def _pytest_command_has_existing_target(command: str, *, project_root: Path) -> bool:
    parts = str(command or "").strip().split()
    if parts[:3] == ["python", "-m", "pytest"]:
        pytest_args = parts[3:]
    elif parts and parts[0] == "pytest":
        pytest_args = parts[1:]
    else:
        return False
    saw_target = False
    for arg in pytest_args:
        if arg in {"-q", "--quiet"} or arg.startswith("--maxfail="):
            continue
        if arg.startswith("-"):
            return False
        target_path = arg.split("::", 1)[0].replace("\\", "/")
        if not target_path.startswith("tests/") or not target_path.endswith(".py"):
            return False
        saw_target = True
        if not (project_root / target_path).exists():
            return False
    return saw_target


def _release_wrapper_sandbox_command_for_project(project_root: Path | str, preferred_command: str) -> str:
    root = Path(project_root)
    if _pytest_command_has_existing_target(preferred_command, project_root=root):
        return preferred_command
    tests_dir = root / "tests"
    if tests_dir.exists():
        for pattern in ("*probe_test.py", "test_*.py"):
            for candidate in sorted(tests_dir.glob(pattern)):
                try:
                    relative = candidate.relative_to(root).as_posix()
                except ValueError:
                    continue
                command = f"pytest {relative} -q"
                if _pytest_command_has_existing_target(command, project_root=root):
                    return command
    fallback_probe = tests_dir / "release_wrapper_auto_sandbox_probe_test.py"
    try:
        tests_dir.mkdir(parents=True, exist_ok=True)
        if not fallback_probe.exists():
            fallback_probe.write_text(
                "def test_release_wrapper_auto_sandbox_probe():\n"
                "    assert 'release-wrapper'.replace('-', '_') == 'release_wrapper'\n",
                encoding="utf-8",
            )
        command = "pytest tests/release_wrapper_auto_sandbox_probe_test.py -q"
        if _pytest_command_has_existing_target(command, project_root=root):
            return command
    except OSError:
        pass
    return preferred_command


