def release_wrapper_runtime_summary_from_artifacts(
    artifacts_dir: Path | str | None,
    *,
    session_id: str | None = None,
) -> dict[str, Any]:
    if artifacts_dir is None:
        return _empty_summary(session_id=session_id)
    summary_path = Path(artifacts_dir) / "release-wrapper-runtime" / "summary.json"
    try:
        summary = json.loads(summary_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return _empty_summary(session_id=session_id)
    if session_id:
        summary["session_id"] = session_id
    return summary


