    def _record_developmental_cortex_assessment(
        self,
        *,
        session_id: str,
        interaction: dict[str, Any],
        stage_results: dict[str, dict[str, Any]],
    ) -> dict[str, Any] | None:
        service = self.developmental_cortex
        if service is None or not hasattr(service, "assess"):
            return None
        trace_id = str(interaction.get("trace_id") or interaction.get("hive_run_id") or "wrapper-interaction")
        safe_trace = _safe_ref(trace_id)
        evidence_refs = [
            f"trace::{safe_trace}",
            f"knowledge::{_safe_ref(str(interaction.get('knowledge_ref') or 'unknown'))}",
        ]
        for key, prefix in (
            ("hive_run_id", "hive-forward"),
            ("federated_packet_id", "federated-packet"),
            ("production_spine_packet_signature", "production-spine-packet"),
            ("ao_execution_receipt_id", "ao-execution"),
            ("cache_ledger_entry_id", "cache-ledger-entry"),
        ):
            value = interaction.get(key)
            if value:
                evidence_refs.append(f"{prefix}::{_safe_ref(str(value))}")
        for stage in stage_results.values():
            for ref in stage.get("evidence_refs") or []:
                if ref:
                    evidence_refs.append(_safe_ref(str(ref)) if "::" not in str(ref) else str(ref))
        evidence_refs = list(dict.fromkeys(evidence_refs))
        blocked_count = sum(
            1
            for stage in stage_results.values()
            if str(stage.get("status") or "") not in {"covered", "pass", "ok", "ready"}
        )
        request_id = f"release-wrapper-developmental::{safe_trace}"
        try:
            assessment = service.assess(
                {
                    "request_id": request_id,
                    "task_ref": "release-wrapper-interaction",
                    "trace_refs": [f"trace::{safe_trace}"],
                    "evidence_refs": evidence_refs,
                    "runtime_state": {
                        "runtime_state": "degraded" if blocked_count else "live-bound",
                        "provider_count": 1 if interaction.get("provider_id") else 0,
                        "route_count": 1 if interaction.get("expert_node") else 0,
                        "blocked_count": blocked_count,
                        "status": "blocked" if blocked_count else "covered",
                    },
                    "memory_state": {
                        "runtime_state": "live-bound",
                        "record_count": 1 if interaction.get("knowledge_ref") else 0,
                    },
                    "authority_state": {
                        "runtime_state": "live-bound",
                        "grant_count": 1 if interaction.get("selected_ao") or interaction.get("ao_execution_receipt_id") else 0,
                    },
                    "eval_state": {
                        "runtime_state": "live-bound",
                        "suite_count": len(stage_results),
                    },
                }
            )
        except Exception as exc:  # pragma: no cover - defensive subsystem boundary
            interaction["developmental_cortex_status"] = "degraded"
            stage_results["developmental_cortex"] = _degraded_forward_pass_stage("developmental_cortex", exc)
            return None
        interaction["developmental_cortex_assessment_ref"] = assessment.get("request_id")
        interaction["developmental_cortex_status"] = assessment.get("status")
        compact_contract_assessment = _compact_developmental_release_contract_assessment(assessment)
        if compact_contract_assessment is not None:
            interaction["developmental_release_contract_assessment"] = compact_contract_assessment
        growth_candidate = assessment.get("growth_candidate") if isinstance(assessment.get("growth_candidate"), dict) else {}
        promotion_case = assessment.get("promotion_case") if isinstance(assessment.get("promotion_case"), dict) else {}
        if growth_candidate.get("candidate_id"):
            interaction["developmental_cortex_growth_candidate_ref"] = growth_candidate.get("candidate_id")
        if promotion_case.get("case_id"):
            interaction["developmental_cortex_promotion_case_ref"] = promotion_case.get("case_id")
        stage_results["developmental_cortex"] = {
            "status": "covered",
            "evidence_refs": [
                ref
                for ref in [
                    f"developmental-cortex::{_safe_ref(str(assessment.get('request_id') or request_id))}",
                    f"growth-candidate::{_safe_ref(str(growth_candidate.get('candidate_id')))}"
                    if growth_candidate.get("candidate_id")
                    else "",
                    f"promotion-case::{_safe_ref(str(promotion_case.get('case_id')))}"
                    if promotion_case.get("case_id")
                    else "",
                ]
                if ref
            ],
            "blocker": "",
        }
        return assessment

    def record_self_repair_action(
        self,
        *,
        update_id: str,
        action: str,
        result: dict[str, Any],
        endpoint_ref: str | None = None,
    ) -> dict[str, Any]:
        proposal = self._autonomous_update_proposal(update_id)
        session_ref_digest = self._self_repair_session_ref_digest(proposal)
        created_at = utcnow().isoformat()
        ao_guard = _compact_self_repair_ao_guard(
            result.get("release_wrapper_ao_guard") if isinstance(result, dict) else None
        )
        evidence_refs = _self_repair_evidence_refs(result, endpoint_ref=endpoint_ref)
        authority_decision = self._self_repair_authority_decision(
            update_id=update_id,
            action=action,
            proposal=proposal,
            result=result,
            evidence_refs=evidence_refs,
        )
        if authority_decision and authority_decision.get("action_id"):
            evidence_refs.append(f"authority_decision::{authority_decision['action_id']}")
        observed_status = _self_repair_status(action, result)
        operation_receipt = _build_runtime_operation_receipt(
            operation_type="self_repair_action",
            operation_ref=f"self-repair::{_safe_ref(update_id)}::{_safe_ref(action)}",
            observed_status=observed_status,
            session_ref_digest=session_ref_digest,
            action=action,
            stages={
                "ao_guard": {
                    "status": "covered" if isinstance(ao_guard, dict) and ao_guard.get("passed") is True else "degraded",
                    "evidence_refs": [f"ao-guard::{ref}" for ref in (ao_guard or {}).get("receipt_refs", [])],
                    "blocker": "" if isinstance(ao_guard, dict) and ao_guard.get("passed") is True else "ao_guard_missing_or_blocked",
                },
                "authority_decision": {
                    "status": "covered"
                    if isinstance(authority_decision, dict)
                    and authority_decision.get("status") in {"allowed", "allowed-shadow", "approved", "pass"}
                    else "degraded",
                    "evidence_refs": _compact_refs(authority_decision, ["action_id", "status"]),
                    "blocker": ""
                    if isinstance(authority_decision, dict)
                    and authority_decision.get("status") in {"allowed", "allowed-shadow", "approved", "pass"}
                    else "authority_decision_missing_or_blocked",
                },
                "sandbox_boundary": {
                    "status": "covered" if _self_repair_sandbox_boundary_ok(action, result) else "degraded",
                    "evidence_refs": _self_repair_sandbox_evidence_refs(result),
                    "blocker": "" if _self_repair_sandbox_boundary_ok(action, result) else "sandbox_boundary_missing_or_failed",
                },
                "active_production_mutation": {
                    "status": "covered" if _self_repair_active_production_mutated(result) is False else "degraded",
                    "evidence_refs": [endpoint_ref or f"self-repair::{_safe_ref(action)}"],
                    "blocker": ""
                    if _self_repair_active_production_mutated(result) is False
                    else "active_production_mutation_detected",
                },
            },
            active_production_mutated=_self_repair_active_production_mutated(result),
        )
        evidence_refs.append(f"operation-receipt::{operation_receipt['receipt_id']}")
        record = {
            "schema_version": "nexusnet-release-wrapper-self-repair-ledger-v1",
            "surface_id": "release-wrapper-self-repair-ledger",
            "repair_run_id": f"self-repair::{_safe_ref(update_id)}::{_safe_ref(action)}::{_privacy_digest(created_at)}",
            "created_at": created_at,
            "update_id": update_id,
            "action": action,
            "status": observed_status,
            "session_ref_digest": session_ref_digest,
            "evidence_refs": evidence_refs,
            "operation_receipt": operation_receipt,
            "active_production_mutated": _self_repair_active_production_mutated(result),
            "raw_content_included": False,
            "ao_guard_required": True,
            "ao_guard": ao_guard,
            "ao_guard_receipts": ao_guard.get("receipts", []) if ao_guard else [],
            "authority_decision": authority_decision,
            "authority_effect_receipt": (
                authority_decision.get("observed_effect_receipt")
                if isinstance(authority_decision, dict)
                else None
            ),
            "authority_rollback_record": (
                authority_decision.get("rollback_record")
                if isinstance(authority_decision, dict)
                else None
            ),
            "mutation_boundary": "admin-approved-shadow-safe-file-only-no-active-production-mutation",
            "privacy_boundary": "sanitized-update-session-digests-and-evidence-refs-only-no-raw-prompts-outputs-session-ids",
        }
        self._self_repair_actions.append(record)
        self._self_repair_actions = self._self_repair_actions[-100:]
        if self._self_repair_replay_status.get("status") == "no-persisted-repair-actions":
            self._self_repair_replay_status["status"] = "recording-live"
        self._self_repair_replay_status["repair_count"] = len(self._self_repair_actions)
        import_governance_backfill = self._backfill_federated_import_governed_update_path(
            update_id=update_id,
            action_records=[
                action_record
                for action_record in self._self_repair_actions
                if str(action_record.get("update_id") or "") == update_id
            ],
        )
        if import_governance_backfill.get("status") != "skipped-no-federated-import":
            record["federated_import_governance_backfill"] = import_governance_backfill
        self._persist_self_repair_action(record)
        return record

    def _self_repair_authority_decision(
        self,
        *,
        update_id: str,
        action: str,
        proposal: dict[str, Any] | None,
        result: dict[str, Any],
        evidence_refs: list[str],
    ) -> dict[str, Any] | None:
        if self.authority_spine is None or not hasattr(self.authority_spine, "evaluate"):
            return None
        action_id = (
            f"release-wrapper-self-repair::{_safe_ref(update_id)}::"
            f"{_safe_ref(action)}::{_privacy_digest('|'.join(evidence_refs))}"
        )
        decision = self.authority_spine.evaluate(
            action_id=action_id,
            actor_ref="release-wrapper-self-repair",
            effect_type="filesystem_write",
            capability_refs=[
                "capability::release-wrapper-self-repair",
                f"capability::release-wrapper-self-repair::{_safe_ref(action)}",
                "capability::autonomous-update-safe-file",
            ],
            sandbox_state=_self_repair_authority_sandbox_state(action, result),
            operator_approved=_self_repair_operator_approved(action, proposal, result),
            evidence_refs=evidence_refs,
            observed_effect_type="filesystem_write",
            rollback_available=_self_repair_rollback_available(proposal, result),
            rollback_ref=_self_repair_authority_rollback_ref(proposal, result),
        )
        allowed = {
            "surface_id",
            "action_id",
            "actor_ref",
            "effect_type",
            "status",
            "blockers",
            "capability_refs",
            "sandbox_state",
            "operator_approved",
            "evidence_refs",
            "observed_effect_receipt",
            "rollback_record",
            "production_action_allowed",
        }
        return {key: decision.get(key) for key in allowed if key in decision}

    def record_release_readiness_evidence_run(
        self,
        *,
        session_id: str,
        update_id: str,
        command: str,
        actions: dict[str, dict[str, Any]],
        status: str = "completed",
        subsystem_repair_envelopes: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        session_ref_digest = _session_ref_digest(session_id)
        created_at = utcnow().isoformat()
        compact_actions = {
            action: _compact_release_readiness_runner_action(result)
            for action, result in actions.items()
            if isinstance(result, dict)
        }
        readiness_after = self.release_readiness_manifest(session_id=session_id)
        readiness_checks = (
            readiness_after.get("readiness_checks")
            if isinstance(readiness_after.get("readiness_checks"), list)
            else []
        )
        active_production_mutated = any(
            bool(action.get("active_production_mutated"))
            for action in compact_actions.values()
            if isinstance(action, dict)
        )
        run = {
            "schema_version": "nexusnet-release-wrapper-readiness-evidence-run-v1",
            "surface_id": "release-wrapper-readiness-evidence-run",
            "run_id": f"release-readiness-run::{_safe_ref(update_id)}::{_privacy_digest(created_at)}",
            "created_at": created_at,
            "status": status,
            "update_id": _safe_ref(update_id),
            "session_ref_digest": session_ref_digest,
            "command": str(command),
            "command_ref": f"pytest::{_privacy_digest(str(command))}",
            "actions": compact_actions,
            "subsystem_repair_envelopes": (
                [dict(envelope) for envelope in subsystem_repair_envelopes]
                if isinstance(subsystem_repair_envelopes, list)
                else []
            ),
            "subsystem_repair_envelope_count": (
                len(subsystem_repair_envelopes) if isinstance(subsystem_repair_envelopes, list) else 0
            ),
            "readiness_after": {
                "surface_id": readiness_after.get("surface_id") or "release-wrapper-readiness",
                "go_no_go": readiness_after.get("go_no_go") or "no-go",
                "passed_check_count": sum(1 for check in readiness_checks if check.get("status") == "pass"),
                "blocked_check_count": sum(1 for check in readiness_checks if check.get("status") != "pass"),
                "artifact_path": readiness_after.get("artifact_path"),
            },
            "active_production_mutated": active_production_mutated,
            "raw_content_included": False,
            "mutation_boundary": "admin-approved-shadow-eval-sandbox-safe-file-apply-rollback-only",
            "privacy_boundary": "sanitized-action-statuses-and-evidence-refs-only-no-raw-prompts-outputs-session-ids",
        }
        artifact_path = self.runtime_dir / f"{_safe_ref(run['run_id'])}.json"
        run["artifact_path"] = str(artifact_path)
        import_governance_backfill = self._backfill_federated_import_governed_update_path(
            update_id=update_id,
            run=run,
        )
        if import_governance_backfill.get("status") != "skipped-no-federated-import":
            run["federated_import_governance_backfill"] = import_governance_backfill
        artifact_path.write_text(json.dumps(run, indent=2, sort_keys=True), encoding="utf-8")
        self._release_readiness_evidence_runs.append(run)
        self._release_readiness_evidence_runs = self._release_readiness_evidence_runs[-100:]
        self._persist_release_readiness_evidence_run(run)
        return run

    def _backfill_federated_import_governed_update_path(
        self,
        *,
        update_id: str,
        run: dict[str, Any] | None = None,
        action_records: list[dict[str, Any]] | None = None,
    ) -> dict[str, Any]:
        proposal = self._autonomous_update_proposal(update_id)
        metadata = proposal.get("metadata") if isinstance((proposal or {}).get("metadata"), dict) else {}
        safe_payload = metadata.get("safe_payload") if isinstance(metadata.get("safe_payload"), dict) else {}
        import_id = str(
            metadata.get("federated_packet_import_id")
            or safe_payload.get("federated_packet_import_id")
            or ""
        )
        source_packet_ref = str(metadata.get("source_packet_ref") or safe_payload.get("source_packet_ref") or "")
        if not import_id:
            return {
                "status": "skipped-no-federated-import",
                "update_id": _safe_ref(update_id),
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        record = next(
            (
                candidate
                for candidate in self._federated_packet_imports
                if str(candidate.get("import_id") or "") == import_id
            ),
            None,
        )
        if record is None:
            return {
                "status": "skipped-import-not-found",
                "update_id": _safe_ref(update_id),
                "federated_packet_import_id": import_id,
                "source_packet_ref": source_packet_ref or None,
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        receipt = (
            record.get("whole_system_enforcement_receipt")
            if isinstance(record.get("whole_system_enforcement_receipt"), dict)
            else _build_federated_import_whole_system_enforcement_receipt(
                record=record,
                operation_receipt=record.get("operation_receipt")
                if isinstance(record.get("operation_receipt"), dict)
                else {},
            )
        )
        backfill = apply_federated_import_governed_update_path(
            update_id=update_id,
            import_id=import_id,
            source_packet_ref=source_packet_ref,
            record=record,
            receipt=receipt,
            run=run,
            action_records=action_records,
        )
        self._persist_federated_packet_import(record)
        return backfill

    def _improvement_queue_transition_plan(self, current_status: str, target_status: str) -> list[str]:
        if current_status in {"rejected", "reverted"} or current_status == target_status:
            return []
        forward = ["proposed", "validated", "approved", "deployed", "monitored"]
        if target_status == "reverted":
            if current_status in {"monitored", "deployed", "approved"}:
                return ["reverted"]
            if current_status in forward:
                current_index = forward.index(current_status)
                approved_index = forward.index("approved")
                return [*forward[current_index + 1 : approved_index + 1], "reverted"]
            return []
        if current_status not in forward or target_status not in forward:
            return []
        current_index = forward.index(current_status)
        target_index = forward.index(target_status)
        if target_index <= current_index:
            return []
        return forward[current_index + 1 : target_index + 1]

    def _sync_linked_improvement_queue(
        self,
        update_id: str,
        *,
        target_status: str,
        actor: str,
        reason: str,
    ) -> dict[str, Any]:
        proposal = self._autonomous_update_proposal(update_id)
        metadata = proposal.get("metadata") if isinstance((proposal or {}).get("metadata"), dict) else {}
        queue_id = str(metadata.get("improvement_queue_id") or "")
        if not queue_id:
            return {
                "status": "not-linked",
                "update_id": update_id,
                "queue_id": None,
                "target_status": target_status,
            }
        if self.improvement_queue is None:
            return {
                "status": "queue-not-configured",
                "update_id": update_id,
                "queue_id": queue_id,
                "target_status": target_status,
            }
        queue = ImprovementQueue(self.improvement_queue.storage_path)
        try:
            item = queue.get(queue_id)
        except KeyError:
            return {
                "status": "missing-queue-item",
                "update_id": update_id,
                "queue_id": queue_id,
                "target_status": target_status,
            }
        from_status = item.status
        transition_path = self._improvement_queue_transition_plan(str(item.status), target_status)
        for status in transition_path:
            item = queue.transition(
                queue_id,
                status,  # type: ignore[arg-type]
                actor=actor,
                reason=f"{reason}; autonomous_update={update_id}",
            )
        return {
            "status": "transitioned" if item.status != from_status else "unchanged",
            "update_id": update_id,
            "queue_id": queue_id,
            "from_status": from_status,
            "queue_status": item.status,
            "target_status": target_status,
            "transition_path": transition_path,
        }

    def _run_linked_eval_replay(self, update_id: str) -> dict[str, Any]:
        proposal = self._autonomous_update_proposal(update_id)
        if proposal is None:
            return {"status": "not-linked", "update_id": update_id, "reason": "proposal-not-found"}
        if self.eval_registry is None or not hasattr(self.eval_registry, "summary") or not hasattr(
            self.eval_registry,
            "run_shadow",
        ):
            return {"status": "not-configured", "update_id": update_id, "reason": "eval-registry-unavailable"}
        eval_refs = [str(ref) for ref in (proposal.get("eval_refs") or [])]
        proposal_metadata = proposal.get("metadata") if isinstance(proposal.get("metadata"), dict) else {}
        safe_payload = (
            proposal_metadata.get("safe_payload") if isinstance(proposal_metadata.get("safe_payload"), dict) else {}
        )
        federated_import_shadow = bool(
            proposal_metadata.get("federated_import_shadow")
            or proposal_metadata.get("federated_packet_import_id")
            or safe_payload.get("federated_packet_import_id")
        )
        dream_research_queue = bool(
            proposal_metadata.get("dream_research_queue")
            or proposal_metadata.get("improvement_queue_id")
        )
        if federated_import_shadow:
            suite_prefixes = (
                "eval::release-wrapper-federated-import::",
                "eval::release-wrapper-dream-research::",
                "eval::release-wrapper-runtime::",
            )
        elif dream_research_queue:
            suite_prefixes = (
                "eval::release-wrapper-dream-research::",
                "eval::release-wrapper-federated-import::",
                "eval::release-wrapper-runtime::",
            )
        else:
            suite_prefixes = (
                "eval::release-wrapper-federated-import::",
                "eval::release-wrapper-runtime::",
                "eval::release-wrapper-dream-research::",
            )
        suite_id = next((ref for prefix in suite_prefixes for ref in eval_refs if ref.startswith(prefix)), None)
        if suite_id is None:
            return {"status": "not-linked", "update_id": update_id, "reason": "no-release-wrapper-eval-suite-ref"}
        registry = self.eval_registry.summary(limit=500)
        suite = next((item for item in registry.get("suites", []) if item.get("suite_id") == suite_id), None)
        if suite is None:
            return {"status": "missing-eval-suite", "update_id": update_id, "suite_id": suite_id}
        metadata = suite.get("metadata") if isinstance(suite.get("metadata"), dict) else {}
        replay_template = metadata.get("replay_template") if isinstance(metadata.get("replay_template"), dict) else {}
        replay_payload = dict(replay_template.get("payload") or {})
        if not replay_payload:
            return {"status": "missing-replay-template", "update_id": update_id, "suite_id": suite_id}
        artifact_gate_refs = [ref for ref in eval_refs if ref.startswith("evals-ao-artifact::")]
        for value in (
            proposal_metadata.get("evals_ao_artifact_gate_ref"),
            safe_payload.get("evals_ao_artifact_gate_ref"),
            metadata.get("gate_id"),
        ):
            gate_ref = str(value or "")
            if gate_ref.startswith("evals-ao-artifact::") and gate_ref not in artifact_gate_refs:
                artifact_gate_refs.append(gate_ref)
        evidence_refs = [str(ref) for ref in (replay_payload.get("evidence_refs") or []) if str(ref or "")]
        evaluator_refs = [str(ref) for ref in (replay_payload.get("evaluator_refs") or []) if str(ref or "")]
        for gate_ref in artifact_gate_refs:
            if gate_ref not in evidence_refs:
                evidence_refs.append(gate_ref)
            if gate_ref not in evaluator_refs:
                evaluator_refs.append(gate_ref)
        if artifact_gate_refs and "ao::EvalsAO" not in evaluator_refs:
            evaluator_refs.append("ao::EvalsAO")
        replay_payload["evidence_refs"] = evidence_refs
        replay_payload["evaluator_refs"] = evaluator_refs
        replay_payload["operator_approved"] = True
        replay_metadata = replay_payload.get("metadata") if isinstance(replay_payload.get("metadata"), dict) else {}
        replay_payload["metadata"] = {
            **replay_metadata,
            "admin_approved_update_id": update_id,
            "approval_trigger": "autonomous-update-admin-approval",
            "evals_ao_artifact_gate_ref": artifact_gate_refs[0] if artifact_gate_refs else None,
            "evals_ao_artifact_gate_refs": artifact_gate_refs,
            "proposal_eval_refs": eval_refs,
        }
        run = self.eval_registry.run_shadow(suite_id, replay_payload)
        return self.autonomous_updates.attach_eval_replay(update_id, run)

    def _record_autonomous_update_governance_lifecycle(
        self,
        *,
        session_id: str,
        update_id: str,
        command: str = DEFAULT_RELEASE_WRAPPER_SANDBOX_COMMAND,
        timeout_seconds: int = 60,
        approved_by: str = "admin",
        approval_ref: str = "operator-review::release-wrapper-runtime-auto-governance",
    ) -> dict[str, Any]:
        if self._autonomous_update_proposal(update_id) is None:
            return {
                "surface_id": "release-wrapper-readiness-evidence-run",
                "status": "blocked-missing-proposal",
                "update_id": update_id,
                "raw_content_included": False,
                "active_production_mutated": False,
            }
        actions: dict[str, dict[str, Any]] = {}
        project_root = self.artifacts_dir.parent.parent
        command = _release_wrapper_sandbox_command_for_project(project_root, command)
        endpoint_ref = f"/ops/brain/autonomous-updates/{update_id}/admin-approval"
        admin_guard = self.guard_self_repair_action(
            update_id=update_id,
            action="admin_approval",
            endpoint_ref=endpoint_ref,
        )
        if admin_guard.get("passed") is not True:
            actions["admin_approval"] = {
                "surface_id": "autonomous-updates",
                "status": "blocked-ao-guard-failed",
                "update_id": update_id,
                "release_wrapper_ao_guard": admin_guard,
                "active_production_mutated": False,
                "raw_content_included": False,
            }
            return self.record_release_readiness_evidence_run(
                session_id=session_id,
                update_id=update_id,
                command=command,
                actions=actions,
                status="blocked-admin-approval-ao-guard",
            )
        approval = self.autonomous_updates.approve(
            update_id,
            approved_by=approved_by,
            approval_ref=approval_ref,
        )
        approval["linked_improvement_queue"] = self._sync_linked_improvement_queue(
            update_id,
            target_status="validated",
            actor="AutonomousUpdateController",
            reason="linked autonomous update received admin approval",
        )
        approval["linked_eval_replay"] = self._run_linked_eval_replay(update_id)
        approval["release_wrapper_ao_guard"] = admin_guard
        approval["release_wrapper_self_repair"] = self.record_self_repair_action(
            update_id=update_id,
            action="admin_approval",
            result=approval,
            endpoint_ref=endpoint_ref,
        )
        actions["admin_approval"] = approval

        endpoint_ref = f"/ops/brain/autonomous-updates/{update_id}/sandbox-tests"
        sandbox_guard = self.guard_self_repair_action(
            update_id=update_id,
            action="sandbox_tests",
            endpoint_ref=endpoint_ref,
        )
        if sandbox_guard.get("passed") is not True:
            actions["sandbox_tests"] = {
                "surface_id": "autonomous-updates",
                "status": "blocked-ao-guard-failed",
                "update_id": update_id,
                "release_wrapper_ao_guard": sandbox_guard,
                "active_production_mutated": False,
                "raw_content_included": False,
            }
            return self.record_release_readiness_evidence_run(
                session_id=session_id,
                update_id=update_id,
                command=command,
                actions=actions,
                status="blocked-sandbox-ao-guard",
            )
        try:
            sandbox = self.autonomous_updates.run_sandbox_tests(
                update_id,
                command=command,
                project_root=project_root,
                timeout_seconds=timeout_seconds,
            )
        except ValueError as exc:
            sandbox = {
                "surface_id": "autonomous-updates",
                "status": "blocked-sandbox-command-invalid",
                "update_id": update_id,
                "passed": False,
                "command": command,
                "blocker": str(exc),
                "release_wrapper_ao_guard": sandbox_guard,
                "active_production_mutated": False,
                "raw_content_included": False,
            }
            sandbox["release_wrapper_self_repair"] = self.record_self_repair_action(
                update_id=update_id,
                action="sandbox_tests",
                result=sandbox,
                endpoint_ref=endpoint_ref,
            )
            actions["sandbox_tests"] = sandbox
            return self.record_release_readiness_evidence_run(
                session_id=session_id,
                update_id=update_id,
                command=command,
                actions=actions,
                status="blocked-sandbox-command-invalid",
            )
        if sandbox.get("passed") is True:
            sandbox["linked_improvement_queue"] = self._sync_linked_improvement_queue(
                update_id,
                target_status="approved",
                actor="AutonomousUpdateController",
                reason="linked autonomous update passed isolated sandbox tests",
            )
        else:
            sandbox["linked_improvement_queue"] = {
                "status": "unchanged",
                "update_id": update_id,
                "target_status": "approved",
                "reason": "sandbox evidence did not pass",
            }
        sandbox["release_wrapper_ao_guard"] = sandbox_guard
        sandbox["release_wrapper_self_repair"] = self.record_self_repair_action(
            update_id=update_id,
            action="sandbox_tests",
            result=sandbox,
            endpoint_ref=endpoint_ref,
        )
        actions["sandbox_tests"] = sandbox
        if sandbox.get("passed") is not True:
            return self.record_release_readiness_evidence_run(
                session_id=session_id,
                update_id=update_id,
                command=command,
                actions=actions,
                status="blocked-sandbox-failed",
            )

        endpoint_ref = f"/ops/brain/autonomous-updates/{update_id}/apply"
        apply_guard = self.guard_self_repair_action(update_id=update_id, action="apply", endpoint_ref=endpoint_ref)
        if apply_guard.get("passed") is not True:
            actions["apply"] = {
                "surface_id": "autonomous-updates",
                "status": "blocked-ao-guard-failed",
                "update_id": update_id,
                "release_wrapper_ao_guard": apply_guard,
                "active_production_mutated": False,
                "raw_content_included": False,
            }
            return self.record_release_readiness_evidence_run(
                session_id=session_id,
                update_id=update_id,
                command=command,
                actions=actions,
                status="blocked-apply-ao-guard",
            )
        evidence_ref = str(sandbox.get("evidence_ref") or "")
        applied = self.autonomous_updates.apply_safe(
            update_id,
            test_refs=[command],
            test_evidence_refs=[evidence_ref] if evidence_ref else [],
            ao_guard=apply_guard,
        )
        applied["linked_improvement_queue"] = self._sync_linked_improvement_queue(
            update_id,
            target_status="deployed",
            actor="AutonomousUpdateController",
            reason="linked autonomous update applied as shadow safe file",
        )
        applied["release_wrapper_ao_guard"] = apply_guard
        applied["release_wrapper_self_repair"] = self.record_self_repair_action(
            update_id=update_id,
            action="apply",
            result=applied,
            endpoint_ref=endpoint_ref,
        )
        actions["apply"] = applied

        endpoint_ref = f"/ops/brain/autonomous-updates/{update_id}/rollback"
        rollback_guard = self.guard_self_repair_action(
            update_id=update_id,
            action="rollback",
            endpoint_ref=endpoint_ref,
        )
        if rollback_guard.get("passed") is not True:
            actions["rollback"] = {
                "surface_id": "autonomous-updates",
                "status": "blocked-ao-guard-failed",
                "update_id": update_id,
                "release_wrapper_ao_guard": rollback_guard,
                "active_production_mutated": False,
                "raw_content_included": False,
            }
            return self.record_release_readiness_evidence_run(
                session_id=session_id,
                update_id=update_id,
                command=command,
                actions=actions,
                status="blocked-rollback-ao-guard",
            )
        rollback = self.autonomous_updates.rollback(
            update_id,
            reason="release-readiness-runner-rollback-verification",
        )
        rollback["linked_improvement_queue"] = self._sync_linked_improvement_queue(
            update_id,
            target_status="reverted",
            actor="AutonomousUpdateController",
            reason="linked autonomous update rollback restored previous safe file",
        )
        rollback["release_wrapper_ao_guard"] = rollback_guard
        rollback["release_wrapper_self_repair"] = self.record_self_repair_action(
            update_id=update_id,
            action="rollback",
            result=rollback,
            endpoint_ref=endpoint_ref,
        )
        actions["rollback"] = rollback
        return self.record_release_readiness_evidence_run(
            session_id=session_id,
            update_id=update_id,
            command=command,
            actions=actions,
            status="completed",
        )

    def guard_self_repair_action(
        self,
        *,
        update_id: str,
        action: str,
        endpoint_ref: str | None = None,
    ) -> dict[str, Any]:
        proposal = self._autonomous_update_proposal(update_id)
        session_ref_digest = self._self_repair_session_ref_digest(proposal)
        created_at = utcnow().isoformat()
        required_aos = list(SELF_REPAIR_GUARD_AOS)
        receipts: list[dict[str, Any]] = []
        missing_aos: list[str] = []
        registry = self.ao_registry
        if registry is None or not hasattr(registry, "record_execution") or not hasattr(registry, "get"):
            missing_aos = list(required_aos)
        else:
            for ao_name in required_aos:
                if registry.get(ao_name) is None:
                    missing_aos.append(ao_name)
                    continue
                plan = AOPlan(
                    ao_name=ao_name,
                    reason=(
                        f"{ao_name} guard recorded for release wrapper self repair action "
                        f"'{action}' before admin-controlled update mutation."
                    ),
                    risk_tier="high",
                    goals=[
                        "preserve admin approval discipline",
                        "verify sandbox and eval evidence",
                        "prevent active production mutation outside safe apply",
                    ],
                    responsibilities=[
                        "admin approval",
                        "sandbox boundary",
                        "rollback evidence",
                        "sanitized guard receipt",
                    ],
                )
                trace_id = (
                    f"self-repair-guard::{_safe_ref(update_id)}::{_safe_ref(action)}::"
                    f"{_safe_ref(ao_name)}::{_privacy_digest(created_at)}"
                )
                receipt = registry.record_execution(
                    session_id=f"self-repair::{session_ref_digest or _safe_ref(update_id)}",
                    trace_id=trace_id,
                    plan=plan,
                    selected_expert="release-wrapper-self-repair",
                    selected_teacher_id=None,
                    wrapper_mode=f"self-repair::{action}",
                    session_ref_digest=session_ref_digest,
                )
                receipts.append(_compact_ao_execution_receipt(receipt))
        received_aos = [str(receipt.get("ao_name") or "") for receipt in receipts if receipt.get("ao_name")]
        missing_aos = [ao_name for ao_name in required_aos if ao_name not in received_aos]
        return {
            "surface_id": "release-wrapper-ao-guard",
            "status_label": "LOCKED CANON",
            "update_id": update_id,
            "action": action,
            "endpoint_ref": endpoint_ref,
            "created_at": created_at,
            "session_ref_digest": session_ref_digest,
            "required_aos": required_aos,
            "received_aos": received_aos,
            "missing_aos": missing_aos,
            "passed": not missing_aos,
            "receipt_refs": [str(receipt.get("execution_id") or "") for receipt in receipts if receipt.get("execution_id")],
            "receipts": receipts,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "mutation_boundary": "admin-approved-shadow-safe-file-only-no-active-production-mutation",
            "privacy_boundary": "sanitized-ao-receipts-only-no-raw-prompts-outputs-session-ids-or-artifact-paths",
        }

    def self_repair_ledger(self, *, session_ref_digest: str | None = None) -> dict[str, Any]:
        actions = [
            action
            for action in self._self_repair_actions
            if not session_ref_digest or str(action.get("session_ref_digest") or "") == session_ref_digest
        ]
        latest = actions[-1] if actions else None
        action_counts: dict[str, int] = {}
        for action in actions:
            action_name = str(action.get("action") or "unknown")
            action_counts[action_name] = action_counts.get(action_name, 0) + 1
        guarded_actions = [
            action
            for action in actions
            if isinstance(action.get("ao_guard"), dict) and action["ao_guard"].get("passed") is True
        ]
        authority_decisions = [
            action["authority_decision"]
            for action in actions
            if isinstance(action.get("authority_decision"), dict)
        ]
        replay = dict(self._self_repair_replay_status)
        replay["repair_count"] = len(actions)
        replay["global_repair_count"] = len(self._self_repair_actions)
        replay["artifact_ref"] = "release-wrapper-runtime/self-repair-ledger.jsonl"
        replay["artifact_path_digest"] = f"sha256:{_privacy_digest(str(self.self_repair_log_path))}"
        return {
            "surface_id": "release-wrapper-self-repair-ledger",
            "status_label": "LOCKED CANON",
            "scope": "session" if session_ref_digest else "global",
            "session_ref_digest": session_ref_digest,
            "repair_count": len(actions),
            "global_repair_count": len(self._self_repair_actions),
            "latest_action": latest.get("action") if isinstance(latest, dict) else None,
            "latest_status": latest.get("status") if isinstance(latest, dict) else None,
            "action_counts": action_counts,
            "actions": actions[-20:],
            "ao_guard_required": True,
            "ao_guard_passed_count": len(guarded_actions),
            "latest_ao_guard": latest.get("ao_guard") if isinstance(latest, dict) else None,
            "authority_decision_count": len(authority_decisions),
            "latest_authority_decision": (
                latest.get("authority_decision")
                if isinstance(latest, dict) and isinstance(latest.get("authority_decision"), dict)
                else None
            ),
            "replay": replay,
            "artifact_ref": "release-wrapper-runtime/self-repair-ledger.jsonl",
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.self_repair_log_path))}",
            "active_production_mutated": any(
                bool(action.get("active_production_mutated")) for action in actions
            ),
            "raw_content_included": False,
            "mutation_boundary": "admin-approved-shadow-safe-file-only-no-active-production-mutation",
            "privacy_boundary": "sanitized-update-session-digests-and-evidence-refs-only-no-raw-prompts-outputs-session-ids",
        }

    def release_readiness_evidence_runner(self, *, session_ref_digest: str | None = None) -> dict[str, Any]:
        runs = [
            run
            for run in self._release_readiness_evidence_runs
            if not session_ref_digest or str(run.get("session_ref_digest") or "") == session_ref_digest
        ]
        latest = runs[-1] if runs else None
        latest_heartbeat_repair = next(
            (
                run
                for run in reversed(runs)
                if str(run.get("status") or "").endswith("heartbeat-supervisor-repair")
            ),
            None,
        )
        latest_whole_system_heartbeat_repair = next(
            (
                run
                for run in reversed(runs)
                if str(run.get("status") or "").endswith("whole-system-heartbeat-repair")
            ),
            None,
        )
        latest_autonomous_lifecycle = next(
            (
                run
                for run in reversed(runs)
                if str(run.get("status") or "") == "completed"
                and isinstance(run.get("actions"), dict)
                and {"admin_approval", "sandbox_tests", "apply", "rollback"}.issubset(
                    set((run.get("actions") or {}).keys())
                )
            ),
            None,
        )
        return {
            "surface_id": "release-wrapper-readiness-evidence-runner",
            "status_label": "LOCKED CANON",
            "runner_ref": "/ops/wrapper/release-readiness/run",
            "scope": "session" if session_ref_digest else "global",
            "session_ref_digest": session_ref_digest,
            "run_count": len(runs),
            "global_run_count": len(self._release_readiness_evidence_runs),
            "latest_status": latest.get("status") if isinstance(latest, dict) else "not-run",
            "latest_run": latest,
            "latest_heartbeat_supervisor_repair_status": (
                latest_heartbeat_repair.get("status") if isinstance(latest_heartbeat_repair, dict) else "not-run"
            ),
            "latest_heartbeat_supervisor_repair_run_id": (
                latest_heartbeat_repair.get("run_id") if isinstance(latest_heartbeat_repair, dict) else None
            ),
            "latest_heartbeat_supervisor_repair_update_id": (
                latest_heartbeat_repair.get("update_id") if isinstance(latest_heartbeat_repair, dict) else None
            ),
            "latest_whole_system_heartbeat_repair_status": (
                latest_whole_system_heartbeat_repair.get("status")
                if isinstance(latest_whole_system_heartbeat_repair, dict)
                else "not-run"
            ),
            "latest_whole_system_heartbeat_repair_run_id": (
                latest_whole_system_heartbeat_repair.get("run_id")
                if isinstance(latest_whole_system_heartbeat_repair, dict)
                else None
            ),
            "latest_whole_system_heartbeat_repair_update_id": (
                latest_whole_system_heartbeat_repair.get("update_id")
                if isinstance(latest_whole_system_heartbeat_repair, dict)
                else None
            ),
            "latest_whole_system_heartbeat_repair_run": latest_whole_system_heartbeat_repair,
            "latest_autonomous_update_lifecycle_status": (
                latest_autonomous_lifecycle.get("status") if isinstance(latest_autonomous_lifecycle, dict) else "not-run"
            ),
            "latest_autonomous_update_lifecycle_run_id": (
                latest_autonomous_lifecycle.get("run_id") if isinstance(latest_autonomous_lifecycle, dict) else None
            ),
            "latest_autonomous_update_lifecycle_update_id": (
                latest_autonomous_lifecycle.get("update_id") if isinstance(latest_autonomous_lifecycle, dict) else None
            ),
            "latest_autonomous_update_lifecycle_run": latest_autonomous_lifecycle,
            "artifact_ref": "release-wrapper-runtime/release-readiness-evidence-runs.jsonl",
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.release_readiness_evidence_log_path))}",
            "active_production_mutated": any(
                bool(run.get("active_production_mutated")) for run in runs if isinstance(run, dict)
            ),
            "raw_content_included": False,
            "mutation_boundary": "admin-approved-shadow-eval-sandbox-safe-file-apply-rollback-only",
            "privacy_boundary": "sanitized-action-statuses-and-evidence-refs-only-no-raw-prompts-outputs-session-ids",
        }

    def first_run_readiness(self, *, session_id: str | None = None) -> dict[str, Any]:
        session_ref_digest = _session_ref_digest(session_id)
        interactions = self._interactions_for_session(session_ref_digest)
        session_history = self._session_history_summary(
            session_ref_digest=session_ref_digest,
            interactions=interactions,
        )
        provider_readiness = self._provider_readiness_summary(
            interactions=interactions,
            session_ref_digest=session_ref_digest,
        )
        continuous_status = self.continuous_assimilation.status()
        global_growth = self.global_growth.growth_status()
        packets = self._federated_packets_for_interactions(interactions)
        autonomous_updates = _filter_autonomous_updates_summary(
            self.autonomous_updates.summary(limit=20),
            session_ref_digest=session_ref_digest,
        )
        dream_queue = self._dream_research_queue_summary(session_ref_digest=session_ref_digest)
        release_readiness_evidence_runner = self.release_readiness_evidence_runner(
            session_ref_digest=session_ref_digest
        )
        native_runtime_growth_governance = _native_runtime_growth_governance_summary(
            autonomous_updates=autonomous_updates,
            dream_queue=dream_queue,
            release_readiness_evidence_runner=release_readiness_evidence_runner,
        )
        latest_interaction = interactions[0] if interactions else {}
        latest_run = self._latest_first_run_readiness_run(session_ref_digest=session_ref_digest)
        model_cache_root = self.artifacts_dir.parent / "model-cache"
        download_cache_root = self.artifacts_dir.parent / "download-cache"
        cycle_token = session_ref_digest or "global"
        target_node_ref = str(latest_interaction.get("expert_node") or "expert.wrapper")
        production_scorecard: dict[str, Any] = {}
        if self.production_spine is not None and hasattr(self.production_spine, "scorecard"):
            try:
                production_scorecard = self.production_spine.scorecard()
            except Exception:
                production_scorecard = {}
        production_first_run_template = (
            production_scorecard.get("first_run_readiness_request_template")
            if isinstance(production_scorecard.get("first_run_readiness_request_template"), dict)
            else {}
        )
        production_first_run_request = (
            production_first_run_template.get("template")
            if isinstance(production_first_run_template.get("template"), dict)
            else {}
        )
        use_production_spine_template = bool(
            production_first_run_request.get("cycle_id")
            and production_first_run_request.get("student_id")
            and production_first_run_request.get("target_node_ref")
        )
        gates = {
            "wrapper_entrypoint_ready": True,
            "provider_pool_visible": int(provider_readiness.get("provider_count") or 0) > 0,
            "local_provider_usable": int(provider_readiness.get("usable_provider_count") or 0) > 0,
            "live_interaction_seen": int(session_history.get("event_count") or 0) > 0,
            "continuous_assimilation_ready": bool(continuous_status.get("nodes")),
            "global_growth_ready": int(global_growth.get("global_captures") or 0) > 0,
            "federated_packet_ready": len(packets) > 0,
            "release_readiness_visible": True,
            "native_runtime_growth_governance_ready": _native_runtime_growth_governance_ready(
                native_runtime_growth_governance
            ),
            "local_cache_controls_ready": bool(
                production_first_run_request.get("local_cache_controls_ready")
                if use_production_spine_template
                else True
            ),
            "model_download_manager_ready": bool(
                production_first_run_request.get("model_download_manager_ready")
                if use_production_spine_template
                else int(provider_readiness.get("provider_count") or 0) > 0
            ),
            "buyer_launcher_ready": bool(
                production_first_run_request.get("buyer_launcher_ready")
                if use_production_spine_template
                else True
            ),
            "support_bundle_ready": bool(production_first_run_request.get("support_bundle_ready"))
            if use_production_spine_template
            else False,
            "crash_diagnostics_ready": bool(production_first_run_request.get("crash_diagnostics_ready"))
            if use_production_spine_template
            else False,
            "project_local_signing_key_ready": bool(production_first_run_request.get("project_local_signing_key_ready"))
            if use_production_spine_template
            else False,
            "buyer_safe_defaults": bool(
                production_first_run_request.get("buyer_safe_defaults")
                if use_production_spine_template
                else True
            ),
            "adapter_artifact_trust_clear": bool(production_first_run_request.get("adapter_artifact_trust_clear"))
            if use_production_spine_template
            else False,
            "operator_approved": bool(production_first_run_request.get("operator_approved"))
            if use_production_spine_template
            else False,
        }
        wrapper_gate_fields = (
            "wrapper_entrypoint_ready",
            "provider_pool_visible",
            "local_provider_usable",
            "live_interaction_seen",
            "continuous_assimilation_ready",
            "global_growth_ready",
            "federated_packet_ready",
            "release_readiness_visible",
            "native_runtime_growth_governance_ready",
        )
        production_gate_fields = (
            "support_bundle_ready",
            "crash_diagnostics_ready",
            "project_local_signing_key_ready",
            "adapter_artifact_trust_clear",
            "operator_approved",
        )
        missing_proof_fields = sorted(field for field, passed in gates.items() if not passed)
        if any(not gates[field] for field in wrapper_gate_fields):
            decision = "blocked-wrapper-evidence-missing"
        elif any(not gates[field] for field in production_gate_fields):
            decision = "blocked-first-run-proofs-missing"
        else:
            decision = "operator-review-ready"
        if use_production_spine_template:
            production_request = json.loads(json.dumps(production_first_run_request))
            production_request["include_raw_private_data"] = False
            production_request["workspace_paths_redacted"] = True
            production_request["redact_secrets"] = True
            production_request["operator_approved"] = gates["operator_approved"]
            source_refs = production_request.get("source_refs") if isinstance(production_request.get("source_refs"), dict) else {}
            production_request["source_refs"] = {
                **source_refs,
                "production_spine_scorecard": "/ops/brain/canon/production-spine",
                "production_spine_first_run_readiness": "/ops/brain/production-spine/first-run-readiness",
                "wrapper_runtime": "/ops/wrapper/release-runtime",
                "wrapper_status": "/ops/wrapper/status-card",
                "native_runtime_growth_governance": "/ops/wrapper/status-card#native_runtime_growth_governance",
                "wrapper_ui": "/ui/wrapper/",
                "first_run_ui": "/ui/first_run.html",
            }
            request_template = {
                "schema_version": production_first_run_template.get("schema_version")
                or "first_run_readiness_request_template.v0.1",
                "endpoint": production_first_run_template.get("endpoint")
                or "/ops/brain/production-spine/first-run-readiness",
                "method": production_first_run_template.get("method") or "POST",
                "ready_to_submit": decision == "operator-review-ready",
                "required_proof_fields": production_first_run_template.get("required_proof_fields") or [],
                "missing_proof_fields": missing_proof_fields,
                "template": production_request,
                "source": "production-spine-scorecard-first-run-template",
                "operator_visible": True,
                "mutation_boundary": production_first_run_template.get("mutation_boundary")
                or "template-only-first-run-readiness-no-installer-or-cache-mutation",
            }
            production_spine_summary = {
                "scorecard_ref": "/ops/brain/canon/production-spine",
                "runtime_state": production_scorecard.get("runtime_state") or "static-canon",
                "cycle_id": production_request.get("cycle_id"),
                "student_id": production_request.get("student_id"),
                "target_node_ref": production_request.get("target_node_ref"),
                "lifecycle_count": int(production_scorecard.get("lifecycle_count") or 0),
                "cycle_count": int(production_scorecard.get("cycle_count") or 0),
                "latest_lifecycle_status": (production_scorecard.get("latest_lifecycle") or {}).get("status")
                if isinstance(production_scorecard.get("latest_lifecycle"), dict)
                else None,
            }
            product_scope = "whole-system"
        else:
            request_template = {
                "schema_version": "first_run_readiness_request_template.v0.1",
                "endpoint": "/ops/brain/production-spine/first-run-readiness",
                "method": "POST",
                "ready_to_submit": decision == "operator-review-ready",
                "missing_proof_fields": missing_proof_fields,
                "template": {
                    "readiness_id": f"first-run:release-wrapper::{cycle_token}",
                    "cycle_id": f"release-wrapper-first-run::{cycle_token}",
                    "student_id": "release-wrapper",
                    "target_node_ref": target_node_ref,
                    "local_cache_controls_ready": gates["local_cache_controls_ready"],
                    "model_download_manager_ready": gates["model_download_manager_ready"],
                    "buyer_launcher_ready": gates["buyer_launcher_ready"],
                    "support_bundle_ready": gates["support_bundle_ready"],
                    "crash_diagnostics_ready": gates["crash_diagnostics_ready"],
                    "docs_complete": True,
                    "buyer_safe_defaults": gates["buyer_safe_defaults"],
                    "adapter_artifact_trust_status": "not_recorded",
                    "adapter_artifact_trust_clear": gates["adapter_artifact_trust_clear"],
                    "project_local_signing_key_ready": gates["project_local_signing_key_ready"],
                    "key_file_path": "",
                    "key_file_storage_scope": "project_local_encrypted_file",
                    "passphrase_persisted": False,
                    "model_cache_root_path": str(model_cache_root),
                    "download_cache_root_path": str(download_cache_root),
                    "support_bundle_path": None,
                    "support_bundle_destination": "",
                    "workspace_paths_redacted": True,
                    "redact_secrets": True,
                    "include_raw_private_data": False,
                    "operator_approved": gates["operator_approved"],
                    "source_refs": {
                        "wrapper_runtime": "/ops/wrapper/release-runtime",
                        "wrapper_status": "/ops/wrapper/status-card",
                        "native_runtime_growth_governance": "/ops/wrapper/status-card#native_runtime_growth_governance",
                        "wrapper_ui": "/ui/wrapper/",
                        "first_run_ui": "/ui/first_run.html",
                        "provider_readiness": "/ops/wrapper/providers",
                        "release_readiness": "/ops/wrapper/release-readiness",
                    },
                },
                "source": "release-wrapper-runtime-first-run-template",
                "operator_visible": True,
                "mutation_boundary": "template-only-first-run-readiness-no-installer-or-cache-mutation",
            }
            production_spine_summary = {
                "scorecard_ref": "/ops/brain/canon/production-spine",
                "runtime_state": production_scorecard.get("runtime_state") or "static-canon",
                "cycle_id": None,
                "student_id": None,
                "target_node_ref": None,
                "lifecycle_count": int(production_scorecard.get("lifecycle_count") or 0),
                "cycle_count": int(production_scorecard.get("cycle_count") or 0),
                "latest_lifecycle_status": None,
            }
            product_scope = "wrapper-session"
        return {
            "schema_version": "nexusnet-release-wrapper-first-run-readiness-v1",
            "surface_id": "release-wrapper-first-run-readiness",
            "generated_at": utcnow().isoformat(),
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "honest_status_label": decision,
            "decision": decision,
            "product_surface": "wrapper",
            "product_scope": product_scope,
            "runtime_state": "live-bound" if interactions else "static-canon",
            "session_ref_digest": session_ref_digest,
            "production_spine": production_spine_summary,
            "native_runtime_growth_governance": native_runtime_growth_governance,
            "entrypoint": {
                "wrapper_ui_ref": "/ui/wrapper/",
                "legacy_first_run_ui_ref": "/ui/first_run.html",
                "runtime_ref": "/ops/wrapper/release-runtime",
                "status_card_ref": "/ops/wrapper/status-card",
            },
            "gates": gates,
            "missing_proof_fields": missing_proof_fields,
            "request_template": request_template,
            "latest_run": latest_run,
            "endpoint_refs": {
                "first_run_readiness": "/ops/wrapper/first-run-readiness",
                "first_run_readiness_run": "/ops/wrapper/first-run-readiness/run",
                "production_spine_first_run_readiness": "/ops/brain/production-spine/first-run-readiness",
                "wrapper": "/ui/wrapper/",
                "first_run_ui": "/ui/first_run.html",
                "runtime": "/ops/wrapper/release-runtime",
                "status_card": "/ops/wrapper/status-card",
            },
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
            "privacy_boundary": "sanitized-first-run-gates-refs-and-digests-only-no-raw-prompts-outputs-session-ids",
        }

    def record_first_run_readiness_run(
        self,
        *,
        session_id: str | None = None,
        request_overrides: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        readiness = self.first_run_readiness(session_id=session_id)
        template = json.loads(json.dumps(readiness["request_template"]["template"]))
        safe_overrides = {
            str(key): value
            for key, value in (request_overrides or {}).items()
            if key
            not in {
                "session_id",
                "raw_private_data",
                "private_data",
                "secrets",
                "environment_variables",
                "passphrase",
                "signing_seed_hex",
            }
        }
        template.update(safe_overrides)
        template["include_raw_private_data"] = False
        template["redact_secrets"] = True
        template["workspace_paths_redacted"] = True
        manifest = self.production_spine.build_first_run_readiness_manifest(template)
        session_ref_digest = _session_ref_digest(session_id)
        created_at = utcnow().isoformat()
        run = {
            "schema_version": "nexusnet-release-wrapper-first-run-readiness-run-v1",
            "surface_id": "release-wrapper-first-run-readiness-run",
            "run_id": f"first-run-readiness-run::{_safe_ref(str(template.get('cycle_id') or 'wrapper'))}::{_privacy_digest(created_at)}",
            "created_at": created_at,
            "status": "manifest-preview-recorded",
            "session_ref_digest": session_ref_digest,
            "request_ref": f"sha256:{_privacy_digest(json.dumps(template, sort_keys=True))}",
            "manifest": manifest,
            "manifest_ref": (manifest.get("artifacts") or {}).get("readiness_manifest_path"),
            "readiness_bundle_created": bool(manifest.get("readiness_bundle_created")),
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
            "privacy_boundary": "sanitized-first-run-manifest-preview-no-raw-prompts-outputs-session-ids-or-secrets",
        }
        self._first_run_readiness_runs.append(run)
        self._first_run_readiness_runs = self._first_run_readiness_runs[-100:]
        self._persist_first_run_readiness_run(run)
        summary = self.summary(session_id=session_id)
        self._persist_summary(summary)
        return run

    def production_spine_release_lifecycle(self, *, session_id: str | None = None) -> dict[str, Any]:
        session_ref_digest = _session_ref_digest(session_id)
        latest_run = self._latest_production_spine_release_lifecycle_run(
            session_ref_digest=session_ref_digest
        )
        release_manifest_status_rollup = self._release_manifest_status_rollup()
        if latest_run is None:
            return _empty_production_spine_release_lifecycle(
                session_ref_digest=session_ref_digest,
                release_manifest_status_rollup=release_manifest_status_rollup,
            )
        admin_approval = (
            latest_run.get("admin_approval")
            if isinstance(latest_run.get("admin_approval"), dict)
            else _production_spine_lifecycle_admin_approval_record(None)
        )
        latest_rollback = self._latest_production_spine_release_lifecycle_rollback(
            session_ref_digest=session_ref_digest,
            run_id=str(latest_run.get("run_id") or ""),
        )
        return {
            "schema_version": "nexusnet-release-wrapper-production-spine-release-lifecycle-v1",
            "surface_id": "release-wrapper-production-spine-release-lifecycle",
            "generated_at": utcnow().isoformat(),
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "honest_status_label": latest_run.get("status") or "not-run",
            "status": latest_run.get("status") or "not-run",
            "product_surface": "wrapper",
            "product_scope": "whole-system",
            "session_ref_digest": session_ref_digest,
            "latest_run": latest_run,
            "latest_run_id": latest_run.get("run_id"),
            "latest_rollback": latest_rollback,
            "latest_rollback_id": (latest_rollback or {}).get("rollback_id"),
            "admin_approval_required": True,
            "admin_approval": admin_approval,
            "release_manifest_status_rollup": release_manifest_status_rollup,
            "endpoint_refs": {
                "production_spine_release_lifecycle": "/ops/wrapper/production-spine-release-lifecycle",
                "production_spine_release_lifecycle_run": "/ops/wrapper/production-spine-release-lifecycle/run",
                "production_spine_release_lifecycle_rollback": (
                    f"/ops/wrapper/production-spine-release-lifecycle/{latest_run.get('run_id')}/rollback"
                ),
                "admin_approval": "/ops/approvals",
                "production_spine_scorecard": "/ops/brain/canon/production-spine",
                "release_runtime": "/ops/wrapper/release-runtime",
                "release_readiness": "/ops/wrapper/release-readiness",
                "status_card": "/ops/wrapper/status-card",
                "control_panel": "/ui/control-panel/",
                "visualizer": "/ui/visualizer/",
            },
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "release_mutation_allowed": bool(latest_run.get("release_mutation_allowed")),
            "privacy_boundary": "sanitized-production-spine-status-ids-counts-and-artifact-digests-only-no-local-paths-secrets-prompts-or-session-ids",
            "mutation_boundary": "shadow-release-lifecycle-preview-only-no-active-production-or-buyer-release-mutation",
        }

    def record_production_spine_release_lifecycle_run(
        self,
        *,
        session_id: str | None = None,
        operator_approved: bool = False,
        human_approved: bool = False,
        admin_approval: dict[str, Any] | None = None,
        request_overrides: dict[str, Any] | None = None,
    ) -> dict[str, Any]:
        created_at = utcnow().isoformat()
        session_ref_digest = _session_ref_digest(session_id)
        approval_record = _production_spine_lifecycle_admin_approval_record(admin_approval)
        if approval_record.get("status") != "approved":
            return {
                "schema_version": "nexusnet-release-wrapper-production-spine-release-lifecycle-run-v1",
                "surface_id": "release-wrapper-production-spine-release-lifecycle-run",
                "run_id": f"production-spine-release-lifecycle::blocked::{_privacy_digest(created_at)}",
                "created_at": created_at,
                "status": "blocked-pending-admin-approval",
                "honest_status_label": "blocked-pending-admin-approval",
                "product_surface": "wrapper",
                "product_scope": "whole-system",
                "session_ref_digest": session_ref_digest,
                "admin_approval_required": True,
                "admin_approval": approval_record,
                "steps": [],
                "step_counts": {"total": 0, "passed": 0, "blocked": 1},
                "release_manifest_status_rollup": self._release_manifest_status_rollup(),
                "release_mutation_allowed": False,
                "buyer_release_allowed": False,
                "evidence_refs": ["/ops/approvals", "/ops/wrapper/production-spine-release-lifecycle/run"],
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
                "privacy_boundary": "sanitized-production-spine-approval-status-only-no-local-paths-secrets-prompts-or-session-ids",
                "mutation_boundary": "admin-approval-required-before-shadow-release-lifecycle-execution",
            }
        safe_overrides = {
            str(key): value
            for key, value in (request_overrides or {}).items()
            if key
            not in {
                "session_id",
                "raw_private_data",
                "private_data",
                "secrets",
                "environment_variables",
                "passphrase",
                "signing_key_passphrase",
                "signing_seed_hex",
            }
        }
        run_token = _privacy_digest(f"{created_at}:{session_ref_digest or 'global'}")
        cycle_id = str(
            safe_overrides.get("cycle_id")
            or f"cycle:rwps:{run_token}"
        )
        lifecycle_id = str(
            safe_overrides.get("lifecycle_id")
            or f"lifecycle:rwps:{run_token}"
        )
        student_id = str(safe_overrides.get("student_id") or f"student:rwps:{run_token}")
        target_node_ref = str(safe_overrides.get("target_node_ref") or "node:rwps_runtime")
        export_dir = self.runtime_dir / "ps-release-lifecycle" / _safe_ref(run_token) / "exports"
        export_dir.mkdir(parents=True, exist_ok=True)

        steps: list[dict[str, Any]] = []

        def scorecard_template(name: str) -> dict[str, Any]:
            scorecard = self.production_spine.scorecard()
            template = scorecard.get(name) if isinstance(scorecard.get(name), dict) else {}
            request = template.get("template") if isinstance(template.get("template"), dict) else {}
            return json.loads(json.dumps(request))

        lifecycle_request = _release_wrapper_shadow_growth_lifecycle_request(
            cycle_id=cycle_id,
            lifecycle_id=lifecycle_id,
            student_id=student_id,
            target_node_ref=target_node_ref,
        )
        lifecycle = self.production_spine.run_growth_lifecycle(lifecycle_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "growth_lifecycle",
                lifecycle,
                ready=lifecycle.get("status") == "closed_loop_complete",
            )
        )

        signing_template = scorecard_template("project_local_signing_key_request_template")
        seed_hex = hashlib.sha256(f"{cycle_id}:release-wrapper-shadow-seed".encode("utf-8")).hexdigest()
        passphrase = f"release-wrapper-shadow-passphrase-{_privacy_digest(cycle_id)}"
        signing_template.update(
            {
                "key_id": signing_template.get("key_id") or "artifact_signing_key",
                "seed_hex": seed_hex,
                "passphrase": passphrase,
            }
        )
        signing_key = self.production_spine.create_project_local_signing_key(signing_template)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "project_local_signing_key",
                signing_key,
                ready=signing_key.get("status") == "created",
            )
        )

        signed_replay_request = scorecard_template("signed_deep_replay_handoff_request_template")
        signed_replay_request["signing_key_passphrase"] = passphrase
        signed_replay = self.production_spine.build_deep_replay_bundle(signed_replay_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "signed_deep_replay",
                signed_replay,
                ready=str(signed_replay.get("status") or "").endswith("ready"),
            )
        )

        rescan_request = scorecard_template("signed_replay_artifact_trust_rescan_request_template")
        rescan = self.production_spine.run_signed_replay_artifact_trust_rescan(rescan_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "signed_replay_artifact_trust_rescan",
                rescan,
                ready=rescan.get("adapter_artifact_trust_clear") is True,
            )
        )

        reviewer_request = scorecard_template("reviewer_window_request_template")
        reviewer_request.update(
            {
                "advancement_id": f"reviewer-window:{_safe_ref(cycle_id)}",
                "window": "post_promotion",
                "window_status": "passed",
                "passed_windows": ["initial_eval", "shadow_runtime", "canary"],
                "lower_confidence_surpass_bound": 0.08,
                "required_lower_confidence_margin": 0.01,
                "teacher_ejection_review_requested": True,
                "parent_retirement_review_requested": True,
                "human_approved": bool(human_approved),
                "governance_approved": bool(operator_approved),
            }
        )
        reviewer = self.production_spine.record_reviewer_window_advancement(reviewer_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "reviewer_window_advancement",
                reviewer,
                ready=reviewer.get("window_status") == "passed",
            )
        )

        productization_request = scorecard_template("productization_readiness_request_template")
        productization_request.update(
            {
                "readiness_id": f"release:{_safe_ref(cycle_id)}",
                "cycle_id": cycle_id,
                "adapter_artifact_trust_status": "trusted",
                "upstream_agent_opportunity_gate": {"status": "clear", "blocked": False},
            }
        )
        for gate in (
            "local_cache_controls",
            "secret_scan_passed",
            "model_download_manager",
            "support_bundle",
            "crash_diagnostics",
            "ci_packaging",
            "buyer_launcher",
            "docs_complete",
            "buyer_safe_defaults",
            "runtime_gates_clear",
            "artifact_signing_ready",
            "artifact_trust_clear",
            "adapter_artifact_trust_clear",
        ):
            productization_request[gate] = True
        productization = self.production_spine.assess_productization_readiness(productization_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "productization_readiness",
                productization,
                ready=productization.get("release_ready") is True,
                blockers=productization.get("open_gates") or [],
            )
        )

        support_request = scorecard_template("production_support_bundle_export_request_template")
        support_request.update(
            {
                "support_bundle_destination": str(export_dir / "support_bundle.zip"),
                "secret_scan_passed": True,
                "adapter_artifact_trust_status": "trusted",
                "adapter_artifact_trust_clear": True,
            }
        )
        support = self.production_spine.build_support_bundle_manifest(support_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "support_bundle_manifest",
                support,
                ready=support.get("zip_created") is True,
                blockers=support.get("zip_creation_blockers") or [],
            )
        )

        first_run_request = scorecard_template("first_run_readiness_request_template")
        first_run_request.update(
            {
                "operator_approved": bool(operator_approved),
                "support_bundle_ready": True,
                "crash_diagnostics_ready": True,
                "project_local_signing_key_ready": True,
                "adapter_artifact_trust_status": "trusted",
                "adapter_artifact_trust_clear": True,
                "include_raw_private_data": False,
                "workspace_paths_redacted": True,
                "redact_secrets": True,
            }
        )
        first_run = self.production_spine.build_first_run_readiness_manifest(first_run_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "first_run_readiness",
                first_run,
                ready=first_run.get("decision") == "ready",
                blockers=first_run.get("readiness_blockers") or [],
            )
        )

        diagnostics_request = scorecard_template("crash_diagnostics_export_request_template")
        diagnostics_request.update(
            {
                "diagnostics_destination": str(export_dir / "crash_diagnostics.json"),
                "crash_diagnostics_ready": True,
                "support_bundle_ready": True,
                "secret_scan_passed": True,
                "adapter_artifact_trust_status": "trusted",
                "adapter_artifact_trust_clear": True,
            }
        )
        diagnostics = self.production_spine.build_crash_diagnostics_manifest(diagnostics_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "crash_diagnostics",
                diagnostics,
                ready=diagnostics.get("logs_packaged") is True,
                blockers=diagnostics.get("log_packaging_blockers") or [],
            )
        )

        runtime_health_request = scorecard_template("active_runtime_health_monitor_request_template")
        runtime_health_request.update(
            {
                "monitor_id": f"runtime-health:{_safe_ref(cycle_id)}",
                "cycle_id": cycle_id,
                "student_id": student_id,
                "target_node_ref": target_node_ref,
                "current_runtime_state": "canary",
                "signed_replay_trust_clear": True,
                "adapter_artifact_trust_status": "trusted",
                "adapter_artifact_trust_clear": True,
                "rollback_restorable": True,
                "health_window_started": True,
                "rollback_snapshot_path": str(export_dir / "rollback_snapshot.json"),
                "target_signed_replay_id": signed_replay.get("signed_replay_id")
                or signed_replay.get("replay_id")
                or f"signed-replay:{_safe_ref(cycle_id)}",
                "max_error_rate": 0.05,
                "error_rate_observed": 0.0,
                "max_p95_latency_ms": 5000,
                "p95_latency_ms_observed": 100,
                "max_route_share": 1.0,
                "route_share_observed": 0.25,
            }
        )
        runtime_health = self.production_spine.build_runtime_health_monitor_manifest(runtime_health_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "runtime_health_monitor",
                runtime_health,
                ready=runtime_health.get("decision") == "ready",
                blockers=runtime_health.get("health_report_blockers") or [],
            )
        )

        release_request = scorecard_template("release_packaging_handoff_request_template")
        release_request.update(
            {
                "release_destination": str(export_dir / "release_package.zip"),
                "ci_packaging_ready": True,
                "buyer_launcher_ready": True,
                "support_bundle_ready": True,
                "crash_diagnostics_ready": True,
                "first_run_readiness_ready": True,
                "buyer_safe_defaults": True,
                "docs_complete": True,
                "secret_scan_passed": True,
                "artifact_signing_ready": True,
                "artifact_trust_clear": True,
                "adapter_artifact_trust_status": "trusted",
                "adapter_artifact_trust_clear": True,
                "include_raw_private_data": False,
                "workspace_paths_redacted": True,
                "redact_secrets": True,
            }
        )
        release_package = self.production_spine.build_release_package_manifest(release_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "release_package",
                release_package,
                ready=release_package.get("package_created") is True
                and release_package.get("buyer_release_allowed") is True,
                blockers=release_package.get("package_creation_blockers") or [],
            )
        )

        go_no_go_request = scorecard_template("release_go_no_go_review_request_template")
        go_no_go_request.update(
            {
                "operator_approved": bool(operator_approved),
                "human_approved": bool(human_approved),
                "buyer_release_allowed": True,
                "release_packaging_ready": True,
                "first_run_readiness_ready": True,
                "crash_diagnostics_ready": True,
                "support_bundle_ready": True,
                "artifact_trust_clear": True,
                "adapter_artifact_trust_status": "trusted",
                "adapter_artifact_trust_clear": True,
                "signed_replay_trust_clear": True,
                "reviewer_windows_ready": True,
                "release_destination": str(export_dir / "release_package.zip"),
                "release_package_path": (release_package.get("artifacts") or {}).get("release_package_path"),
                "support_bundle_path": (support.get("artifacts") or {}).get("support_bundle_path"),
                "crash_diagnostics_bundle_path": (diagnostics.get("artifacts") or {}).get("diagnostics_bundle_path"),
                "include_raw_private_data": False,
                "workspace_paths_redacted": True,
                "redact_secrets": True,
            }
        )
        go_no_go = self.production_spine.build_release_go_no_go_manifest(go_no_go_request)
        steps.append(
            _production_spine_lifecycle_step_summary(
                "release_go_no_go",
                go_no_go,
                ready=go_no_go.get("decision") == "approved"
                and go_no_go.get("release_mutation_allowed") is False,
                blockers=go_no_go.get("release_blockers") or [],
            )
        )

        blocked_steps = [step for step in steps if step.get("status") != "pass"]
        release_manifest_status_rollup = self._release_manifest_status_rollup()
        authority_evidence_tool_governance = self._record_production_spine_release_lifecycle_governance(
            run_token=run_token,
            cycle_id=cycle_id,
            lifecycle_id=lifecycle_id,
            approval_record=approval_record,
            steps=steps,
            release_manifest_status_rollup=release_manifest_status_rollup,
        )
        approved = (
            not blocked_steps
            and release_manifest_status_rollup.get("status") == "approved"
            and release_manifest_status_rollup.get("release_mutation_allowed") is False
            and approval_record.get("status") == "approved"
            and authority_evidence_tool_governance.get("status") == "pass"
        )
        run = {
            "schema_version": "nexusnet-release-wrapper-production-spine-release-lifecycle-run-v1",
            "surface_id": "release-wrapper-production-spine-release-lifecycle-run",
            "run_id": f"production-spine-release-lifecycle::{_safe_ref(cycle_id)}::{run_token}",
            "created_at": created_at,
            "status": "approved-shadow-release-lifecycle" if approved else "blocked-shadow-release-lifecycle",
            "honest_status_label": "approved-shadow-release-lifecycle" if approved else "blocked-shadow-release-lifecycle",
            "product_surface": "wrapper",
            "product_scope": "whole-system",
            "session_ref_digest": session_ref_digest,
            "cycle_id": cycle_id,
            "lifecycle_id": lifecycle_id,
            "student_id": student_id,
            "target_node_ref": target_node_ref,
            "admin_approval_required": True,
            "admin_approval": approval_record,
            "steps": steps,
            "step_counts": {
                "total": len(steps),
                "passed": len(steps) - len(blocked_steps),
                "blocked": len(blocked_steps),
            },
            "release_manifest_status_rollup": release_manifest_status_rollup,
            "authority_evidence_tool_governance": authority_evidence_tool_governance,
            "release_mutation_allowed": False,
            "buyer_release_allowed": bool(release_manifest_status_rollup.get("buyer_release_allowed")),
            "evidence_refs": [
                "/ops/wrapper/production-spine-release-lifecycle/run",
                "/ops/approvals",
                f"approval::{approval_record.get('approval_ref') or 'missing'}",
                f"authority-decision::{authority_evidence_tool_governance.get('authority_decision_id') or 'missing'}",
                f"evidence::{authority_evidence_tool_governance.get('evidence_record_id') or 'missing'}",
                f"eval-federation::{authority_evidence_tool_governance.get('eval_federation_event_id') or 'missing'}",
                f"tool-action::{authority_evidence_tool_governance.get('tool_action_plan_id') or 'missing'}",
                "/ops/brain/canon/production-spine",
                f"cycle::{cycle_id}",
                f"lifecycle::{lifecycle_id}",
                f"release_manifest_status::{release_manifest_status_rollup.get('status') or 'not_recorded'}",
            ],
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.production_spine_release_lifecycle_log_path))}",
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "sanitized-production-spine-status-ids-counts-and-artifact-digests-only-no-local-paths-secrets-prompts-or-session-ids",
            "mutation_boundary": "shadow-release-lifecycle-preview-only-no-active-production-or-buyer-release-mutation",
        }
        self._production_spine_release_lifecycle_runs.append(run)
        self._production_spine_release_lifecycle_runs = self._production_spine_release_lifecycle_runs[-100:]
        self._persist_production_spine_release_lifecycle_run(run)
        summary = self.summary(session_id=session_id)
        self._persist_summary(summary)
        return run

    def rollback_production_spine_release_lifecycle_run(
        self,
        *,
        run_id: str,
        session_id: str | None = None,
        reason: str = "operator-requested-lifecycle-rollback",
    ) -> dict[str, Any]:
        created_at = utcnow().isoformat()
        session_ref_digest = _session_ref_digest(session_id)
        run = self._find_production_spine_release_lifecycle_run(run_id)
        if run is None:
            return {
                "schema_version": "nexusnet-release-wrapper-production-spine-release-lifecycle-rollback-v1",
                "surface_id": "release-wrapper-production-spine-release-lifecycle-rollback",
                "rollback_id": f"production-spine-release-lifecycle-rollback::missing::{_privacy_digest(created_at)}",
                "created_at": created_at,
                "status": "blocked-run-not-found",
                "run_id": _safe_ref(str(run_id or "")),
                "session_ref_digest": session_ref_digest,
                "rollback_restored": False,
                "active_production_mutated": False,
                "release_mutation_allowed": False,
                "raw_content_included": False,
                "privacy_boundary": "sanitized-rollback-status-only-no-local-paths-secrets-prompts-or-session-ids",
                "mutation_boundary": "no-run-artifact-found-no-production-mutation",
            }

        run_token = _safe_ref(str(run.get("run_id") or run_id).split("::")[-1])
        rollback_id = f"production-spine-release-lifecycle-rollback::{run_token}::{_privacy_digest(created_at)}"
        artifact_base = (self.runtime_dir / "ps-release-lifecycle").resolve()
        artifact_root = (artifact_base / run_token).resolve()
        quarantine_base = (self.runtime_dir / "ps-release-lifecycle-rollbacks").resolve()
        quarantine_root = (quarantine_base / run_token / _privacy_digest(created_at)).resolve()
        cleanup = self._quarantine_production_spine_lifecycle_artifacts(
            artifact_base=artifact_base,
            artifact_root=artifact_root,
            quarantine_base=quarantine_base,
            quarantine_root=quarantine_root,
        )
        authority_evidence_tool_governance = self._record_production_spine_release_lifecycle_rollback_governance(
            rollback_id=rollback_id,
            run=run,
            cleanup=cleanup,
        )
        restored = (
            cleanup.get("status") in {"quarantined", "already-quarantined", "not-present"}
            and authority_evidence_tool_governance.get("status") == "pass"
        )
        rollback = {
            "schema_version": "nexusnet-release-wrapper-production-spine-release-lifecycle-rollback-v1",
            "surface_id": "release-wrapper-production-spine-release-lifecycle-rollback",
            "rollback_id": rollback_id,
            "created_at": created_at,
            "status": "rolled-back" if restored else "blocked",
            "run_id": str(run.get("run_id") or run_id),
            "session_ref_digest": str(run.get("session_ref_digest") or session_ref_digest or ""),
            "reason_digest": f"sha256:{_privacy_digest(str(reason or ''))}",
            "artifact_cleanup": cleanup,
            "authority_evidence_tool_governance": authority_evidence_tool_governance,
            "rollback_restored": bool(restored),
            "active_production_mutated": False,
            "release_mutation_allowed": False,
            "evidence_refs": [
                f"run::{run.get('run_id') or run_id}",
                f"rollback::{rollback_id}",
                f"artifact-cleanup::{cleanup.get('status') or 'unknown'}",
                f"authority-decision::{authority_evidence_tool_governance.get('authority_decision_id') or 'missing'}",
                f"evidence::{authority_evidence_tool_governance.get('evidence_record_id') or 'missing'}",
                f"eval-federation::{authority_evidence_tool_governance.get('eval_federation_event_id') or 'missing'}",
                f"tool-action::{authority_evidence_tool_governance.get('tool_action_plan_id') or 'missing'}",
            ],
            "raw_content_included": False,
            "privacy_boundary": "sanitized-rollback-ids-counts-digests-and-statuses-only-no-local-paths-secrets-prompts-or-session-ids",
            "mutation_boundary": "run-scoped-artifact-quarantine-only-no-active-production-or-buyer-release-mutation",
        }
        self._production_spine_release_lifecycle_rollbacks.append(rollback)
        self._production_spine_release_lifecycle_rollbacks = self._production_spine_release_lifecycle_rollbacks[-100:]
        self._persist_production_spine_release_lifecycle_rollback(rollback)
        summary = self.summary(session_id=session_id)
        self._persist_summary(summary)
        return rollback

    def _boot_supervisor_summary(self) -> dict[str, Any]:
        candidates = [self.runtime_dir / "boot-manifest.json"]
        cli_default_manifest = self.artifacts_dir.parent.parent / BOOT_SUPERVISOR_MANIFEST_REF
        if cli_default_manifest not in candidates:
            candidates.append(cli_default_manifest)
        return _boot_supervisor_summary_from_manifest(candidates)

