    def _record_release_health_loop_failure_learning_signal(
        self,
        *,
        session_id: str | None,
        loop_id: str,
        trigger: str,
        blocked_cycles: list[dict[str, Any]],
    ) -> dict[str, Any]:
        if not blocked_cycles:
            return {
                "status": "not-required",
                "signal_id": None,
                "loop_id": loop_id,
                "trigger": trigger,
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        signal = self._record_degraded_failure_learning_signal(
            session_id=session_id or "release-wrapper-startup",
            source_model="release-wrapper-health-supervisor",
            expert_node="expert.release-health",
            knowledge_ref=f"sha256:{_privacy_digest(loop_id)}",
            trace_id=f"release-health-loop::{_privacy_digest(loop_id)}",
            failure_ref=f"release-health-loop::{_privacy_digest(loop_id)}",
            reason="release_health_heartbeat_loop_blocked",
        )
        return {
            **signal,
            "loop_id": loop_id,
            "trigger": trigger,
            "blocked_cycle_count": len(blocked_cycles),
            "blocked_cycle_ids": [
                f"cycle::{cycle.get('cycle_index')}"
                for cycle in blocked_cycles
                if cycle.get("cycle_index") is not None
            ],
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }

    def _propose_release_health_heartbeat_loop_repair(
        self,
        *,
        loop_id: str,
        trigger: str,
        session_ref_digest: str | None,
        cycles: list[dict[str, Any]],
        blocked_cycles: list[dict[str, Any]],
    ) -> dict[str, Any]:
        if not blocked_cycles or self.autonomous_updates is None:
            return {
                "status": "not-required",
                "latest_update_id": None,
                "active_production_mutation_allowed": False,
                "raw_content_included": False,
            }
        heartbeat_ids = [str(cycle.get("heartbeat_id") or "") for cycle in cycles if cycle.get("heartbeat_id")]
        blocked_cycle_ids = [
            f"cycle::{cycle.get('cycle_index')}"
            for cycle in blocked_cycles
            if cycle.get("cycle_index") is not None
        ]
        whole_system_repair_candidates = release_health_heartbeat_repair_candidates_from_cycles(cycles)
        whole_system_target_surfaces = release_health_heartbeat_target_surfaces(
            whole_system_repair_candidates,
            fallback=[
                "release-wrapper-health-heartbeat-loop",
                "release-wrapper-runtime",
            ],
        )
        whole_system_candidate_gate_ids = release_health_heartbeat_candidate_gate_ids(
            whole_system_repair_candidates
        )
        update_id = f"update::release-wrapper-health-heartbeat-loop::{_privacy_digest(loop_id)}"
        loop_digest = _privacy_digest(loop_id)
        eval_suite_ref = f"eval::release-wrapper-runtime::{loop_digest}"
        evals_ao_artifact_gate_ref = f"evals-ao-artifact::release-wrapper::{loop_digest}"
        proposal = self.autonomous_updates.propose(
            {
                "update_id": update_id,
                "update_type": "runtime",
                "target_ref": "safe-artifact::release-wrapper-health-heartbeat-loop",
                "requested_state": "proposal",
                "eval_refs": [
                    eval_suite_ref,
                    evals_ao_artifact_gate_ref,
                    f"release-health-heartbeat-loop::{loop_id}",
                    "/ops/wrapper/release-readiness",
                    "/ops/wrapper/status-card",
                    *[f"release-health-heartbeat::{heartbeat_id}" for heartbeat_id in heartbeat_ids[:10]],
                ],
                "target_surfaces": whole_system_target_surfaces,
                "artifact_trust_refs": [
                    loop_id,
                    RELEASE_HEALTH_HEARTBEAT_LOOP_REF,
                    RELEASE_HEALTH_HEARTBEAT_REF,
                    BOOT_SUPERVISOR_MANIFEST_REF,
                    RELEASE_PRODUCT_SMOKE_MANIFEST_REF,
                ],
                "rollback_plan": "release-health-loop-safe-file-rollback-before-any-production-mutation",
                "monitoring_plan": (
                    "pytest tests/test_release_wrapper_runtime.py::"
                    "test_release_wrapper_health_heartbeat_loop_runs_bounded_self_checks_with_backoff_and_repair_queue -q"
                ),
                "operator_approved": False,
                "sandbox_ref": "release-wrapper-health-heartbeat-loop",
                "metadata": {
                    "source": "release-wrapper-health-heartbeat-loop",
                    "trigger": trigger,
                    "loop_id": loop_id,
                    "evals_ao_eval_suite_id": eval_suite_ref,
                    "evals_ao_artifact_gate_ref": evals_ao_artifact_gate_ref,
                    "heartbeat_ids": heartbeat_ids,
                    "blocked_cycle_ids": blocked_cycle_ids,
                    "whole_system_candidate_gate_ids": whole_system_candidate_gate_ids,
                    "whole_system_candidate_count": len(whole_system_repair_candidates),
                    "target_surfaces": whole_system_target_surfaces,
                    "session_ref_digest": session_ref_digest,
                    "safe_payload": {
                        "surface_id": RELEASE_HEALTH_HEARTBEAT_LOOP_SURFACE_ID,
                        "loop_id": loop_id,
                        "evals_ao_eval_suite_id": eval_suite_ref,
                        "evals_ao_artifact_gate_ref": evals_ao_artifact_gate_ref,
                        "heartbeat_ids": heartbeat_ids,
                        "blocked_cycle_ids": blocked_cycle_ids,
                        "whole_system_candidate_gate_ids": whole_system_candidate_gate_ids,
                        "whole_system_candidate_count": len(whole_system_repair_candidates),
                        "target_surfaces": whole_system_target_surfaces,
                    },
                    "safe_file_scope": ["artifacts/autonomous-updates/safe-files"],
                    "active_production_mutation_allowed": False,
                },
            }
        )
        return {
            "status": "proposal-routed",
            "latest_update_id": update_id,
            "proposal_status": str(proposal.get("status") or "proposed"),
            "target_ref": "safe-artifact::release-wrapper-health-heartbeat-loop",
            "target_surfaces": whole_system_target_surfaces,
            "whole_system_candidate_count": len(whole_system_repair_candidates),
            "whole_system_candidate_gate_ids": whole_system_candidate_gate_ids,
            "blocked_cycle_ids": blocked_cycle_ids,
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
        }

    def _record_privacy_consent(
        self,
        *,
        session_id: str,
        session_ref_digest: str,
        trace_id: str,
        created_at: str,
    ) -> dict[str, Any]:
        active_state = _active_privacy_consent_state(
            self._latest_privacy_consent_record_for_session(session_ref_digest)
        )
        record = _build_privacy_consent_record(
            session_id=session_id,
            session_ref_digest=session_ref_digest,
            trace_id=trace_id,
            created_at=created_at,
            config_refs=self.privacy_consent_config_refs,
            decision="runtime-observation",
            status=active_state["status"],
            consent_state=active_state["consent_state"],
            personal_data_training_opt_in=active_state["personal_data_training_opt_in"],
            personal_data_federation_allowed=active_state["personal_data_federation_allowed"],
            personal_data_dream_training_allowed=active_state["personal_data_dream_training_allowed"],
            approved_by_ref=active_state.get("approved_by_ref"),
            approval_ref_digest=active_state.get("approval_ref_digest"),
            parent_record_id=active_state.get("record_id"),
            revoked_at=active_state.get("revoked_at"),
        )
        self._privacy_consent_records.insert(0, record)
        self._privacy_consent_records = self._privacy_consent_records[:200]
        self._privacy_consent_replay_status = {
            "status": "replayed",
            "record_count": len(self._privacy_consent_records),
            "artifact_ref": PRIVACY_CONSENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_consent_log_path))}",
        }
        self._persist_privacy_consent_record(record)
        return record

    def _latest_privacy_consent_record_for_session(self, session_ref_digest: str | None) -> dict[str, Any] | None:
        for record in self._privacy_consent_records_for_session(session_ref_digest):
            return record
        return None

    def record_privacy_consent_decision(
        self,
        *,
        session_id: str | None,
        decision: str,
        personal_data_training_opt_in: bool | None = None,
        personal_data_federation_allowed: bool | None = None,
        personal_data_dream_training_allowed: bool | None = None,
        approved_by: str | None = None,
        approval_ref: str | None = None,
    ) -> dict[str, Any]:
        normalized = str(decision or "").strip().lower().replace("_", "-")
        if normalized in {"opt-in", "optin", "approve", "approved", "grant"}:
            training_opt_in = True if personal_data_training_opt_in is None else bool(personal_data_training_opt_in)
            federation_allowed = (
                training_opt_in
                if personal_data_federation_allowed is None
                else bool(personal_data_federation_allowed) and training_opt_in
            )
            dream_training_allowed = (
                training_opt_in
                if personal_data_dream_training_allowed is None
                else bool(personal_data_dream_training_allowed) and training_opt_in
            )
            status = PRIVACY_CONSENT_OPT_IN_STATUS
            consent_state = "explicit-opt-in-personal-data"
            revoked_at = None
        elif normalized in {"revoke", "revoked", "opt-out", "optout", "deny", "denied"}:
            training_opt_in = False
            federation_allowed = False
            dream_training_allowed = False
            status = PRIVACY_CONSENT_REVOKED_STATUS
            consent_state = "revoked-personal-data-default-off"
            revoked_at = utcnow().isoformat()
        else:
            return {
                "schema_version": "nexusnet-release-wrapper-privacy-consent-ledger-v1",
                "surface_id": PRIVACY_CONSENT_SURFACE_ID,
                "status": "blocked-invalid-consent-decision",
                "decision": normalized or "missing",
                "allowed_decisions": ["opt-in", "revoke"],
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }

        safe_session_id = str(session_id or "default")
        session_ref_digest = _privacy_digest(safe_session_id)
        created_at = utcnow().isoformat()
        approval_ref_digest = f"sha256:{_privacy_digest(str(approval_ref or normalized or created_at))}"
        record = _build_privacy_consent_record(
            session_id=safe_session_id,
            session_ref_digest=session_ref_digest,
            trace_id=f"privacy-consent::{normalized}::{_privacy_digest(created_at)}",
            created_at=created_at,
            config_refs=self.privacy_consent_config_refs,
            decision=normalized,
            status=status,
            consent_state=consent_state,
            personal_data_training_opt_in=training_opt_in,
            personal_data_federation_allowed=federation_allowed,
            personal_data_dream_training_allowed=dream_training_allowed,
            approved_by_ref=_safe_ref(str(approved_by or "admin")),
            approval_ref_digest=approval_ref_digest,
            parent_record_id=(
                self._latest_privacy_consent_record_for_session(session_ref_digest) or {}
            ).get("record_id"),
            revoked_at=revoked_at,
        )
        self._privacy_consent_records.insert(0, record)
        self._privacy_consent_records = self._privacy_consent_records[:200]
        self._privacy_consent_replay_status = {
            "status": "replayed",
            "record_count": len(self._privacy_consent_records),
            "artifact_ref": PRIVACY_CONSENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_consent_log_path))}",
        }
        self._persist_privacy_consent_record(record)
        if normalized in {"revoke", "revoked", "opt-out", "optout", "deny", "denied"}:
            self._record_privacy_consent_enforcement(
                session_ref_digest=session_ref_digest,
                decision_record=record,
            )
            self._record_privacy_retention_enforcement(
                session_ref_digest=session_ref_digest,
                decision_record=record,
            )
        summary = self._privacy_consent_summary(session_ref_digest=session_ref_digest)
        summary["decision"] = normalized
        return summary

    def privacy_consent(self, *, session_id: str | None = None) -> dict[str, Any]:
        return self._privacy_consent_summary(session_ref_digest=_session_ref_digest(session_id))

    def _privacy_consent_records_for_session(self, session_ref_digest: str | None) -> list[dict[str, Any]]:
        if not session_ref_digest:
            return list(self._privacy_consent_records)
        return [
            record
            for record in self._privacy_consent_records
            if str(record.get("session_ref_digest") or "") == session_ref_digest
        ]

    def _privacy_consent_summary(self, *, session_ref_digest: str | None) -> dict[str, Any]:
        records = self._privacy_consent_records_for_session(session_ref_digest)
        latest_record = records[0] if records else None
        latest_policy = _privacy_consent_policy_for_packet(latest_record)
        latest_status = str(latest_policy.get("status") or "")
        enforcement = self._privacy_consent_enforcement_summary(session_ref_digest=session_ref_digest)
        retention_enforcement = self._privacy_retention_enforcement_summary(session_ref_digest=session_ref_digest)
        return {
            "schema_version": "nexusnet-release-wrapper-privacy-consent-ledger-v1",
            "surface_id": PRIVACY_CONSENT_SURFACE_ID,
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": (
                latest_status
                if latest_record
                else "no-live-consent-record-yet-personal-data-default-off"
            ),
            "session_ref_digest": session_ref_digest,
            "record_count": len(records),
            "global_record_count": len(self._privacy_consent_records),
            "latest_record_id": latest_record.get("record_id") if latest_record else None,
            "latest_record": latest_record,
            "records": records[:20],
            "config_refs": dict(self.privacy_consent_config_refs),
            "artifact_ref": PRIVACY_CONSENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_consent_log_path))}",
            "personal_data_training_opt_in": latest_policy["personal_data_training_opt_in"],
            "personal_data_federation_allowed": latest_policy["personal_data_federation_allowed"],
            "personal_data_dream_training_allowed": latest_policy["personal_data_dream_training_allowed"],
            "sanitized_metadata_federation_allowed": latest_policy["sanitized_metadata_federation_allowed"],
            "sanitized_dream_research_allowed": latest_policy["sanitized_dream_research_allowed"],
            "federated_packet_scope": latest_policy["federated_packet_scope"],
            "consent_basis": latest_policy["consent_basis"],
            "retention_enforcement": latest_policy["retention_enforcement"],
            "retention_cleanup": retention_enforcement,
            "queue_enforcement": enforcement,
            "decision_endpoint_ref": "/ops/wrapper/privacy-consent",
            "revoked_at": latest_record.get("revoked_at") if latest_record else None,
            "replay": dict(self._privacy_consent_replay_status),
            "raw_content_included": False,
            "contains_personal_data": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "hashed-session-consent-state-config-refs-and-retention-policy-only-no-prompts-outputs-session-ids-or-local-paths",
        }

    def _privacy_consent_enforcement_records_for_session(
        self,
        session_ref_digest: str | None,
    ) -> list[dict[str, Any]]:
        if not session_ref_digest:
            return list(self._privacy_consent_enforcement_records)
        return [
            record
            for record in self._privacy_consent_enforcement_records
            if str(record.get("session_ref_digest") or "") == session_ref_digest
        ]

    def _privacy_consent_enforcement_queue_blocks(self, session_ref_digest: str | None) -> list[dict[str, Any]]:
        if self.improvement_queue is None:
            return []
        queue = ImprovementQueue(self.improvement_queue.storage_path)
        blocks: list[dict[str, Any]] = []
        for item in queue.list_items():
            metadata = item.event.metadata if isinstance(item.event.metadata, dict) else {}
            if session_ref_digest and str(item.event.session_id or "") != session_ref_digest:
                continue
            if metadata.get("source") not in {"release-wrapper-runtime", "native-hive-runtime-growth"}:
                continue
            if metadata.get("dream_research_queue") is not True:
                continue
            if not (
                metadata.get("personal_data_training_opt_in") is True
                or metadata.get("dream_training_personal_data_allowed") is True
                or metadata.get("personal_data_federation_allowed") is True
            ):
                continue
            blocks.append(
                {
                    "queue_id": str(item.queue_id),
                    "event_id": str(item.event.event_id),
                    "status": item.status,
                    "source": metadata.get("source"),
                    "source_model": metadata.get("source_model"),
                    "expert_node": metadata.get("expert_node"),
                    "privacy_consent_record_id": metadata.get("privacy_consent_record_id"),
                    "consent_basis": metadata.get("consent_basis"),
                    "federated_packet_id": (
                        metadata.get("federated_packet_id")
                        or metadata.get("runtime_growth_federated_packet_id")
                    ),
                    "runtime_growth_federated_packet_id": metadata.get("runtime_growth_federated_packet_id"),
                    "personal_data_training_opt_in": metadata.get("personal_data_training_opt_in") is True,
                    "personal_data_federation_allowed": metadata.get("personal_data_federation_allowed") is True,
                    "dream_training_personal_data_allowed": (
                        metadata.get("dream_training_personal_data_allowed") is True
                    ),
                    "quarantine_state": "blocked-by-revocation",
                    "active_personal_data_training_allowed": False,
                    "active_production_mutation_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        return blocks[-50:]

    def _privacy_consent_enforcement_packet_blocks(self, session_ref_digest: str | None) -> list[dict[str, Any]]:
        interactions = self._interactions_for_session(session_ref_digest)
        packets = self._federated_packets_for_interactions(interactions)
        blocks: list[dict[str, Any]] = []
        for packet in packets:
            consent_policy = packet.get("consent_policy") if isinstance(packet.get("consent_policy"), dict) else {}
            if not (
                consent_policy.get("personal_data_training_opt_in") is True
                or consent_policy.get("personal_data_federation_allowed") is True
                or consent_policy.get("personal_data_dream_training_allowed") is True
            ):
                continue
            blocks.append(
                {
                    "packet_id": str(packet.get("packet_id") or ""),
                    "source_model": packet.get("source_model"),
                    "expert_node": packet.get("expert_node") or packet.get("selected_expert"),
                    "privacy_consent_record_id": packet.get("privacy_consent_record_id")
                    or consent_policy.get("record_id"),
                    "consent_basis": consent_policy.get("consent_basis"),
                    "federated_packet_scope": consent_policy.get("federated_packet_scope"),
                    "personal_data_training_opt_in": consent_policy.get("personal_data_training_opt_in") is True,
                    "personal_data_federation_allowed": consent_policy.get("personal_data_federation_allowed") is True,
                    "dream_training_personal_data_allowed": (
                        consent_policy.get("personal_data_dream_training_allowed") is True
                    ),
                    "quarantine_state": "blocked-by-revocation",
                    "active_personal_data_training_allowed": False,
                    "active_production_mutation_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        return blocks[:50]

    def _privacy_consent_enforcement_import_blocks(self, session_ref_digest: str | None) -> list[dict[str, Any]]:
        blocks: list[dict[str, Any]] = []
        for record in self._federated_packet_imports_for_session(session_ref_digest):
            consent_policy = record.get("consent_policy") if isinstance(record.get("consent_policy"), dict) else {}
            if not (
                consent_policy.get("personal_data_training_opt_in") is True
                or consent_policy.get("personal_data_federation_allowed") is True
                or consent_policy.get("personal_data_dream_training_allowed") is True
            ):
                continue
            blocks.append(
                {
                    "import_id": str(record.get("import_id") or ""),
                    "source_packet_ref": record.get("source_packet_ref"),
                    "source_model": record.get("source_model"),
                    "expert_node": record.get("expert_node"),
                    "privacy_consent_record_id": record.get("privacy_consent_record_id")
                    or consent_policy.get("record_id"),
                    "consent_basis": consent_policy.get("consent_basis"),
                    "personal_data_training_opt_in": consent_policy.get("personal_data_training_opt_in") is True,
                    "personal_data_federation_allowed": consent_policy.get("personal_data_federation_allowed") is True,
                    "dream_training_personal_data_allowed": (
                        consent_policy.get("personal_data_dream_training_allowed") is True
                    ),
                    "quarantine_state": "blocked-by-revocation",
                    "active_personal_data_training_allowed": False,
                    "active_production_mutation_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        return blocks[:50]

    def _record_privacy_consent_enforcement(
        self,
        *,
        session_ref_digest: str,
        decision_record: dict[str, Any],
    ) -> dict[str, Any]:
        queue_blocks = self._privacy_consent_enforcement_queue_blocks(session_ref_digest)
        packet_blocks = self._privacy_consent_enforcement_packet_blocks(session_ref_digest)
        import_blocks = self._privacy_consent_enforcement_import_blocks(session_ref_digest)
        blocked_capabilities: list[str] = []
        if queue_blocks:
            blocked_capabilities.append("personal-data-dream-training")
            blocked_capabilities.append("personal-data-global-growth")
        if packet_blocks or import_blocks:
            blocked_capabilities.append("personal-data-federation")
        created_at = utcnow().isoformat()
        decision_record_id = str(decision_record.get("record_id") or "")
        enforcement_digest = _privacy_digest(f"{session_ref_digest}:{decision_record_id}:{created_at}")
        record = {
            "schema_version": "nexusnet-release-wrapper-privacy-consent-enforcement-record-v1",
            "surface_id": PRIVACY_CONSENT_ENFORCEMENT_RECORD_SURFACE_ID,
            "record_id": f"privacy-consent-enforcement::{enforcement_digest}",
            "created_at": created_at,
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": (
                "revocation-enforced"
                if queue_blocks or packet_blocks or import_blocks
                else "revocation-enforced-no-personal-data-artifacts"
            ),
            "session_ref_digest": session_ref_digest,
            "decision_record_id": decision_record_id,
            "revocation_consent_record_id": decision_record_id,
            "revoked_at": decision_record.get("revoked_at") or created_at,
            "blocked_capabilities": blocked_capabilities,
            "revoked_personal_data_queue_count": len(queue_blocks),
            "revoked_federated_packet_count": len(packet_blocks),
            "revoked_federated_import_count": len(import_blocks),
            "queue_blocks": queue_blocks,
            "federated_packet_blocks": packet_blocks,
            "federated_import_blocks": import_blocks,
            "artifact_ref": PRIVACY_CONSENT_ENFORCEMENT_LEDGER_REF,
            "active_personal_data_training_allowed": False,
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
            "contains_personal_data": False,
            "privacy_boundary": "sanitized-queue-packet-import-ids-and-consent-record-refs-only-no-prompts-outputs-session-ids-or-local-paths",
        }
        self._privacy_consent_enforcement_records.insert(0, record)
        self._privacy_consent_enforcement_records = self._privacy_consent_enforcement_records[:200]
        self._privacy_consent_enforcement_replay_status = {
            "status": "replayed",
            "record_count": len(self._privacy_consent_enforcement_records),
            "artifact_ref": PRIVACY_CONSENT_ENFORCEMENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_consent_enforcement_log_path))}",
        }
        self._persist_privacy_consent_enforcement_record(record)
        return record

    def _privacy_consent_enforcement_summary(self, *, session_ref_digest: str | None) -> dict[str, Any]:
        records = self._privacy_consent_enforcement_records_for_session(session_ref_digest)
        latest_record = records[0] if records else None
        latest_queue_blocks = (
            list(latest_record.get("queue_blocks") or []) if isinstance(latest_record, dict) else []
        )
        latest_packet_blocks = (
            list(latest_record.get("federated_packet_blocks") or []) if isinstance(latest_record, dict) else []
        )
        latest_import_blocks = (
            list(latest_record.get("federated_import_blocks") or []) if isinstance(latest_record, dict) else []
        )
        return {
            "schema_version": "nexusnet-release-wrapper-privacy-consent-enforcement-ledger-v1",
            "surface_id": PRIVACY_CONSENT_ENFORCEMENT_SURFACE_ID,
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": latest_record.get("status") if latest_record else "no-revocation-enforcement-recorded",
            "session_ref_digest": session_ref_digest,
            "record_count": len(records),
            "global_record_count": len(self._privacy_consent_enforcement_records),
            "latest_record_id": latest_record.get("record_id") if latest_record else None,
            "latest_record": latest_record,
            "records": records[:20],
            "blocked_capabilities": list(latest_record.get("blocked_capabilities") or [])
            if latest_record
            else [],
            "revoked_personal_data_queue_count": len(latest_queue_blocks),
            "revoked_federated_packet_count": len(latest_packet_blocks),
            "revoked_federated_import_count": len(latest_import_blocks),
            "queue_blocks": latest_queue_blocks[:20],
            "federated_packet_blocks": latest_packet_blocks[:20],
            "federated_import_blocks": latest_import_blocks[:20],
            "artifact_ref": PRIVACY_CONSENT_ENFORCEMENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_consent_enforcement_log_path))}",
            "replay": dict(self._privacy_consent_enforcement_replay_status),
            "active_personal_data_training_allowed": False,
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
            "contains_personal_data": False,
            "retention_enforcement": self._privacy_retention_enforcement_summary(
                session_ref_digest=session_ref_digest
            ),
            "privacy_boundary": "sanitized-queue-packet-import-ids-and-consent-record-refs-only-no-prompts-outputs-session-ids-or-local-paths",
        }

    def _privacy_retention_enforcement_records_for_session(
        self,
        session_ref_digest: str | None,
    ) -> list[dict[str, Any]]:
        if not session_ref_digest:
            return list(self._privacy_retention_enforcement_records)
        return [
            record
            for record in self._privacy_retention_enforcement_records
            if str(record.get("session_ref_digest") or "") == session_ref_digest
        ]

    def _latest_privacy_retention_enforcement_record_for_session(
        self,
        session_ref_digest: str | None,
    ) -> dict[str, Any] | None:
        records = self._privacy_retention_enforcement_records_for_session(session_ref_digest)
        return records[0] if records else None

    def _reject_privacy_retention_queue_blocks(
        self,
        queue_blocks: list[dict[str, Any]],
        *,
        decision_record_id: str,
    ) -> list[dict[str, Any]]:
        if self.improvement_queue is None:
            return []
        queue = ImprovementQueue(self.improvement_queue.storage_path)
        expired_refs: list[dict[str, Any]] = []
        for block in queue_blocks:
            queue_id = str(block.get("queue_id") or "")
            if not queue_id:
                continue
            try:
                item = queue.get(queue_id)
            except KeyError:
                continue
            previous_status = str(item.status)
            target_status = ""
            if previous_status in {"proposed", "validated"}:
                target_status = "rejected"
            elif previous_status in {"approved", "deployed", "monitored"}:
                target_status = "reverted"
            transition_applied = False
            transition_blocked = ""
            if target_status:
                try:
                    item = queue.transition(
                        queue_id,
                        target_status,  # type: ignore[arg-type]
                        actor="PrivacyConsentRetentionEnforcer",
                        reason=(
                            "personal-data learning artifact expired after privacy consent revocation "
                            f"{decision_record_id}"
                        ),
                    )
                    transition_applied = True
                except ValueError as exc:
                    transition_blocked = str(exc)
            metadata = item.event.metadata if isinstance(item.event.metadata, dict) else {}
            expired_refs.append(
                {
                    "queue_id": queue_id,
                    "event_id": str(item.event.event_id),
                    "previous_status": previous_status,
                    "status": str(item.status),
                    "transition_target": target_status or str(item.status),
                    "transition_applied": transition_applied,
                    "transition_blocked": transition_blocked or None,
                    "source": metadata.get("source") or block.get("source"),
                    "source_model": metadata.get("source_model") or block.get("source_model"),
                    "expert_node": metadata.get("expert_node") or block.get("expert_node"),
                    "federated_packet_id": (
                        metadata.get("federated_packet_id")
                        or metadata.get("runtime_growth_federated_packet_id")
                        or block.get("federated_packet_id")
                    ),
                    "runtime_growth_federated_packet_id": (
                        metadata.get("runtime_growth_federated_packet_id")
                        or block.get("runtime_growth_federated_packet_id")
                    ),
                    "federated_packet_import_id": metadata.get("federated_packet_import_id"),
                    "privacy_consent_record_id": (
                        metadata.get("privacy_consent_record_id") or block.get("privacy_consent_record_id")
                    ),
                    "active_personal_data_training_allowed": False,
                    "active_production_mutation_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        return expired_refs[-100:]

    def _privacy_retention_global_growth_passivation_refs(
        self,
        *,
        session_ref_digest: str,
        expired_queue_refs: list[dict[str, Any]],
        packet_blocks: list[dict[str, Any]],
        import_blocks: list[dict[str, Any]],
    ) -> list[dict[str, Any]]:
        passivated: list[dict[str, Any]] = []
        for ref in expired_queue_refs:
            queue_id = str(ref.get("queue_id") or "")
            if not queue_id:
                continue
            runtime_packet_id = str(ref.get("runtime_growth_federated_packet_id") or "")
            packet_id = runtime_packet_id or str(ref.get("federated_packet_id") or "")
            capture_seed = f"{session_ref_digest}:queue:{queue_id}"
            passivated.append(
                {
                    "capture_ref": f"global-growth-passivation::{_privacy_digest(capture_seed)}",
                    "source_ref": (
                        f"federated-packet::{_safe_ref(packet_id)}"
                        if packet_id
                        else f"improvement-queue::{_safe_ref(queue_id)}"
                    ),
                    "source_type": "dream-research-queue",
                    "queue_id": queue_id,
                    "packet_id": packet_id or None,
                    "runtime_growth_federated_packet_id": runtime_packet_id or None,
                    "status": "inactive-retention-passivated",
                    "passivation_mode": "native-growth-state-passivation",
                    "active_personal_data_training_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        for block in packet_blocks:
            packet_id = str(block.get("packet_id") or "")
            if not packet_id:
                continue
            capture_seed = f"{session_ref_digest}:packet:{packet_id}"
            passivated.append(
                {
                    "capture_ref": f"global-growth-passivation::{_privacy_digest(capture_seed)}",
                    "source_ref": f"federated-packet::{_safe_ref(packet_id)}",
                    "source_type": "federated-packet",
                    "packet_id": packet_id,
                    "status": "inactive-retention-passivated",
                    "passivation_mode": "native-growth-state-passivation",
                    "active_personal_data_training_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        for block in import_blocks:
            import_id = str(block.get("import_id") or "")
            if not import_id:
                continue
            capture_seed = f"{session_ref_digest}:import:{import_id}"
            passivated.append(
                {
                    "capture_ref": f"global-growth-passivation::{_privacy_digest(capture_seed)}",
                    "source_ref": f"federated-packet-import::{_safe_ref(import_id)}",
                    "source_type": "federated-packet-import",
                    "import_id": import_id,
                    "status": "inactive-retention-passivated",
                    "passivation_mode": "native-growth-state-passivation",
                    "active_personal_data_training_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
            )
        deduped: dict[str, dict[str, Any]] = {}
        for item in passivated:
            deduped[str(item.get("capture_ref") or "")] = item
        return list(deduped.values())[:100]

    def _record_privacy_retention_enforcement(
        self,
        *,
        session_ref_digest: str,
        decision_record: dict[str, Any],
    ) -> dict[str, Any]:
        queue_blocks = self._privacy_consent_enforcement_queue_blocks(session_ref_digest)
        packet_blocks = self._privacy_consent_enforcement_packet_blocks(session_ref_digest)
        import_blocks = self._privacy_consent_enforcement_import_blocks(session_ref_digest)
        created_at = utcnow().isoformat()
        decision_record_id = str(decision_record.get("record_id") or "")
        expired_queue_refs = self._reject_privacy_retention_queue_blocks(
            queue_blocks,
            decision_record_id=decision_record_id,
        )
        passivated_refs = self._privacy_retention_global_growth_passivation_refs(
            session_ref_digest=session_ref_digest,
            expired_queue_refs=expired_queue_refs,
            packet_blocks=packet_blocks,
            import_blocks=import_blocks,
        )
        record_id = (
            "privacy-retention-enforcement::"
            f"{_privacy_digest(f'{session_ref_digest}:{decision_record_id}:{created_at}')}"
        )
        native_passivation = (
            self.global_growth.passivate_runtime_captures(
                passivated_refs,
                reason_ref=record_id,
                session_ref_digest=session_ref_digest,
            )
            if self.global_growth is not None and passivated_refs
            else {
                "surface_id": "multi-user-runtime-growth-passivation",
                "status": "not-run-no-passivation-refs",
                "passivated_capture_count": 0,
                "raw_content_included": False,
                "contains_personal_data": False,
                "active_production_mutation_allowed": False,
            }
        )
        native_passivation_governance = (
            self._record_native_growth_passivation_governance(
                retention_record_id=record_id,
                session_ref_digest=session_ref_digest,
                decision_record_id=decision_record_id,
                native_passivation=native_passivation,
                passivated_refs=passivated_refs,
            )
            if self.global_growth is not None and passivated_refs
            else {
                "surface_id": "native-growth-passivation-governance-record",
                "status": "not-run-no-native-passivation",
                "governed_surface_id": "multi-user-runtime-growth-passivation",
                "native_passivation_record_id": native_passivation.get("record_id"),
                "raw_content_included": False,
                "contains_personal_data": False,
                "active_production_mutation_allowed": False,
            }
        )
        native_passivation = {
            **native_passivation,
            "authority_evidence_tool_governance": native_passivation_governance,
        }
        status = (
            "revoked-personal-data-retention-enforced"
            if expired_queue_refs or passivated_refs
            else "revoked-personal-data-retention-enforced-no-active-artifacts"
        )
        record = {
            "schema_version": "nexusnet-release-wrapper-privacy-retention-enforcement-record-v1",
            "surface_id": PRIVACY_RETENTION_ENFORCEMENT_RECORD_SURFACE_ID,
            "record_id": record_id,
            "created_at": created_at,
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": status,
            "session_ref_digest": session_ref_digest,
            "decision_record_id": decision_record_id,
            "revocation_consent_record_id": decision_record_id,
            "revoked_at": decision_record.get("revoked_at") or created_at,
            "expired_queue_count": len(expired_queue_refs),
            "passivated_global_growth_count": int(
                native_passivation.get("passivated_capture_count") or len(passivated_refs)
            ),
            "blocked_federated_packet_count": len(packet_blocks),
            "blocked_federated_import_count": len(import_blocks),
            "expired_queue_refs": expired_queue_refs,
            "passivated_global_growth_refs": passivated_refs,
            "federated_packet_blocks": packet_blocks,
            "federated_import_blocks": import_blocks,
            "native_global_growth_passivation": native_passivation,
            "authority_evidence_tool_governance": native_passivation_governance,
            "global_growth_passivation_mode": "native-growth-state-passivation"
            if int(native_passivation.get("passivated_capture_count") or 0) > 0
            else "native-growth-state-passivation-no-active-captures-matched",
            "artifact_ref": PRIVACY_RETENTION_ENFORCEMENT_LEDGER_REF,
            "active_personal_data_training_allowed": False,
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
            "contains_personal_data": False,
            "privacy_boundary": "sanitized-queue-packet-import-growth-refs-and-consent-record-refs-only-no-prompts-outputs-session-ids-or-local-paths",
        }
        self._privacy_retention_enforcement_records.insert(0, record)
        self._privacy_retention_enforcement_records = self._privacy_retention_enforcement_records[:200]
        self._privacy_retention_enforcement_replay_status = {
            "status": "replayed",
            "record_count": len(self._privacy_retention_enforcement_records),
            "artifact_ref": PRIVACY_RETENTION_ENFORCEMENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_retention_enforcement_log_path))}",
        }
        self._persist_privacy_retention_enforcement_record(record)
        return record

    def _privacy_retention_enforcement_summary(self, *, session_ref_digest: str | None) -> dict[str, Any]:
        records = self._privacy_retention_enforcement_records_for_session(session_ref_digest)
        latest_record = records[0] if records else None
        expired_queue_refs = (
            list(latest_record.get("expired_queue_refs") or []) if isinstance(latest_record, dict) else []
        )
        passivated_refs = (
            list(latest_record.get("passivated_global_growth_refs") or [])
            if isinstance(latest_record, dict)
            else []
        )
        latest_governance = (
            latest_record.get("authority_evidence_tool_governance")
            if isinstance((latest_record or {}).get("authority_evidence_tool_governance"), dict)
            else {}
        )
        return {
            "schema_version": "nexusnet-release-wrapper-privacy-retention-enforcement-ledger-v1",
            "surface_id": PRIVACY_RETENTION_ENFORCEMENT_SURFACE_ID,
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": latest_record.get("status") if latest_record else "no-retention-enforcement-recorded",
            "session_ref_digest": session_ref_digest,
            "record_count": len(records),
            "global_record_count": len(self._privacy_retention_enforcement_records),
            "latest_record_id": latest_record.get("record_id") if latest_record else None,
            "latest_record": latest_record,
            "records": records[:20],
            "expired_queue_count": int(
                latest_record.get("expired_queue_count") if latest_record else 0
            ),
            "passivated_global_growth_count": int(
                latest_record.get("passivated_global_growth_count") if latest_record else 0
            ),
            "expired_queue_refs": expired_queue_refs[:20],
            "passivated_global_growth_refs": passivated_refs[:20],
            "native_global_growth_passivation": (
                latest_record.get("native_global_growth_passivation")
                if isinstance((latest_record or {}).get("native_global_growth_passivation"), dict)
                else {
                    "surface_id": "multi-user-runtime-growth-passivation",
                    "status": "not-recorded",
                    "passivated_capture_count": 0,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                    "active_production_mutation_allowed": False,
                }
            ),
            "global_growth_passivation_mode": (
                latest_record.get("global_growth_passivation_mode")
                if latest_record
                else "not-recorded"
            ),
            "authority_evidence_tool_governance": {
                "schema_version": "nexusnet-native-growth-passivation-governance-summary-v1",
                "surface_id": "native-growth-passivation-governance-summary",
                "authority": "NexusBrain",
                "status": latest_governance.get("status")
                if latest_governance
                else "no-native-passivation-governance-recorded",
                "latest_record_id": latest_record.get("record_id") if latest_governance else None,
                "latest_governance": latest_governance,
                "authority_decision_id": latest_governance.get("authority_decision_id"),
                "evidence_record_id": latest_governance.get("evidence_record_id"),
                "eval_federation_event_id": latest_governance.get("eval_federation_event_id"),
                "tool_action_plan_id": latest_governance.get("tool_action_plan_id"),
                "raw_content_included": False,
                "contains_personal_data": False,
                "active_production_mutation_allowed": False,
                "privacy_boundary": "sanitized-native-passivation-governance-ids-counts-and-hashes-only",
            },
            "artifact_ref": PRIVACY_RETENTION_ENFORCEMENT_LEDGER_REF,
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.privacy_retention_enforcement_log_path))}",
            "replay": {
                **dict(self._privacy_retention_enforcement_replay_status),
                "native_growth_replay": dict(
                    getattr(self, "_privacy_retention_growth_replay_status", {})
                ),
            },
            "active_personal_data_training_allowed": False,
            "active_production_mutation_allowed": False,
            "raw_content_included": False,
            "contains_personal_data": False,
            "privacy_boundary": "sanitized-retention-counts-queue-refs-and-growth-passivation-refs-only-no-prompts-outputs-session-ids-or-local-paths",
        }

    def _global_growth_with_privacy_retention(
        self,
        global_growth: dict[str, Any],
        *,
        retention: dict[str, Any],
    ) -> dict[str, Any]:
        passivated_count = int(retention.get("passivated_global_growth_count") or 0)
        native_passivation = (
            global_growth.get("native_privacy_passivation")
            if isinstance(global_growth.get("native_privacy_passivation"), dict)
            else retention.get("native_global_growth_passivation")
            if isinstance(retention.get("native_global_growth_passivation"), dict)
            else {}
        )
        return {
            **global_growth,
            "privacy_retention_enforcement": retention,
            "passivated_personal_data_capture_count": passivated_count,
            "native_privacy_passivation": native_passivation,
            "active_personal_data_training_allowed": False
            if passivated_count or retention.get("latest_record_id")
            else bool(global_growth.get("active_personal_data_training_allowed", False)),
            "global_growth_passivation_mode": retention.get("global_growth_passivation_mode") or "not-recorded",
        }

    def _replay_privacy_retention_queue_state(self) -> None:
        if self.improvement_queue is None or not self._privacy_retention_enforcement_records:
            return
        queue = ImprovementQueue(self.improvement_queue.storage_path)
        reapplied = 0
        skipped = 0
        for record in reversed(self._privacy_retention_enforcement_records):
            decision_record_id = str(record.get("decision_record_id") or record.get("record_id") or "")
            for ref in record.get("expired_queue_refs") or []:
                if not isinstance(ref, dict):
                    skipped += 1
                    continue
                queue_id = str(ref.get("queue_id") or "")
                if not queue_id:
                    skipped += 1
                    continue
                try:
                    item = queue.get(queue_id)
                except KeyError:
                    skipped += 1
                    continue
                status = str(item.status)
                target_status = "rejected" if status in {"proposed", "validated"} else ""
                if status in {"approved", "deployed", "monitored"}:
                    target_status = "reverted"
                if not target_status:
                    skipped += 1
                    continue
                try:
                    queue.transition(
                        queue_id,
                        target_status,  # type: ignore[arg-type]
                        actor="PrivacyRetentionReplay",
                        reason=(
                            "replayed personal-data retention enforcement after privacy consent revocation "
                            f"{decision_record_id}"
                        ),
                    )
                    reapplied += 1
                except ValueError:
                    skipped += 1
        self._privacy_retention_enforcement_replay_status = {
            **self._privacy_retention_enforcement_replay_status,
            "status": "replayed",
            "queue_replay": {
                "reapplied_queue_transitions": reapplied,
                "skipped_queue_transitions": skipped,
                "active_production_mutation_allowed": False,
                "raw_content_included": False,
            },
        }

    def _replay_privacy_retention_growth_state(self) -> dict[str, Any]:
        if self.global_growth is None or not self._privacy_retention_enforcement_records:
            return {
                "surface_id": "release-wrapper-privacy-retention-native-growth-replay",
                "status": "no-persisted-retention-enforcement-records",
                "restored_passivation_records": 0,
                "raw_content_included": False,
                "contains_personal_data": False,
                "active_production_mutation_allowed": False,
            }
        replay = self.global_growth.restore_passivation_records(self._privacy_retention_enforcement_records)
        return {
            "surface_id": "release-wrapper-privacy-retention-native-growth-replay",
            "status": replay.get("status") or "replayed",
            "restored_passivation_records": int(replay.get("restored_passivation_records") or 0),
            "skipped_passivation_records": int(replay.get("skipped_passivation_records") or 0),
            "passivated_capture_count": int(replay.get("passivated_capture_count") or 0),
            "active_global_captures": int(replay.get("active_global_captures") or 0),
            "passivated_global_captures": int(replay.get("passivated_global_captures") or 0),
            "raw_content_included": False,
            "contains_personal_data": False,
            "active_production_mutation_allowed": False,
        }

    def _privacy_consent_blocks_personal_data_policy(
        self,
        *,
        session_ref_digest: str | None,
        consent_policy: dict[str, Any],
    ) -> bool:
        personal_data_requested = (
            consent_policy.get("personal_data_training_opt_in") is True
            or consent_policy.get("personal_data_federation_allowed") is True
            or consent_policy.get("personal_data_dream_training_allowed") is True
        )
        if not personal_data_requested:
            return False
        active_local_policy = _privacy_consent_policy_for_packet(
            self._latest_privacy_consent_record_for_session(session_ref_digest)
        )
        return active_local_policy.get("personal_data_training_opt_in") is not True

    def guard_privacy_consent_for_autonomous_update(
        self,
        *,
        update_id: str,
        action: str,
        endpoint_ref: str,
    ) -> dict[str, Any]:
        proposal = self._autonomous_update_proposal(update_id)
        if proposal is None:
            return {
                "surface_id": "release-wrapper-privacy-consent-promotion-gate",
                "status": "not-linked",
                "passed": True,
                "update_id": _safe_ref(update_id),
                "blocked_action": action,
                "endpoint_ref": endpoint_ref,
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        metadata = proposal.get("metadata") if isinstance(proposal.get("metadata"), dict) else {}
        safe_payload = metadata.get("safe_payload") if isinstance(metadata.get("safe_payload"), dict) else {}
        session_ref_digest = str(metadata.get("session_ref_digest") or self._self_repair_session_ref_digest(proposal) or "")
        queue_id = str(metadata.get("improvement_queue_id") or safe_payload.get("improvement_queue_id") or "")
        federated_packet_import_id = str(
            metadata.get("federated_packet_import_id")
            or safe_payload.get("federated_packet_import_id")
            or ""
        )
        federated_packet_id = str(
            metadata.get("federated_packet_id")
            or safe_payload.get("federated_packet_id")
            or ""
        )
        enforcement = self._privacy_consent_enforcement_summary(
            session_ref_digest=session_ref_digest or None
        )
        queue_block = next(
            (
                block
                for block in enforcement.get("queue_blocks") or []
                if isinstance(block, dict) and str(block.get("queue_id") or "") == queue_id
            ),
            None,
        )
        import_block = next(
            (
                block
                for block in enforcement.get("federated_import_blocks") or []
                if isinstance(block, dict) and str(block.get("import_id") or "") == federated_packet_import_id
            ),
            None,
        )
        packet_block = next(
            (
                block
                for block in enforcement.get("federated_packet_blocks") or []
                if isinstance(block, dict) and str(block.get("packet_id") or "") == federated_packet_id
            ),
            None,
        )
        fallback_queue_block: dict[str, Any] | None = None
        if queue_block is None and queue_id and self.improvement_queue is not None:
            try:
                item = ImprovementQueue(self.improvement_queue.storage_path).get(queue_id)
                item_metadata = item.event.metadata if isinstance(item.event.metadata, dict) else {}
            except KeyError:
                item_metadata = {}
            consent_policy = {
                "personal_data_training_opt_in": item_metadata.get("personal_data_training_opt_in"),
                "personal_data_federation_allowed": item_metadata.get("personal_data_federation_allowed"),
                "personal_data_dream_training_allowed": item_metadata.get("dream_training_personal_data_allowed"),
            }
            if item_metadata and self._privacy_consent_blocks_personal_data_policy(
                session_ref_digest=session_ref_digest or None,
                consent_policy=consent_policy,
            ):
                fallback_queue_block = {
                    "queue_id": queue_id,
                    "federated_packet_import_id": item_metadata.get("federated_packet_import_id"),
                    "federated_packet_id": item_metadata.get("federated_packet_id"),
                    "privacy_consent_record_id": item_metadata.get("privacy_consent_record_id"),
                    "quarantine_state": "blocked-by-revocation",
                    "active_personal_data_training_allowed": False,
                    "raw_content_included": False,
                    "contains_personal_data": False,
                }
        matched_block = queue_block or import_block or packet_block or fallback_queue_block
        if matched_block is None:
            return {
                "surface_id": "release-wrapper-privacy-consent-promotion-gate",
                "status": "passed",
                "passed": True,
                "update_id": _safe_ref(update_id),
                "blocked_action": action,
                "endpoint_ref": endpoint_ref,
                "queue_id": queue_id or None,
                "federated_packet_import_id": federated_packet_import_id or None,
                "privacy_consent_enforcement": {
                    "surface_id": enforcement.get("surface_id"),
                    "status": enforcement.get("status"),
                    "latest_record_id": enforcement.get("latest_record_id"),
                    "record_count": enforcement.get("record_count"),
                    "raw_content_included": False,
                    "active_production_mutation_allowed": False,
                },
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        return {
            "surface_id": "release-wrapper-privacy-consent-promotion-gate",
            "status": "blocked-privacy-consent-revoked-personal-data-artifact",
            "passed": False,
            "update_id": _safe_ref(update_id),
            "blocked_action": action,
            "endpoint_ref": endpoint_ref,
            "queue_id": queue_id or matched_block.get("queue_id"),
            "federated_packet_import_id": federated_packet_import_id or matched_block.get("import_id"),
            "federated_packet_id": federated_packet_id or matched_block.get("packet_id"),
            "matched_block": matched_block,
            "blocked_capabilities": list(enforcement.get("blocked_capabilities") or []),
            "privacy_consent_enforcement": {
                "surface_id": enforcement.get("surface_id"),
                "status": enforcement.get("status"),
                "latest_record_id": enforcement.get("latest_record_id"),
                "record_count": enforcement.get("record_count"),
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            },
            "raw_content_included": False,
            "contains_personal_data": False,
            "active_production_mutation_allowed": False,
        }

    def _federated_packet_outbox_summary(
        self,
        *,
        session_ref_digest: str | None,
        interactions: list[dict[str, Any]],
        packets: list[dict[str, Any]],
    ) -> dict[str, Any]:
        latest_interaction = interactions[0] if interactions else None
        latest_packet = packets[0] if packets else None
        return {
            "schema_version": "nexusnet-release-wrapper-federated-packet-outbox-v1",
            "surface_id": "release-wrapper-federated-packet-outbox",
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": "live-bound" if packets else "empty",
            "session_ref_digest": session_ref_digest,
            "endpoint_ref": "/ops/wrapper/federated-packets",
            "packet_count": len(packets),
            "global_packet_count": len(self._federated_packets),
            "latest_packet": latest_packet,
            "packets": packets[:20],
            "privacy_consent": self._privacy_consent_summary(session_ref_digest=session_ref_digest),
            "privacy_consent_enforcement": self._privacy_consent_enforcement_summary(
                session_ref_digest=session_ref_digest
            ),
            "latest_interaction_ref": (
                f"trace::{latest_interaction.get('trace_id')}"
                if isinstance(latest_interaction, dict) and latest_interaction.get("trace_id")
                else None
            ),
            "packet_refs": [str(packet.get("packet_id") or "") for packet in packets[:50] if packet.get("packet_id")],
            "artifact_ref": "release-wrapper-runtime/events.jsonl",
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.event_log_path))}",
            "replay": dict(self._replay_status),
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "sanitized-federated-packets-and-trace-refs-only-no-raw-prompts-outputs-session-ids",
        }

    def _federated_packet_inbox_summary(
        self,
        *,
        session_ref_digest: str | None,
        imports: list[dict[str, Any]],
    ) -> dict[str, Any]:
        latest_import = imports[0] if imports else None
        accepted_import_count = sum(
            1 for record in imports if record.get("status") == "quarantined-shadow-accepted"
        )
        rejected_import_count = sum(
            1 for record in imports if record.get("status") == "quarantined-rejected"
        )
        degraded_import_count = sum(
            1 for record in imports if record.get("status") == "quarantined-shadow-degraded"
        )
        return {
            "schema_version": "nexusnet-release-wrapper-federated-packet-inbox-v1",
            "surface_id": "release-wrapper-federated-packet-inbox",
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "status": "shadow-quarantine-active" if imports else "empty",
            "session_ref_digest": session_ref_digest,
            "endpoint_ref": "/ops/wrapper/federated-packets/imports",
            "import_ref": "/ops/wrapper/federated-packets/import",
            "import_count": len(imports),
            "accepted_import_count": accepted_import_count,
            "rejected_import_count": rejected_import_count,
            "degraded_import_count": degraded_import_count,
            "global_import_count": len(self._federated_packet_imports),
            "latest_import": latest_import,
            "imports": imports[:20],
            "privacy_consent_enforcement": self._privacy_consent_enforcement_summary(
                session_ref_digest=session_ref_digest
            ),
            "import_refs": [
                str(record.get("import_id") or "") for record in imports[:50] if record.get("import_id")
            ],
            "artifact_ref": "release-wrapper-runtime/federated-packet-imports.jsonl",
            "artifact_path_digest": f"sha256:{_privacy_digest(str(self.federated_import_log_path))}",
            "replay": dict(self._federated_packet_import_replay_status),
            "quarantine_state": "shadow-only",
            "raw_content_included": False,
            "contains_personal_data": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "sanitized-peer-packet-digests-refs-and-status-only-no-raw-prompts-outputs-session-ids",
        }

    def import_federated_packet(
        self,
        *,
        packet: dict[str, Any],
        session_id: str | None = None,
        peer_node_id: str | None = None,
    ) -> dict[str, Any]:
        packet_payload = packet if isinstance(packet, dict) else {}
        session_ref_digest = _session_ref_digest(session_id)
        created_at = utcnow().isoformat()
        packet_id = str(packet_payload.get("packet_id") or "")
        packet_digest = _privacy_digest(json.dumps(packet_payload, sort_keys=True, default=str))
        peer_node_ref_digest = f"sha256:{_privacy_digest(str(peer_node_id or packet_id or 'anonymous-peer'))}"
        source_packet_ref = f"federated-packet::{packet_id or packet_digest}"
        route_metadata = (
            packet_payload.get("route_metadata") if isinstance(packet_payload.get("route_metadata"), dict) else {}
        )
        learning_metadata = (
            packet_payload.get("learning_metadata") if isinstance(packet_payload.get("learning_metadata"), dict) else {}
        )
        security_envelope = (
            packet_payload.get("security_envelope")
            if isinstance(packet_payload.get("security_envelope"), dict)
            else {}
        )
        signed_packet = (
            security_envelope.get("signed_packet")
            if isinstance(security_envelope.get("signed_packet"), dict)
            else {}
        )
        privacy_audit = (
            security_envelope.get("privacy_audit")
            if isinstance(security_envelope.get("privacy_audit"), dict)
            else {}
        )
        consent_policy = (
            packet_payload.get("consent_policy")
            if isinstance(packet_payload.get("consent_policy"), dict)
            else _privacy_consent_policy_for_packet(None)
        )
        packet_authority_evidence_tool_governance = (
            packet_payload.get("authority_evidence_tool_governance")
            if isinstance(packet_payload.get("authority_evidence_tool_governance"), dict)
            else {}
        )
        privacy_consent_enforcement = self._privacy_consent_enforcement_summary(
            session_ref_digest=session_ref_digest
        )
        privacy_consent_blocks_personal_data_import = self._privacy_consent_blocks_personal_data_policy(
            session_ref_digest=session_ref_digest,
            consent_policy=consent_policy,
        )
        packet_raw_content_clear = packet_payload.get("raw_content_included") is False
        packet_personal_data_clear = packet_payload.get("contains_personal_data") is False
        signed_packet_clear = signed_packet.get("raw_private_data_exported") is False
        privacy_audit_clear = not privacy_audit or privacy_audit.get("raw_private_data_exported") is False
        security_envelope_verified = bool(
            packet_id
            and packet_raw_content_clear
            and packet_personal_data_clear
            and signed_packet_clear
            and privacy_audit_clear
        )
        selected_terms = [
            _safe_ref(str(term))
            for term in (route_metadata.get("selected_capability_terms") or [])
            if str(term).strip()
        ]
        expert_node = str(
            packet_payload.get("expert_node")
            or packet_payload.get("selected_expert")
            or (f"federated_shadow::{selected_terms[0]}" if selected_terms else "federated_shadow::general")
        )
        source_model = f"federated-peer::{_privacy_digest(str(peer_node_id or packet_id or 'anonymous-peer'))}"
        quality = _float_metric(
            learning_metadata.get("final_confidence")
            if "final_confidence" in learning_metadata
            else learning_metadata.get("quality")
        )
        if quality <= 0.0:
            quality = 1.0
        import_id = f"fed-import::{_privacy_digest('|'.join([packet_id, packet_digest, peer_node_ref_digest, created_at]))}"
        knowledge_ref = f"federated-packet-import::{packet_digest}"
        assimilation_shadow_captured = False
        global_growth_shadow_captured = False
        shadow_error: str | None = None
        if security_envelope_verified and not privacy_consent_blocks_personal_data_import:
            try:
                self.continuous_assimilation.assimilate(
                    source_model=source_model,
                    expert_node=expert_node,
                    task="federated-import-shadow",
                    quality=quality,
                    knowledge_ref=knowledge_ref,
                    metadata={
                        "federated_packet_import": True,
                        "source_packet_ref": source_packet_ref,
                        "peer_node_ref_digest": peer_node_ref_digest,
                        "raw_content_included": False,
                        "active_production_mutation_allowed": False,
                    },
                )
                assimilation_shadow_captured = True
                self.global_growth.assimilate_for_user(
                    session_ref_digest or peer_node_ref_digest,
                    source_model=source_model,
                    expert_node=expert_node,
                    quality=quality,
                    knowledge_ref=knowledge_ref,
                )
                global_growth_shadow_captured = True
            except Exception as exc:  # pragma: no cover - defensive status path
                shadow_error = type(exc).__name__
        status = (
            "quarantined-shadow-blocked-by-consent-revocation"
            if security_envelope_verified and privacy_consent_blocks_personal_data_import
            else
            "quarantined-shadow-accepted"
            if security_envelope_verified and assimilation_shadow_captured and global_growth_shadow_captured
            else "quarantined-shadow-degraded"
            if security_envelope_verified
            else "quarantined-rejected"
        )
        record = {
            "schema_version": "nexusnet-release-wrapper-federated-packet-import-v1",
            "surface_id": "release-wrapper-federated-packet-import",
            "import_id": import_id,
            "created_at": created_at,
            "status": status,
            "authority": "NexusBrain",
            "status_label": "LOCKED CANON",
            "session_ref_digest": session_ref_digest,
            "peer_node_ref_digest": peer_node_ref_digest,
            "source_packet_ref": source_packet_ref,
            "packet_digest": f"sha256:{packet_digest}",
            "source_model": source_model,
            "expert_node": expert_node,
            "quality": quality,
            "security_envelope_verified": security_envelope_verified,
            "consent_policy": consent_policy,
            "privacy_consent_record_id": consent_policy.get("record_id"),
            "consent_basis": consent_policy.get("consent_basis"),
            "runtime_growth_receipt_id": packet_authority_evidence_tool_governance.get("runtime_growth_receipt_id"),
            "runtime_growth_federated_packet_id": (
                packet_authority_evidence_tool_governance.get("federated_packet_id")
            ),
            "authority_evidence_tool_governance": packet_authority_evidence_tool_governance or None,
            "privacy_consent_enforcement": privacy_consent_enforcement,
            "privacy_consent_import_gate": {
                "surface_id": "release-wrapper-privacy-consent-federated-import-gate",
                "status": (
                    "blocked-privacy-consent-revoked-personal-data-artifact"
                    if privacy_consent_blocks_personal_data_import
                    else "passed"
                ),
                "passed": not privacy_consent_blocks_personal_data_import,
                "latest_enforcement_record_id": privacy_consent_enforcement.get("latest_record_id"),
                "active_personal_data_training_allowed": not privacy_consent_blocks_personal_data_import,
                "raw_content_included": False,
                "contains_personal_data": False,
                "active_production_mutation_allowed": False,
            },
            "security_checks": {
                "packet_id_present": bool(packet_id),
                "raw_content_clear": packet_raw_content_clear,
                "personal_data_clear": packet_personal_data_clear,
                "signed_packet_raw_private_data_clear": signed_packet_clear,
                "privacy_audit_clear": privacy_audit_clear,
            },
            "quarantine_state": (
                "blocked-by-revocation"
                if privacy_consent_blocks_personal_data_import
                else "shadow-only"
                if security_envelope_verified
                else "blocked"
            ),
            "assimilation_shadow_captured": assimilation_shadow_captured,
            "global_growth_shadow_captured": global_growth_shadow_captured,
            "shadow_error_type": shadow_error,
            "raw_content_included": False,
            "contains_personal_data": False,
            "active_production_mutation_allowed": False,
            "mutation_boundary": "quarantined-shadow-learning-only-no-active-routing-production-or-safe-file-mutation",
            "privacy_boundary": "sanitized-peer-packet-digests-refs-and-status-only-no-raw-prompts-outputs-session-ids",
        }
        if status == "quarantined-shadow-accepted":
            record["evals_ao_artifact_gate"] = self._record_federated_import_evals_ao_artifact_gate(record=record)
            self._queue_federated_import_dream_research(record)
        record["operation_receipt"] = _build_runtime_operation_receipt(
            operation_type="federated_packet_import",
            operation_ref=import_id,
            observed_status=status,
            session_ref_digest=session_ref_digest,
            stages={
                "security_envelope": {
                    "status": "covered" if security_envelope_verified else "degraded",
                    "evidence_refs": [source_packet_ref, f"packet-digest::sha256:{packet_digest}"],
                    "blocker": "" if security_envelope_verified else "security_envelope_not_verified",
                },
                "shadow_quarantine": {
                    "status": "covered" if status == "quarantined-shadow-accepted" else "degraded",
                    "evidence_refs": [f"federated-packet-import::{import_id}"],
                    "blocker": "" if status == "quarantined-shadow-accepted" else status,
                },
                "privacy_consent_enforcement": {
                    "status": "covered" if not privacy_consent_blocks_personal_data_import else "blocked",
                    "evidence_refs": [
                        f"privacy-consent-enforcement::{privacy_consent_enforcement.get('latest_record_id')}"
                    ]
                    if privacy_consent_enforcement.get("latest_record_id")
                    else [],
                    "blocker": (
                        "privacy_consent_revoked_personal_data_import"
                        if privacy_consent_blocks_personal_data_import
                        else ""
                    ),
                },
                "continuous_assimilation": {
                    "status": "covered" if assimilation_shadow_captured else "degraded",
                    "evidence_refs": [f"assimilation-node::{expert_node}"],
                    "blocker": "" if assimilation_shadow_captured else "assimilation_shadow_not_captured",
                },
                "global_growth": {
                    "status": "covered" if global_growth_shadow_captured else "degraded",
                    "evidence_refs": [f"global-growth::{session_ref_digest or peer_node_ref_digest}"],
                    "blocker": "" if global_growth_shadow_captured else "global_growth_shadow_not_captured",
                },
                "evals_ao_artifact_gate": {
                    "status": "covered"
                    if (record.get("evals_ao_artifact_gate") or {}).get("status") == "passed-shadow"
                    else "degraded",
                    "evidence_refs": _compact_refs(
                        record.get("evals_ao_artifact_gate")
                        if isinstance(record.get("evals_ao_artifact_gate"), dict)
                        else {},
                        ["gate_id", "status"],
                    ),
                    "blocker": ""
                    if (record.get("evals_ao_artifact_gate") or {}).get("status") == "passed-shadow"
                    else "evals_ao_artifact_gate_missing_or_blocked",
                },
                "dream_research_queue": {
                    "status": "covered" if record.get("dream_research_queue_id") else "degraded",
                    "evidence_refs": [f"dream-research-queue::{record.get('dream_research_queue_id')}"]
                    if record.get("dream_research_queue_id")
                    else [],
                    "blocker": "" if record.get("dream_research_queue_id") else "dream_research_queue_item_missing",
                },
            },
            active_production_mutated=False,
        )
        record["whole_system_enforcement_receipt"] = _build_federated_import_whole_system_enforcement_receipt(
            record=record,
            operation_receipt=record["operation_receipt"],
        )
        record["whole_system_enforcement_receipt_id"] = record["whole_system_enforcement_receipt"]["receipt_id"]
        self._federated_packet_imports.insert(0, record)
        self._federated_packet_imports = self._federated_packet_imports[:100]
        self._persist_federated_packet_import(record)
        return record

    def _provider_readiness_summary(
        self,
        *,
        interactions: list[dict[str, Any]] | None = None,
        session_ref_digest: str | None = None,
        latest_active_provider_id: str | None = None,
    ) -> dict[str, Any]:
        active_provider_ids = [
            str(interaction.get("provider_id") or interaction.get("source_model") or "")
            for interaction in (interactions or [])
            if isinstance(interaction, dict)
            and str(interaction.get("provider_id") or interaction.get("source_model") or "")
        ]
        latest_active_provider_id = latest_active_provider_id or (active_provider_ids[0] if active_provider_ids else None)
        if self.provider_registry is None or not hasattr(self.provider_registry, "readiness"):
            return _empty_provider_readiness(
                session_ref_digest=session_ref_digest,
                latest_active_provider_id=latest_active_provider_id,
                active_provider_ids=active_provider_ids,
            )
        try:
            readiness = self.provider_registry.readiness(
                active_provider_ids=active_provider_ids,
                latest_active_provider_id=latest_active_provider_id,
            )
        except Exception as exc:  # pragma: no cover - defensive provider registry boundary
            readiness = _empty_provider_readiness(
                session_ref_digest=session_ref_digest,
                latest_active_provider_id=latest_active_provider_id,
                active_provider_ids=active_provider_ids,
            )
            readiness["status"] = "degraded"
            readiness["blockers"] = [f"provider_readiness_unavailable::{_safe_ref(type(exc).__name__)}"]
        readiness["session_ref_digest"] = session_ref_digest
        return readiness

    def _provider_readiness_status(self, provider_id: str) -> str:
        readiness = self._provider_readiness_summary(
            interactions=[],
            latest_active_provider_id=provider_id,
        )
        for provider in readiness.get("providers") or []:
            if isinstance(provider, dict) and provider.get("provider_id") == provider_id:
                return str(provider.get("status") or "unknown-provider")
        return "unknown-provider"

    def _release_manifest_status_rollup(self) -> dict[str, Any]:
        if self.production_spine is None:
            return _empty_release_manifest_status_rollup()
        try:
            scorecard = self.production_spine.scorecard()
        except Exception as exc:  # pragma: no cover - defensive production-spine boundary
            rollup = _empty_release_manifest_status_rollup()
            rollup["status"] = "degraded"
            rollup["blockers"] = [f"production_spine_scorecard_unavailable::{_safe_ref(type(exc).__name__)}"]
            rollup["control_panel_label"] = "Release manifest rollup unavailable"
            return rollup
        source_rollup = scorecard.get("release_manifest_status_rollup") if isinstance(scorecard, dict) else None
        if not isinstance(source_rollup, dict):
            return _empty_release_manifest_status_rollup()
        rollup = json.loads(json.dumps(source_rollup))
        latest_refs = rollup.pop("latest_refs", {}) if isinstance(rollup.get("latest_refs"), dict) else {}
        rollup["latest_ref_digests"] = {
            str(key): f"sha256:{_privacy_digest(str(value))}" if value else None
            for key, value in latest_refs.items()
        }
        rollup["source"] = "production-spine-scorecard"
        rollup["raw_content_included"] = False
        rollup["active_production_mutation_allowed"] = False
        rollup["privacy_boundary"] = "status-booleans-and-digested-artifact-refs-only-no-local-paths-or-secrets"
        return rollup

    def _teacher_expert_birth_registry_summary(
        self,
        *,
        session_ref_digest: str | None = None,
    ) -> dict[str, Any]:
        blockers: list[str] = []
        profile_count = 0
        assignment_count = 0
        live_core_expert_pair_count = 0
        auxiliary_count = 0
        core_expert_count = 0
        schema_version: int | None = None
        default_registry_layer = "unknown"
        schema_manifest_ref: str | None = None

        if self.teacher_registry is None:
            blockers.append("teacher_registry_unavailable")
        else:
            try:
                profiles = self.teacher_registry.list_profiles()
                assignments = self.teacher_registry.list_assignments()
                metadata = self.teacher_registry.metadata()
                profile_count = len(profiles)
                assignment_count = len(assignments)
                schema_version = metadata.get("schema_version")
                default_registry_layer = str(metadata.get("default_registry_layer") or "unknown")
                schema_manifest_path = metadata.get("schema_manifest_path")
                if schema_manifest_path:
                    schema_manifest_ref = f"teacher-schema-manifest::sha256:{_privacy_digest(str(schema_manifest_path))}"
                live_core_expert_pair_count = sum(
                    1
                    for assignment in assignments
                    if getattr(assignment, "registry_layer", None) == "v2026_live"
                    and getattr(assignment, "subject", None) != "core-brain"
                    and not bool(getattr(assignment, "auxiliary", False))
                    and bool(getattr(assignment, "primary_teacher_id", None))
                    and bool(getattr(assignment, "secondary_teacher_id", None))
                )
                auxiliary_count = sum(
                    1
                    for assignment in assignments
                    if getattr(assignment, "registry_layer", None) == "v2026_live"
                    and bool(getattr(assignment, "auxiliary", False))
                )
                core_expert_count = live_core_expert_pair_count
            except Exception as exc:  # pragma: no cover - defensive registry boundary
                blockers.append(f"teacher_registry_unreadable::{_safe_ref(type(exc).__name__)}")

        hive_surface_id = "unavailable"
        hive_runtime_state = "unavailable"
        plane_count = 0
        node_count = 0
        node_registry_update_count = 0
        ivy_review_count = 0
        certified_candidate_count = 0
        if self.hive_substrate is None:
            blockers.append("hive_substrate_unavailable")
        else:
            try:
                hive_summary = self.hive_substrate.summary()
                hive_surface_id = str(hive_summary.get("surface_id") or "unknown")
                hive_runtime_state = str(hive_summary.get("runtime_state") or "unknown")
                plane_count = int(hive_summary.get("plane_count") or 0)
                node_count = int(hive_summary.get("node_count") or 0)
                node_registry = (
                    hive_summary.get("node_registry") if isinstance(hive_summary.get("node_registry"), dict) else {}
                )
                ivy_school = (
                    hive_summary.get("ivy_league_school")
                    if isinstance(hive_summary.get("ivy_league_school"), dict)
                    else {}
                )
                node_registry_update_count = int(node_registry.get("update_count") or 0)
                ivy_review_count = int(ivy_school.get("review_count") or 0)
                certified_candidate_count = int(ivy_school.get("certified_candidate_count") or 0)
            except Exception as exc:  # pragma: no cover - defensive substrate boundary
                blockers.append(f"hive_substrate_unreadable::{_safe_ref(type(exc).__name__)}")

        if default_registry_layer != "v2026_live":
            blockers.append("teacher_registry_default_layer_not_v2026_live")
        if schema_version != 2:
            blockers.append("teacher_registry_schema_version_not_2")
        if live_core_expert_pair_count < 19:
            blockers.append("live_core_expert_pairs_below_canon_19")
        if core_expert_count < 19:
            blockers.append("core_expert_roster_below_canon_19")
        if plane_count <= 0 or node_count <= 0:
            blockers.append("hive_birth_substrate_nodes_or_planes_missing")

        evidence_refs = _dedupe_strings(
            [
                "/ops/brain/teachers",
                "/ops/brain/canon/hive-substrate",
                "nexusnet.teachers.TeacherRegistry.metadata",
                "nexusnet.hive.net.birth_expert_node",
                "nexusnet.hive.net.birth_hive",
                "tests/test_teacher_registry.py",
                "tests/test_hive_birth_orchestrator.py",
                f"teacher_profiles::{profile_count}",
                f"teacher_assignments::{assignment_count}",
                f"live_core_expert_pairs::{live_core_expert_pair_count}",
                f"hive_nodes::{node_count}",
                f"hive_planes::{plane_count}",
            ]
        )
        if schema_manifest_ref:
            evidence_refs.append(schema_manifest_ref)

        status = "pass" if not blockers else "blocked"
        return {
            "surface_id": "teacher-expert-birth-registry-release-gate",
            "status_label": "LOCKED CANON",
            "authority": "NexusBrain",
            "status": status,
            "session_ref_digest": session_ref_digest,
            "teacher_registry": {
                "status": "pass" if self.teacher_registry is not None and not any("teacher_registry" in item for item in blockers) else "blocked",
                "default_registry_layer": default_registry_layer,
                "schema_version": schema_version,
                "profile_count": profile_count,
                "assignment_count": assignment_count,
                "live_core_expert_pair_count": live_core_expert_pair_count,
                "schema_manifest_ref": schema_manifest_ref,
                "metadata_ref": "nexusnet.teachers.TeacherRegistry.metadata",
                "api_ref": "/ops/brain/teachers",
            },
            "expert_roster": {
                "status": "pass" if core_expert_count >= 19 else "blocked",
                "canon_core_expert_target": 19,
                "core_expert_count": core_expert_count,
                "auxiliary_count": auxiliary_count,
                "registry_layer": "v2026_live",
            },
            "birth_stack": {
                "status": "pass" if plane_count > 0 and node_count > 0 and self.hive_substrate is not None else "blocked",
                "surface_id": hive_surface_id,
                "runtime_state": hive_runtime_state,
                "plane_count": plane_count,
                "node_count": node_count,
                "node_registry_update_count": node_registry_update_count,
                "ivy_review_count": ivy_review_count,
                "certified_candidate_count": certified_candidate_count,
                "birth_orchestrator_ref": "nexusnet.hive.net.birth_hive",
                "expert_node_birth_ref": "nexusnet.hive.net.birth_expert_node",
                "scorecard_ref": "/ops/brain/canon/hive-substrate",
                "summary_ref": "/ops/brain/hive-substrate",
            },
            "blockers": blockers,
            "evidence_refs": evidence_refs,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "counts-statuses-endpoint-refs-and-digested-manifest-ref-only-no-prompts-outputs-or-local-paths",
            "mutation_boundary": "readiness-projection-only-no-teacher-or-birth-mutation",
        }

