            restored["boot_supervisor"] = boot_supervisor
            restored["initial_release_supervisor"] = initial_release_supervisor
            restored["release_product_smoke"] = release_product_smoke
            restored["release_run_history"] = release_run_history
            restored["release_health_heartbeat"] = release_health_heartbeat
            restored["release_health_heartbeat_loop"] = release_health_heartbeat_loop
