    def _quarantine_production_spine_lifecycle_artifacts(
        self,
        *,
        artifact_base: Path,
        artifact_root: Path,
        quarantine_base: Path,
        quarantine_root: Path,
    ) -> dict[str, Any]:
        source_inside = artifact_base in artifact_root.parents or artifact_root == artifact_base
        quarantine_inside = quarantine_base in quarantine_root.parents or quarantine_root == quarantine_base
        if not source_inside or not quarantine_inside:
            return {
                "status": "blocked-path-boundary",
                "source_ref_digest": f"sha256:{_privacy_digest(str(artifact_root))}",
                "quarantine_ref_digest": f"sha256:{_privacy_digest(str(quarantine_root))}",
                "entry_count": 0,
                "file_count": 0,
                "byte_count": 0,
                "active_production_mutated": False,
                "release_mutation_allowed": False,
                "raw_content_included": False,
                "privacy_boundary": "digested-path-boundary-status-only-no-local-paths",
            }

        if not artifact_root.exists():
            return {
                "status": "not-present",
                "source_ref_digest": f"sha256:{_privacy_digest(str(artifact_root))}",
                "quarantine_ref_digest": f"sha256:{_privacy_digest(str(quarantine_root))}",
                "entry_count": 0,
                "file_count": 0,
                "byte_count": 0,
                "active_production_mutated": False,
                "release_mutation_allowed": False,
                "raw_content_included": False,
                "privacy_boundary": "digested-artifact-status-only-no-local-paths",
            }

        entries = [path for path in artifact_root.rglob("*")]
        files = [path for path in entries if path.is_file()]
        file_count = len(files)
        byte_count = sum(path.stat().st_size for path in files)
        quarantine_root.parent.mkdir(parents=True, exist_ok=True)
        final_quarantine_root = quarantine_root
        if final_quarantine_root.exists():
            final_quarantine_root = quarantine_root.with_name(
                f"{quarantine_root.name}-{_privacy_digest(str(file_count) + str(byte_count))}"
            )
        shutil.move(str(artifact_root), str(final_quarantine_root))
        return {
            "status": "quarantined",
            "source_ref_digest": f"sha256:{_privacy_digest(str(artifact_root))}",
            "quarantine_ref_digest": f"sha256:{_privacy_digest(str(final_quarantine_root))}",
            "entry_count": len(entries),
            "file_count": file_count,
            "byte_count": byte_count,
            "active_production_mutated": False,
            "release_mutation_allowed": False,
            "raw_content_included": False,
            "privacy_boundary": "digested-artifact-quarantine-status-counts-only-no-local-paths",
        }

