    def _record_external_evals_ao_artifact_gate(
        self,
        *,
        trace_id: str,
        result: Any,
        interaction: dict[str, Any],
        cache_state: dict[str, Any],
        scorecard: dict[str, Any],
        route_decision: dict[str, Any],
        quantization_state: dict[str, Any],
    ) -> dict[str, Any]:
        safe_trace = _safe_ref(trace_id)
        gate_id = f"evals-ao-artifact::release-wrapper::{safe_trace}"
        relative_root = Path("evals") / "ao" / "release-wrapper" / safe_trace
        destination = self.artifacts_dir / relative_root
        created_at = utcnow().isoformat()
        eval_refs = [str(ref) for ref in scorecard.get("eval_refs") or [] if str(ref or "")]
        trace_ref = f"trace::{safe_trace}"
        artifact_refs = {
            "decision": (relative_root / "decision.json").as_posix(),
            "metrics": (relative_root / "metrics.json").as_posix(),
            "report": (relative_root / "report.md").as_posix(),
            "scenarios": (relative_root / "scenarios.jsonl").as_posix(),
        }
        artifact_path_digests = {
            name: f"sha256:{_privacy_digest(str(self.artifacts_dir / relative_path))}"
            for name, relative_path in artifact_refs.items()
        }
        base_promotion_allowed = (
            str(getattr(result, "status", None) or "") != "error"
            and cache_state.get("promotion_allowed") is True
            and scorecard.get("status") in {"measured", "warning"}
            and bool(eval_refs)
        )
        findings: list[str] = []
        if not eval_refs:
            findings.append("evals_ao_artifact_gate_requires_eval_refs")
        if scorecard.get("status") not in {"measured", "warning"}:
            findings.append("evals_ao_artifact_gate_requires_measured_runtime_scorecard")
        if cache_state.get("promotion_allowed") is not True:
            findings.append("evals_ao_artifact_gate_requires_cache_promotion")
        if str(getattr(result, "status", None) or "") == "error":
            findings.append("evals_ao_artifact_gate_blocks_error_result")
        metrics = {
            "surface_id": "external-evals-ao-artifact-gate",
            "authority": "NexusBrain",
            "ao": "EvalsAO",
            "gate_id": gate_id,
            "created_at": created_at,
            "trace_ref": trace_ref,
            "session_ref_digest": interaction.get("session_ref_digest"),
            "runtime_scorecard_id": scorecard.get("scorecard_id"),
            "runtime_scorecard_status": scorecard.get("status") or "missing",
            "cache_entry_id": cache_state.get("latest_cache_entry_id"),
            "cache_promotion_allowed": cache_state.get("promotion_allowed") is True,
            "route_status": route_decision.get("status") or "unknown",
            "quantization_status": quantization_state.get("status") or "unknown",
            "eval_ref_count": len(eval_refs),
            "finding_count": len(findings),
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }
        decision = {
            "surface_id": "external-evals-ao-artifact-gate",
            "authority": "NexusBrain",
            "ao": "EvalsAO",
            "gate_id": gate_id,
            "created_at": created_at,
            "decision": "passed-shadow" if base_promotion_allowed and not findings else "blocked",
            "promotion_allowed": base_promotion_allowed and not findings,
            "findings": findings,
            "trace_ref": trace_ref,
            "session_ref_digest": interaction.get("session_ref_digest"),
            "artifact_refs": artifact_refs,
            "artifact_path_digests": artifact_path_digests,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "promotion_boundary": "external-evals-ao-artifact-gate-is-shadow-only-and-does-not-mutate-production",
        }
        scenario = {
            "scenario_id": f"release-wrapper-live-model-interaction::{safe_trace}",
            "surface_id": "external-evals-ao-artifact-scenario",
            "trace_ref": trace_ref,
            "session_ref_digest": interaction.get("session_ref_digest"),
            "source_model_ref": f"model::{_safe_ref(str(interaction.get('source_model') or 'wrapped-model'))}",
            "selected_expert": interaction.get("expert_node"),
            "selected_ao": interaction.get("selected_ao"),
            "cache_entry_id": cache_state.get("latest_cache_entry_id"),
            "runtime_scorecard_id": scorecard.get("scorecard_id"),
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }
        report = "\n".join(
            [
                f"# External EvalsAO Artifact Gate {gate_id}",
                "",
                f"- Decision: {decision['decision']}",
                f"- Runtime scorecard: {metrics['runtime_scorecard_id'] or 'missing'}",
                f"- Cache entry: {metrics['cache_entry_id'] or 'missing'}",
                f"- Eval refs: {metrics['eval_ref_count']}",
                "",
                "This artifact set is generated from sanitized wrapper runtime refs only.",
                "It remains shadow-only and does not grant active production mutation.",
            ]
        )
        try:
            destination.mkdir(parents=True, exist_ok=True)
            (destination / "metrics.json").write_text(json.dumps(metrics, indent=2, sort_keys=True), encoding="utf-8")
            (destination / "decision.json").write_text(json.dumps(decision, indent=2, sort_keys=True), encoding="utf-8")
            (destination / "report.md").write_text(report, encoding="utf-8")
            (destination / "scenarios.jsonl").write_text(json.dumps(scenario, sort_keys=True) + "\n", encoding="utf-8")
        except OSError as exc:
            return {
                "surface_id": "external-evals-ao-artifact-gate",
                "authority": "NexusBrain",
                "ao": "EvalsAO",
                "gate_id": gate_id,
                "status": "blocked",
                "promotion_allowed": False,
                "artifact_set_complete": False,
                "artifact_refs": {},
                "artifact_path_digests": {},
                "findings": [*findings, f"evals_ao_artifact_write_failed::{type(exc).__name__}"],
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        artifact_set_complete = all((self.artifacts_dir / relative_path).is_file() for relative_path in artifact_refs.values())
        promotion_allowed = decision["promotion_allowed"] is True and artifact_set_complete
        eval_registry_ref = self._register_runtime_evals_ao_artifact_gate(
            gate_id=gate_id,
            trace_ref=trace_ref,
            artifact_refs=artifact_refs,
            artifact_set_complete=artifact_set_complete,
            metrics=metrics,
            findings=findings,
            interaction=interaction,
        )
        return {
            "surface_id": "external-evals-ao-artifact-gate",
            "authority": "NexusBrain",
            "ao": "EvalsAO",
            "gate_id": gate_id,
            "status": "passed-shadow" if promotion_allowed else "blocked",
            "promotion_allowed": promotion_allowed,
            "artifact_set_complete": artifact_set_complete,
            "artifact_refs": artifact_refs,
            "artifact_path_digests": artifact_path_digests,
            "decision_ref": artifact_refs["decision"],
            "metrics_ref": artifact_refs["metrics"],
            "report_ref": artifact_refs["report"],
            "scenarios_ref": artifact_refs["scenarios"],
            "eval_registry_ref": eval_registry_ref,
            "findings": findings,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "sanitized-eval-artifact-refs-and-digests-only-no-raw-prompts-outputs-session-ids-or-local-paths",
            "mutation_boundary": "shadow-evals-ao-gate-only-no-active-production-mutation",
        }

    def _register_runtime_evals_ao_artifact_gate(
        self,
        *,
        gate_id: str,
        trace_ref: str,
        artifact_refs: dict[str, str],
        artifact_set_complete: bool,
        metrics: dict[str, Any],
        findings: list[str],
        interaction: dict[str, Any],
    ) -> dict[str, Any]:
        safe_gate = _safe_ref(gate_id)
        suite_id = f"eval::release-wrapper-runtime::{safe_gate}"
        shadow_run_id = f"shadow-run::release-wrapper-runtime::{safe_gate}"
        if self.eval_registry is None or not hasattr(self.eval_registry, "register"):
            return {
                "surface_id": "eval-registry-runtime-evals-ao-link",
                "status": "not-configured",
                "suite_id": suite_id,
                "shadow_run_id": shadow_run_id,
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        evidence_refs = [
            gate_id,
            trace_ref,
            f"cache::{metrics.get('cache_entry_id')}" if metrics.get("cache_entry_id") else "",
            f"runtime-scorecard::{metrics.get('runtime_scorecard_id')}" if metrics.get("runtime_scorecard_id") else "",
            *artifact_refs.values(),
        ]
        evidence_refs = [str(ref) for ref in evidence_refs if str(ref or "")]
        replay_payload = {
            "run_id": shadow_run_id,
            "candidate_ref": gate_id,
            "baseline_ref": "release-wrapper-runtime-shadow-baseline",
            "metrics": {
                "regression_count": 0.0,
                "artifact_set_complete": 1.0 if artifact_set_complete else 0.0,
                "finding_count": float(len(findings)),
            },
            "trace_refs": [trace_ref],
            "evaluator_refs": [gate_id, "ao::EvalsAO"],
            "evidence_refs": evidence_refs,
            "operator_approved": False,
            "lifecycle_ref": "release-wrapper-runtime-shadow-only",
            "lifecycle_status": "shadow_only_runtime_evidence",
            "growth_engine_gate": {"allowed": True, "blockers": []},
            "artifact_trust_promotion": {"promotion_allowed": True, "promotion_blockers": []},
            "metadata": {
                "source": "release-wrapper-runtime-evals-ao-artifact-gate",
                "evals_ao_artifact_gate_ref": gate_id,
                "evals_ao_artifact_gate_refs": [gate_id],
                "gate_id": gate_id,
                "trace_ref": trace_ref,
                "session_ref_digest": interaction.get("session_ref_digest"),
                "promotion_use_requires_operator_approval": True,
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            },
        }
        try:
            suite = self.eval_registry.register(
                {
                    "suite_id": suite_id,
                    "suite_type": "runtime",
                    "target_surfaces": ["release-wrapper-runtime", "runtime-decision-ledger", "EvalsAO"],
                    "benchmark_refs": list(artifact_refs.values()),
                    "held_out": True,
                    "external_or_tool_verifier": True,
                    "metrics": {
                        "regression_count": 0.0,
                        "artifact_set_complete": 1.0 if artifact_set_complete else 0.0,
                        "finding_count": float(len(findings)),
                    },
                    "promotion_target": "none",
                    "evidence_refs": evidence_refs,
                    "rollback_plan": "release-wrapper-runtime-shadow-only-no-production-mutation",
                    "monitoring_plan": "release-wrapper-runtime-evals-ao-artifact-drift-monitoring",
                    "metadata": {
                        "source": "release-wrapper-runtime-evals-ao-artifact-gate",
                        "gate_id": gate_id,
                        "trace_ref": trace_ref,
                        "session_ref_digest": interaction.get("session_ref_digest"),
                        "replay_template": {
                            "method": "POST",
                            "endpoint": f"/ops/brain/eval-suites/{suite_id}/run-shadow",
                            "payload": replay_payload,
                            "ready_for_operator_approval": False,
                            "operator_approval_boundary": "shadow eval replay becomes promotion evidence only after admin approval",
                        },
                        "raw_content_included": False,
                        "active_production_mutation_allowed": False,
                    },
                }
            )
            shadow_run = (
                self.eval_registry.run_shadow(
                    suite_id,
                    replay_payload,
                )
                if hasattr(self.eval_registry, "run_shadow")
                else {}
            )
        except Exception as exc:
            return {
                "surface_id": "eval-registry-runtime-evals-ao-link",
                "status": "blocked",
                "suite_id": suite_id,
                "shadow_run_id": shadow_run_id,
                "blocker": f"eval_registry_link_failed::{type(exc).__name__}",
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        return {
            "surface_id": "eval-registry-runtime-evals-ao-link",
            "status": "registered",
            "suite_id": suite_id,
            "suite_status": suite.get("status"),
            "suite_promotion_gate": suite.get("promotion_gate"),
            "suite_artifact_path_digest": (
                f"sha256:{_privacy_digest(str(suite.get('artifact_path')))}" if suite.get("artifact_path") else None
            ),
            "shadow_run_id": shadow_run_id,
            "shadow_run_status": shadow_run.get("status") if isinstance(shadow_run, dict) else "not-run",
            "shadow_run_promotion_allowed": (
                shadow_run.get("promotion_allowed") is True if isinstance(shadow_run, dict) else False
            ),
            "shadow_run_artifact_path_digest": (
                f"sha256:{_privacy_digest(str(shadow_run.get('artifact_path')))}"
                if isinstance(shadow_run, dict) and shadow_run.get("artifact_path")
                else None
            ),
            "promotion_use_requires_operator_approval": True,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }

    def _record_federated_import_evals_ao_artifact_gate(self, *, record: dict[str, Any]) -> dict[str, Any]:
        import_id = str(record.get("import_id") or "federated-import")
        safe_import = _safe_ref(import_id)
        gate_id = f"evals-ao-artifact::release-wrapper-federated-import::{safe_import}"
        trace_ref = f"federated-packet-import::{import_id}"
        relative_root = Path("evals") / "ao" / "release-wrapper-federated-import" / safe_import
        destination = self.artifacts_dir / relative_root
        created_at = utcnow().isoformat()
        artifact_refs = {
            "decision": (relative_root / "decision.json").as_posix(),
            "metrics": (relative_root / "metrics.json").as_posix(),
            "report": (relative_root / "report.md").as_posix(),
            "scenarios": (relative_root / "scenarios.jsonl").as_posix(),
        }
        artifact_path_digests = {
            name: f"sha256:{_privacy_digest(str(self.artifacts_dir / relative_path))}"
            for name, relative_path in artifact_refs.items()
        }
        findings: list[str] = []
        if record.get("security_envelope_verified") is not True:
            findings.append("federated_import_evals_ao_requires_verified_security_envelope")
        if record.get("assimilation_shadow_captured") is not True:
            findings.append("federated_import_evals_ao_requires_assimilation_shadow_capture")
        if record.get("global_growth_shadow_captured") is not True:
            findings.append("federated_import_evals_ao_requires_global_growth_shadow_capture")
        if record.get("raw_content_included") is not False or record.get("contains_personal_data") is not False:
            findings.append("federated_import_evals_ao_requires_sanitized_packet_boundary")
        metrics = {
            "surface_id": "external-evals-ao-artifact-gate",
            "authority": "NexusBrain",
            "ao": "EvalsAO",
            "gate_id": gate_id,
            "created_at": created_at,
            "trace_ref": trace_ref,
            "import_id": import_id,
            "source_packet_ref": record.get("source_packet_ref"),
            "session_ref_digest": record.get("session_ref_digest"),
            "peer_node_ref_digest": record.get("peer_node_ref_digest"),
            "security_envelope_verified": record.get("security_envelope_verified") is True,
            "assimilation_shadow_captured": record.get("assimilation_shadow_captured") is True,
            "global_growth_shadow_captured": record.get("global_growth_shadow_captured") is True,
            "quality": _float_metric(record.get("quality")),
            "finding_count": len(findings),
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }
        promotion_allowed = not findings
        decision = {
            "surface_id": "external-evals-ao-artifact-gate",
            "authority": "NexusBrain",
            "ao": "EvalsAO",
            "gate_id": gate_id,
            "created_at": created_at,
            "decision": "passed-shadow" if promotion_allowed else "blocked",
            "promotion_allowed": promotion_allowed,
            "findings": findings,
            "trace_ref": trace_ref,
            "import_id": import_id,
            "source_packet_ref": record.get("source_packet_ref"),
            "artifact_refs": artifact_refs,
            "artifact_path_digests": artifact_path_digests,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "promotion_boundary": "federated-import-evals-ao-artifact-gate-is-shadow-only-and-does-not-mutate-production",
        }
        scenario = {
            "scenario_id": f"release-wrapper-federated-import::{safe_import}",
            "surface_id": "external-evals-ao-artifact-scenario",
            "trace_ref": trace_ref,
            "import_id": import_id,
            "source_packet_ref": record.get("source_packet_ref"),
            "source_model_ref": str(record.get("source_model") or "federated-peer"),
            "selected_expert": record.get("expert_node"),
            "quarantine_state": record.get("quarantine_state"),
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }
        report = "\n".join(
            [
                f"# Federated Import EvalsAO Artifact Gate {gate_id}",
                "",
                f"- Decision: {decision['decision']}",
                f"- Import: {import_id}",
                f"- Source packet: {record.get('source_packet_ref') or 'missing'}",
                f"- Findings: {len(findings)}",
                "",
                "This artifact set is generated from sanitized federated import refs only.",
                "It remains shadow-only and does not grant active production mutation.",
            ]
        )
        try:
            destination.mkdir(parents=True, exist_ok=True)
            (destination / "metrics.json").write_text(json.dumps(metrics, indent=2, sort_keys=True), encoding="utf-8")
            (destination / "decision.json").write_text(json.dumps(decision, indent=2, sort_keys=True), encoding="utf-8")
            (destination / "report.md").write_text(report, encoding="utf-8")
            (destination / "scenarios.jsonl").write_text(json.dumps(scenario, sort_keys=True) + "\n", encoding="utf-8")
        except OSError as exc:
            return {
                "surface_id": "external-evals-ao-artifact-gate",
                "authority": "NexusBrain",
                "ao": "EvalsAO",
                "gate_id": gate_id,
                "status": "blocked",
                "promotion_allowed": False,
                "artifact_set_complete": False,
                "artifact_refs": {},
                "artifact_path_digests": {},
                "findings": [*findings, f"federated_import_evals_ao_artifact_write_failed::{type(exc).__name__}"],
                "raw_content_included": False,
                "active_production_mutation_allowed": False,
            }
        artifact_set_complete = all((self.artifacts_dir / relative_path).is_file() for relative_path in artifact_refs.values())
        eval_registry_ref = self._register_federated_import_evals_ao_artifact_gate(
            gate_id=gate_id,
            import_id=import_id,
            trace_ref=trace_ref,
            artifact_refs=artifact_refs,
            artifact_set_complete=artifact_set_complete,
            metrics=metrics,
            findings=findings,
            record=record,
        )
        return {
            "surface_id": "external-evals-ao-artifact-gate",
            "authority": "NexusBrain",
            "ao": "EvalsAO",
            "gate_id": gate_id,
            "status": "passed-shadow" if promotion_allowed and artifact_set_complete else "blocked",
            "promotion_allowed": promotion_allowed and artifact_set_complete,
            "artifact_set_complete": artifact_set_complete,
            "artifact_refs": artifact_refs,
            "artifact_path_digests": artifact_path_digests,
            "decision_ref": artifact_refs["decision"],
            "metrics_ref": artifact_refs["metrics"],
            "report_ref": artifact_refs["report"],
            "scenarios_ref": artifact_refs["scenarios"],
            "eval_registry_ref": eval_registry_ref,
            "findings": findings,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "sanitized-federated-import-eval-artifact-refs-and-digests-only-no-raw-prompts-outputs",
            "mutation_boundary": "shadow-evals-ao-gate-only-no-active-production-mutation",
        }

