    def _runtime_scorecard_for_id(self, scorecard_id: str) -> dict[str, Any]:
        if not scorecard_id or not hasattr(self.runtime_workload_scorecards, "summary"):
            return {}
        try:
            summary = self.runtime_workload_scorecards.summary(limit=50)
        except Exception:  # pragma: no cover - defensive status boundary
            return {}
        scorecards = summary.get("scorecards") if isinstance(summary.get("scorecards"), list) else []
        for scorecard in scorecards:
            if isinstance(scorecard, dict) and scorecard.get("scorecard_id") == scorecard_id:
                return scorecard
        latest = summary.get("latest_scorecard") if isinstance(summary.get("latest_scorecard"), dict) else {}
        return latest if latest.get("scorecard_id") == scorecard_id else {}

    def _runtime_decision_quantization_state(
        self,
        *,
        request: Any,
        result: Any,
        interaction: dict[str, Any],
        cache_entry: dict[str, Any],
        scorecard: dict[str, Any],
        trace_id: str,
    ) -> dict[str, Any]:
        scorecard_gate = {
            "promotion_allowed": scorecard.get("promotion_allowed"),
            "status": scorecard.get("status"),
            "promotion_blockers": scorecard.get("promotion_blockers") or [],
            "source": "runtime-workload-scorecard",
        }
        if self.quantization_catalog is not None and hasattr(self.quantization_catalog, "recommend"):
            try:
                recommendation = self.quantization_catalog.recommend(
                    {
                        "request_id": f"quantization::release-wrapper::{_safe_ref(trace_id)}",
                        "model_id": str(
                            getattr(result, "model_id", None)
                            or getattr(result, "selected_teacher_id", None)
                            or interaction.get("source_model")
                            or "wrapped-model"
                        ),
                        "runtime_targets": [str(getattr(result, "runtime_name", None) or "release-wrapper-runtime")],
                        "hardware_snapshot": scorecard.get("hardware") if isinstance(scorecard.get("hardware"), dict) else {},
                        "objective": "balanced_quality_latency",
                        "context_tokens": _safe_count(
                            (cache_entry.get("context_economics") or {}).get("effective_context_tokens")
                        )
                        or _estimated_request_tokens(request),
                        "upstream_runtime_scorecard_gate": scorecard_gate,
                        "metadata": {
                            "source": "release-wrapper-runtime",
                            "trace_ref": f"trace::{_safe_ref(trace_id)}",
                            "cache_ledger_entry_id": cache_entry.get("entry_id"),
                            "raw_content_included": False,
                            "active_production_mutation_allowed": False,
                        },
                    }
                )
                return _compact_runtime_quantization_state(recommendation)
            except Exception as exc:  # pragma: no cover - defensive degraded runtime boundary
                return {
                    "surface_id": "quantization-catalog",
                    "status": "blocked",
                    "promotion_allowed": False,
                    "promotion_blockers": ["quantization_catalog_recommendation_failed"],
                    "failure_digest": f"sha256:{_privacy_digest(str(exc))}",
                    "upstream_runtime_scorecard_gate": scorecard_gate,
                    "raw_content_included": False,
                    "active_production_mutation_allowed": False,
                }
        return {
            "surface_id": "quantization-catalog",
            "status": "not-configured-shadow",
            "promotion_allowed": True,
            "promotion_blockers": [],
            "upstream_runtime_scorecard_gate": scorecard_gate,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        }

    def _record_provider_ao_execution(
        self,
        *,
        session_id: str,
        provider_id: str,
        model_id: str,
        messages: list[dict[str, Any]],
        result: Any,
        wrapper_mode: str,
    ) -> dict[str, Any] | None:
        if self.ao_registry is None or not hasattr(self.ao_registry, "select_request"):
            return None
        if not hasattr(self.ao_registry, "record_execution"):
            return None
        operator_request = OperatorRequest(
            session_id=session_id,
            messages=[
                Message(role=str(message.get("role") or "user"), content=str(message.get("content") or ""))
                for message in messages
                if isinstance(message, dict)
            ],
            model_hint=model_id or provider_id,
            use_retrieval=False,
            metadata={
                "wrapper_mode": wrapper_mode,
                "provider_id": provider_id,
                "provider_model_id": model_id,
                "openai_compatible_surface": True,
            },
            trace_id=str(getattr(result, "trace_id", None) or ""),
        )
        plan = self.ao_registry.select_request(
            operator_request,
            expert=str(getattr(result, "selected_expert", None) or "conversationalist"),
            wrapper_mode=wrapper_mode,
        )
        result.canonical_ao_coverage = self._record_canonical_wrapper_ao_coverage(
            session_id=session_id,
            trace_id=str(getattr(result, "trace_id", None) or operator_request.trace_id),
            selected_expert=str(getattr(result, "selected_expert", None) or ""),
            selected_teacher_id=None,
            wrapper_mode=wrapper_mode,
        )
        return self.ao_registry.record_execution(
            session_id=session_id,
            trace_id=str(getattr(result, "trace_id", None) or operator_request.trace_id),
            plan=plan,
            selected_expert=str(getattr(result, "selected_expert", None) or ""),
            selected_teacher_id=None,
            wrapper_mode=wrapper_mode,
        )

    def _record_canonical_wrapper_ao_coverage(
        self,
        *,
        session_id: str,
        trace_id: str,
        selected_expert: str | None,
        selected_teacher_id: str | None,
        wrapper_mode: str,
    ) -> dict[str, Any]:
        session_ref_digest = _privacy_digest(session_id)
        created_at = utcnow().isoformat()
        receipts: list[dict[str, Any]] = []
        missing_aos: list[str] = []
        registry = self.ao_registry
        if registry is None or not hasattr(registry, "record_execution") or not hasattr(registry, "get"):
            missing_aos = list(WRAPPER_CANONICAL_AOS)
        else:
            for ao_name in WRAPPER_CANONICAL_AOS:
                orchestrator = registry.get(ao_name)
                if orchestrator is None:
                    missing_aos.append(ao_name)
                    continue
                responsibilities = list(getattr(orchestrator, "responsibilities", []) or [])
                risk_tier = str(getattr(orchestrator, "risk_tier", "high") or "high")
                if risk_tier not in {"low", "medium", "high"}:
                    risk_tier = "high"
                plan = AOPlan(
                    ao_name=ao_name,
                    reason=(
                        f"{ao_name} coverage recorded for release wrapper model interaction "
                        "before readiness can claim canonical AO runtime coverage."
                    ),
                    risk_tier=risk_tier,
                    goals=[
                        "prove release wrapper product path is governed by canonical AOs",
                        "preserve sanitized trace-only AO evidence",
                        "avoid active production mutation during wrapper coverage",
                    ],
                    responsibilities=responsibilities
                    or [
                        "release wrapper canonical AO coverage",
                        "sanitized runtime evidence",
                        "readiness gate support",
                    ],
                )
                receipt = registry.record_execution(
                    session_id=session_id,
                    trace_id=(
                        f"canonical-wrapper-ao::{_safe_ref(trace_id)}::"
                        f"{_safe_ref(ao_name)}::{_privacy_digest(created_at)}"
                    ),
                    plan=plan,
                    selected_expert=selected_expert,
                    selected_teacher_id=selected_teacher_id,
                    wrapper_mode=f"canonical-ao-coverage::{wrapper_mode}",
                    session_ref_digest=session_ref_digest,
                )
                receipts.append(_compact_ao_execution_receipt(receipt))
        covered_aos = [str(receipt.get("ao_name") or "") for receipt in receipts if receipt.get("ao_name")]
        missing_aos = [ao_name for ao_name in WRAPPER_CANONICAL_AOS if ao_name not in covered_aos]
        return {
            "surface_id": "release-wrapper-canonical-ao-coverage",
            "status_label": "LOCKED CANON",
            "coverage_id": f"canonical-ao-coverage::{_safe_ref(trace_id)}::{_privacy_digest(created_at)}",
            "created_at": created_at,
            "session_ref_digest": session_ref_digest,
            "trace_ref": f"trace::{trace_id}",
            "required_aos": list(WRAPPER_CANONICAL_AOS),
            "covered_aos": covered_aos,
            "missing_aos": missing_aos,
            "passed": not missing_aos,
            "receipt_count": len(receipts),
            "receipt_refs": [str(receipt.get("execution_id") or "") for receipt in receipts if receipt.get("execution_id")],
            "receipts": receipts,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "runtime_boundary": "canonical-wrapper-aos-record-sanitized-trace-receipts-no-raw-prompts-or-session-ids",
        }

