    def _observe_project_heartbeat(
        self,
        project_heartbeat: dict[str, Any],
        *,
        session_ref_digest: str | None,
    ) -> tuple[dict[str, Any], dict[str, Any]]:
        records_before = self._project_heartbeats_for_session(session_ref_digest)
        heartbeat = json.loads(json.dumps(project_heartbeat, default=str))
        if session_ref_digest:
            heartbeat["session_ref_digest"] = session_ref_digest
        heartbeat_id = str(heartbeat.get("heartbeat_id") or "")
        native_replay_ref = str(heartbeat.get("native_replay_ref") or "").strip()
        native_replay_record_id = str(heartbeat.get("native_replay_record_id") or "").strip()
        if heartbeat_id:
            record = compact_project_heartbeat_history_record(
                heartbeat,
                observed_at=utcnow().isoformat(),
                artifact_ref=PROJECT_HEARTBEAT_HISTORY_REF,
            )
            if is_replayable_project_heartbeat_record(record) and not any(
                str(existing.get("record_id") or "") == str(record.get("record_id") or "")
                or str(existing.get("heartbeat_id") or "") == heartbeat_id
                for existing in self._project_heartbeats
            ):
                self._project_heartbeats.insert(0, record)
                self._project_heartbeats = self._project_heartbeats[:100]
                self._persist_project_heartbeat_record(record)
        records_after = self._project_heartbeats_for_session(session_ref_digest)
        replay_status = (
            "replayed"
            if records_before
            else ("recording-live" if records_after else "not-observed")
        )
        replay = project_heartbeat_replay_summary(
            records_after,
            session_ref_digest=session_ref_digest,
            status=replay_status,
            artifact_ref=PROJECT_HEARTBEAT_HISTORY_REF,
        )
        if heartbeat_id:
            heartbeat["wrapper_replay_ref"] = PROJECT_HEARTBEAT_HISTORY_REF
            heartbeat["wrapper_replay_record_id"] = replay.get("latest_record_id")
            heartbeat["replay_ref"] = native_replay_ref or PROJECT_HEARTBEAT_HISTORY_REF
            heartbeat["replay_record_id"] = native_replay_record_id or replay.get("latest_record_id")
            heartbeat["runtime_state"] = (
                "replayed-history"
                if records_before
                else heartbeat.get("runtime_state")
                or ("live-bound" if heartbeat.get("status") == "alive" else "degraded")
            )
        return heartbeat, replay

