    def _session_history_summary(
        self,
        *,
        session_ref_digest: str | None,
        interactions: list[dict[str, Any]],
    ) -> dict[str, Any]:
        latest = interactions[0] if interactions else None
        trace_ids = [
            str(interaction.get("trace_id") or "")
            for interaction in interactions[:12]
            if str(interaction.get("trace_id") or "")
        ]
        return {
            "surface_id": "release-wrapper-session-history",
            "status_label": "LOCKED CANON",
            "scope": "session" if session_ref_digest else "global",
            "session_ref_digest": session_ref_digest,
            "event_count": len(interactions),
            "global_event_count": len(self._interactions),
            "latest_trace_id": (latest or {}).get("trace_id"),
            "latest_knowledge_ref": (latest or {}).get("knowledge_ref"),
            "latest_federated_packet_id": (latest or {}).get("federated_packet_id"),
            "latest_production_spine_packet_signature": (latest or {}).get("production_spine_packet_signature"),
            "trace_ids": trace_ids,
            "raw_content_included": False,
            "privacy_boundary": "sanitized-session-digests-trace-refs-and-counts-only-no-raw-prompts-outputs-session-ids",
        }

    def _effective_context_cache_summary(self, *, session_ref_digest: str | None = None) -> dict[str, Any]:
        if self.cache_ledger is None:
            return {
                "surface_id": "effective-context-cache-ledger",
                "runtime_state": "not-configured",
                "entry_count": 0,
                "latest_entry": None,
                "runtime_truth_boundary": "advertised-context-is-not-effective-context-without-measurement",
            }
        summary = self.cache_ledger.summary(limit=50)
        if not session_ref_digest:
            return summary
        entries = [
            entry
            for entry in (summary.get("entries") if isinstance(summary.get("entries"), list) else [])
            if str(entry.get("owner_ref") or (entry.get("privacy") or {}).get("owner_ref") or "")
            == f"session::{session_ref_digest}"
        ]
        measured = [entry for entry in entries if entry.get("status") in {"measured", "warning"}]
        latest = entries[0] if entries else None
        return {
            **summary,
            "runtime_state": "live-bound" if latest else "not-configured",
            "entry_count": len(entries),
            "measured_count": len(measured),
            "warning_count": sum(1 for entry in entries if entry.get("status") == "warning"),
            "blocked_count": sum(1 for entry in entries if entry.get("status") == "blocked"),
            "latest_entry": latest,
            "entries": entries[:20],
            "session_ref_digest": session_ref_digest,
        }

    def _runtime_decision_ledger_summary(self, *, session_ref_digest: str | None = None) -> dict[str, Any]:
        if self.runtime_decision_ledger is None or not hasattr(self.runtime_decision_ledger, "summary"):
            return {
                "surface_id": "runtime-decision-ledger",
                "authority": "NexusBrain",
                "runtime_state": "not-configured",
                "decision_count": 0,
                "latest_decision": None,
                "decisions": [],
                "session_ref_digest": session_ref_digest,
                "privacy_boundary": "runtime-decision-ledger-unavailable",
            }
        summary = self.runtime_decision_ledger.summary(limit=50)
        records = summary.get("decisions") if isinstance(summary.get("decisions"), list) else []
        if session_ref_digest:
            records = [
                record
                for record in records
                if str((record.get("metadata") or {}).get("session_ref_digest") or "") == session_ref_digest
            ]
        compact_records = [
            compact
            for compact in (_compact_runtime_decision_record(record) for record in records)
            if compact is not None
        ]
        latest = compact_records[0] if compact_records else None
        return {
            "status_label": summary.get("status_label") or "LOCKED CANON",
            "surface_id": "runtime-decision-ledger",
            "authority": "NexusBrain",
            "runtime_state": (
                "degraded"
                if any(record.get("status") == "blocked" for record in compact_records)
                else ("live-bound" if compact_records else "static-canon")
            ),
            "decision_count": len(compact_records),
            "global_decision_count": int(summary.get("decision_count") or 0),
            "latest_decision": latest,
            "decisions": compact_records,
            "recent_decisions": compact_records,
            "session_ref_digest": session_ref_digest,
            "promotion_boundary": summary.get("promotion_boundary")
            or "runtime decisions remain shadow-only until route, cache, quantization, eval, and fallback evidence clear",
            "privacy_boundary": "sanitized-runtime-decision-ids-statuses-digests-and-references-only-no-raw-prompts-outputs-session-ids-or-local-paths",
        }

    def _ao_execution_receipts_summary(self, *, session_ref_digest: str | None = None) -> dict[str, Any]:
        boundary = "ao-execution-receipts-are-sanitized-trace-refs-no-raw-prompts-or-session-ids"
        if self.ao_registry is None or not hasattr(self.ao_registry, "snapshot"):
            return {
                "surface_id": "ao-execution-receipts",
                "execution_count": 0,
                "latest_execution": None,
                "execution_receipts": [],
                "replay": {"status": "not-configured", "receipt_count": 0},
                "runtime_boundary": boundary,
            }
        snapshot = self.ao_registry.snapshot()
        payload = snapshot.model_dump(mode="json") if hasattr(snapshot, "model_dump") else dict(snapshot)
        receipts = list(payload.get("execution_receipts") or [])
        if session_ref_digest:
            receipts = [
                receipt
                for receipt in receipts
                if str(receipt.get("session_ref_digest") or "") == session_ref_digest
            ]
        latest_execution = next(
            (
                receipt
                for receipt in receipts
                if not str(receipt.get("wrapper_mode") or "").startswith("canonical-ao-coverage::")
            ),
            receipts[0] if receipts else None,
        )
        return {
            "surface_id": "ao-execution-receipts",
            "execution_count": len(receipts) if session_ref_digest else int(payload.get("execution_count") or 0),
            "latest_execution": latest_execution,
            "execution_receipts": receipts,
            "replay": payload.get("replay") or {},
            "runtime_boundary": payload.get("runtime_boundary") or boundary,
            "session_ref_digest": session_ref_digest,
        }

    def _autonomous_update_proposal(self, update_id: str) -> dict[str, Any] | None:
        proposals = self.autonomous_updates.summary(limit=500).get("proposals") or []
        return next(
            (
                proposal
                for proposal in proposals
                if isinstance(proposal, dict) and str(proposal.get("update_id") or "") == update_id
            ),
            None,
        )

    def _self_repair_session_ref_digest(self, proposal: dict[str, Any] | None) -> str | None:
        metadata = proposal.get("metadata") if isinstance((proposal or {}).get("metadata"), dict) else {}
        session_ref_digest = str(metadata.get("session_ref_digest") or "")
        if session_ref_digest:
            return session_ref_digest
        queue_id = str(metadata.get("improvement_queue_id") or "")
        if not queue_id or self.improvement_queue is None:
            return None
        try:
            item = ImprovementQueue(self.improvement_queue.storage_path).get(queue_id)
        except KeyError:
            return None
        return str(item.event.session_id or "") or None

