    def _load_interaction_events(self) -> list[dict[str, Any]]:
        try:
            lines = self.event_log_path.read_text(encoding="utf-8").splitlines()
        except OSError:
            return []
        events: list[dict[str, Any]] = []
        for line in lines:
            if not line.strip():
                continue
            try:
                event = json.loads(line)
            except json.JSONDecodeError:
                continue
            if self._is_replayable_event(event):
                events.append(event)
        return events

    def _is_replayable_event(self, event: dict[str, Any]) -> bool:
        capture = event.get("capture") if isinstance(event.get("capture"), dict) else {}
        return (
            event.get("schema_version") == 1
            and event.get("raw_content_included") is False
            and bool(event.get("session_ref_digest"))
            and bool(capture.get("source_model"))
            and bool(capture.get("expert_node"))
            and bool(capture.get("knowledge_ref"))
        )

    def _replay_persisted_events(self) -> dict[str, Any]:
        events = self._load_interaction_events()
        if not events:
            return {
                "status": "no-persisted-events",
                "event_count": 0,
                "privacy_boundary": "digests-and-routing-metadata-only-no-raw-prompts-outputs-session-ids",
            }
        seen: set[str] = set()
        replayed = 0
        runtime_growth_receipts_restored = 0
        for event in events:
            event_id = str(event.get("event_id") or "")
            if event_id and event_id in seen:
                continue
            if event_id:
                seen.add(event_id)
            capture = event["capture"]
            source_model = str(capture["source_model"])
            expert_node = str(capture["expert_node"])
            quality = _float_metric(capture.get("quality"))
            knowledge_ref = str(capture["knowledge_ref"])
            metadata = capture.get("metadata") if isinstance(capture.get("metadata"), dict) else {}
            if not bool(metadata.get("skip_learning_replay")):
                self.continuous_assimilation.assimilate(
                    source_model=source_model,
                    expert_node=expert_node,
                    task=str(capture.get("task") or "chat"),
                    quality=quality,
                    knowledge_ref=knowledge_ref,
                    metadata=metadata,
                )
                runtime_growth_receipt = (
                    event.get("runtime_growth_receipt")
                    if isinstance(event.get("runtime_growth_receipt"), dict)
                    else {}
                )
                if runtime_growth_receipt:
                    rehydration = self.global_growth.restore_runtime_receipts([runtime_growth_receipt])
                    runtime_growth_receipts_restored += int(rehydration.get("restored_receipts") or 0)
                else:
                    self.global_growth.assimilate_for_user(
                        str(event["session_ref_digest"]),
                        source_model=source_model,
                        expert_node=expert_node,
                        quality=quality,
                        knowledge_ref=knowledge_ref,
                    )
            interaction = event.get("interaction") if isinstance(event.get("interaction"), dict) else {}
            if interaction:
                self._interactions.insert(0, interaction)
                self._interactions = self._interactions[:50]
            federated_packet = event.get("federated_packet") if isinstance(event.get("federated_packet"), dict) else {}
            if federated_packet:
                self._federated_packets.insert(0, federated_packet)
                self._federated_packets = self._federated_packets[:50]
            production_packet = (
                event.get("production_spine_packet")
                if isinstance(event.get("production_spine_packet"), dict)
                else {}
            )
            if production_packet:
                self._production_spine_packets.insert(0, production_packet)
                self._production_spine_packets = self._production_spine_packets[:50]
            replayed += 1
        return {
            "status": "replayed" if replayed else "no-replayable-events",
            "event_count": replayed,
            "runtime_growth_receipts_restored": runtime_growth_receipts_restored,
            "privacy_boundary": "digests-and-routing-metadata-only-no-raw-prompts-outputs-session-ids",
        }

    def _latest_first_run_readiness_run(self, *, session_ref_digest: str | None) -> dict[str, Any] | None:
        for run in reversed(self._first_run_readiness_runs):
            if not session_ref_digest or str(run.get("session_ref_digest") or "") == session_ref_digest:
                return run
        return None

    def _latest_production_spine_release_lifecycle_run(
        self,
        *,
        session_ref_digest: str | None,
    ) -> dict[str, Any] | None:
        for run in reversed(self._production_spine_release_lifecycle_runs):
            if not session_ref_digest or str(run.get("session_ref_digest") or "") == session_ref_digest:
                return run
        return None

    def _find_production_spine_release_lifecycle_run(self, run_id: str) -> dict[str, Any] | None:
        requested = str(run_id or "")
        for run in reversed(self._production_spine_release_lifecycle_runs):
            if str(run.get("run_id") or "") == requested:
                return run
        return None

    def _latest_production_spine_release_lifecycle_rollback(
        self,
        *,
        session_ref_digest: str | None,
        run_id: str | None = None,
    ) -> dict[str, Any] | None:
        for rollback in reversed(self._production_spine_release_lifecycle_rollbacks):
            if run_id and str(rollback.get("run_id") or "") != str(run_id):
                continue
            if session_ref_digest and str(rollback.get("session_ref_digest") or "") != session_ref_digest:
                continue
            return rollback
        return None

    def _replay_federated_packet_import_learning(self) -> dict[str, Any]:
        if not self._federated_packet_imports:
            return {
                "status": "no-persisted-imports",
                "import_count": 0,
                "privacy_boundary": "sanitized-peer-packet-digests-refs-and-status-only-no-raw-prompts-outputs-session-ids",
            }
        replayed = 0
        blocked_by_privacy_consent = 0
        for record in reversed(self._federated_packet_imports):
            if record.get("status") != "quarantined-shadow-accepted":
                continue
            if record.get("security_envelope_verified") is not True:
                continue
            consent_policy = (
                record.get("consent_policy")
                if isinstance(record.get("consent_policy"), dict)
                else _privacy_consent_policy_for_packet(None)
            )
            if self._privacy_consent_blocks_personal_data_policy(
                session_ref_digest=str(record.get("session_ref_digest") or ""),
                consent_policy=consent_policy,
            ):
                blocked_by_privacy_consent += 1
                continue
            try:
                self.continuous_assimilation.assimilate(
                    source_model=str(record["source_model"]),
                    expert_node=str(record["expert_node"]),
                    task="federated-import-shadow-replay",
                    quality=_float_metric(record.get("quality")),
                    knowledge_ref=str(record.get("packet_digest") or record.get("source_packet_ref") or ""),
                    metadata={
                        "federated_packet_import_replay": True,
                        "source_packet_ref": record.get("source_packet_ref"),
                        "peer_node_ref_digest": record.get("peer_node_ref_digest"),
                        "raw_content_included": False,
                        "active_production_mutation_allowed": False,
                    },
                )
                self.global_growth.assimilate_for_user(
                    str(record.get("session_ref_digest") or record.get("peer_node_ref_digest") or "federated-peer"),
                    source_model=str(record["source_model"]),
                    expert_node=str(record["expert_node"]),
                    quality=_float_metric(record.get("quality")),
                    knowledge_ref=str(record.get("packet_digest") or record.get("source_packet_ref") or ""),
                )
                replayed += 1
            except Exception:
                continue
        return {
            "status": "replayed" if replayed else "no-replayable-import-learning",
            "import_count": replayed,
            "blocked_by_privacy_consent_count": blocked_by_privacy_consent,
            "privacy_boundary": "sanitized-peer-packet-digests-refs-and-status-only-no-raw-prompts-outputs-session-ids",
        }


