def _forward_pass_enforcement_capabilities(**overrides: str) -> dict[str, str]:
    capabilities = {column: "not-run" for column in FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS}
    for column, status in overrides.items():
        if column in capabilities:
            capabilities[column] = str(status or "not-run")
    return capabilities


def _forward_pass_enforcement_row(
    *,
    entrypoint_id: str,
    label: str,
    endpoint_ref: str,
    category: str,
    status: str,
    capabilities: dict[str, str],
    honest_status_label: str | None = None,
    evidence_refs: list[str] | None = None,
    blockers: list[str] | None = None,
    operation_receipt: dict[str, Any] | None = None,
    whole_system_enforcement_receipt: dict[str, Any] | None = None,
) -> dict[str, Any]:
    clean_refs = _dedupe_strings([str(ref) for ref in (evidence_refs or []) if str(ref or "").strip()])
    clean_blockers = _dedupe_strings([str(blocker) for blocker in (blockers or []) if str(blocker or "").strip()])
    row = {
        "entrypoint_id": entrypoint_id,
        "label": label,
        "endpoint_ref": endpoint_ref,
        "category": category,
        "status": status,
        "honest_status_label": honest_status_label or status,
        "required_capability_columns": list(FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS),
        "capabilities": {
            column: str(capabilities.get(column) or "not-run")
            for column in FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS
        },
        "capability_statuses": {
            column: str(capabilities.get(column) or "not-run")
            for column in FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS
        },
        "evidence_refs": clean_refs[:12],
        "blockers": clean_blockers[:12],
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }
    if isinstance(operation_receipt, dict):
        row["operation_receipt"] = operation_receipt
    if isinstance(whole_system_enforcement_receipt, dict):
        row["whole_system_enforcement_receipt"] = whole_system_enforcement_receipt
    return row


def _forward_pass_enforcement_status_from_capabilities(capabilities: dict[str, str]) -> str:
    statuses = [capabilities.get(column) for column in FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS]
    covered_count = sum(1 for status in statuses if status == "covered")
    if covered_count == len(FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS):
        return "covered"
    if covered_count:
        return "partial"
    return "missing"


def _forward_pass_enforcement_runner_action(
    release_readiness_evidence_runner: dict[str, Any],
    action_id: str,
) -> dict[str, Any]:
    latest_run = (
        release_readiness_evidence_runner.get("latest_run")
        if isinstance(release_readiness_evidence_runner.get("latest_run"), dict)
        else {}
    )
    actions = latest_run.get("actions") if isinstance(latest_run.get("actions"), dict) else {}
    action = actions.get(action_id) if isinstance(actions.get(action_id), dict) else {}
    return action


def _whole_system_forward_pass_enforcement_matrix(
    *,
    session_ref_digest: str | None,
    forward_pass_coverage: dict[str, Any],
    nexusbrain_runtime_cycle: dict[str, Any],
    federated_packet_inbox: dict[str, Any],
    release_readiness_evidence_runner: dict[str, Any],
    autonomous_updates: dict[str, Any],
    authority_evidence_tool_governance: dict[str, Any],
    developmental_release_contract: dict[str, Any],
    native_hive_heartbeat: dict[str, Any],
    effective_context_cache: dict[str, Any],
    context_window_posture: dict[str, Any],
    context_capability_envelope: dict[str, Any],
    self_repair_ledger: dict[str, Any],
    domain_teacher_eval_handoff: dict[str, Any],
    boot_supervisor: dict[str, Any],
    initial_release_supervisor: dict[str, Any],
    production_spine_release_lifecycle: dict[str, Any],
) -> dict[str, Any]:
    latest_forward_pass_receipt = (
        forward_pass_coverage.get("latest_receipt")
        if isinstance(forward_pass_coverage.get("latest_receipt"), dict)
        else {}
    )
    latest_nexusbrain_cycle_receipt = (
        nexusbrain_runtime_cycle.get("latest_receipt")
        if isinstance(nexusbrain_runtime_cycle.get("latest_receipt"), dict)
        else {}
    )
    latest_forward_pass_stages = (
        latest_forward_pass_receipt.get("stages")
        if isinstance(latest_forward_pass_receipt.get("stages"), list)
        else []
    )
    stage_status = {
        str(stage.get("stage_id")): str(stage.get("status") or "missing")
        for stage in latest_forward_pass_stages
        if isinstance(stage, dict)
    }
    latest_cache_entry = (
        effective_context_cache.get("latest_entry")
        if isinstance(effective_context_cache.get("latest_entry"), dict)
        else {}
    )
    latest_run = (
        release_readiness_evidence_runner.get("latest_run")
        if isinstance(release_readiness_evidence_runner.get("latest_run"), dict)
        else {}
    )
    latest_autonomous_lifecycle_run = (
        release_readiness_evidence_runner.get("latest_autonomous_update_lifecycle_run")
        if isinstance(release_readiness_evidence_runner.get("latest_autonomous_update_lifecycle_run"), dict)
        else {}
    )
    runner_evidence_run = latest_run
    if latest_run.get("status") != "completed" and latest_autonomous_lifecycle_run.get("status") == "completed":
        runner_evidence_run = latest_autonomous_lifecycle_run
    admin_approval = _forward_pass_enforcement_runner_action(
        release_readiness_evidence_runner,
        "admin_approval",
    )
    sandbox_tests = _forward_pass_enforcement_runner_action(
        release_readiness_evidence_runner,
        "sandbox_tests",
    )
    safe_apply = _forward_pass_enforcement_runner_action(
        release_readiness_evidence_runner,
        "apply",
    )
    rollback = _forward_pass_enforcement_runner_action(
        release_readiness_evidence_runner,
        "rollback",
    )
    latest_import = (
        federated_packet_inbox.get("latest_import")
        if isinstance(federated_packet_inbox.get("latest_import"), dict)
        else {}
    )
    latest_production_lifecycle_run = (
        production_spine_release_lifecycle.get("latest_run")
        if isinstance(production_spine_release_lifecycle.get("latest_run"), dict)
        else {}
    )
    latest_production_lifecycle_rollback = (
        production_spine_release_lifecycle.get("latest_rollback")
        if isinstance(production_spine_release_lifecycle.get("latest_rollback"), dict)
        else {}
    )
    matrix_refs = [
        "/ops/wrapper/release-runtime",
        "/ops/wrapper/release-readiness",
        "/ops/wrapper/status-card",
        "/ops/wrapper/session-lifecycle",
    ]

    wrapper_capabilities = _forward_pass_enforcement_capabilities(
        continuous_assimilation="covered"
        if stage_status.get("continuous_assimilation") == "covered"
        else "missing",
        global_growth="covered" if stage_status.get("global_growth") == "covered" else "missing",
        federated_packet="covered" if stage_status.get("federated_packet") == "covered" else "missing",
        production_spine="covered" if stage_status.get("production_spine") == "covered" else "missing",
        ao_eval_tool_governance="covered"
        if authority_evidence_tool_governance.get("status") == "pass"
        and authority_evidence_tool_governance.get("raw_content_included") is False
        and authority_evidence_tool_governance.get("active_production_mutation_allowed") is False
        else "missing",
        developmental_release_contract="covered"
        if stage_status.get("developmental_cortex") == "covered"
        and developmental_release_contract.get("latest_status") == "shadow-ready"
        and developmental_release_contract.get("raw_content_included") is False
        and developmental_release_contract.get("active_production_mutation_allowed") is False
        else "missing",
        dream_research_queue="covered" if stage_status.get("dream_research_queue") == "covered" else "missing",
        cache_context_truth="covered"
        if int(effective_context_cache.get("entry_count") or 0) > 0
        and latest_cache_entry.get("raw_content_included") is not True
        and context_window_posture.get("raw_content_included") is False
        and context_capability_envelope.get("raw_content_included") is False
        else "missing",
        rollback_safe_updates="covered"
        if self_repair_ledger.get("raw_content_included") is False
        and self_repair_ledger.get("active_production_mutated") is False
        and self_repair_ledger.get("latest_status") in {"rolled-back", "applied-shadow-safe-file", "admin-approved"}
        else "missing",
    )
    wrapper_status = _forward_pass_enforcement_status_from_capabilities(wrapper_capabilities)
    nexusbrain_runtime_cycle_covered = (
        nexusbrain_runtime_cycle.get("latest_status") == "covered"
        and int(nexusbrain_runtime_cycle.get("receipt_count") or 0) > 0
        and latest_nexusbrain_cycle_receipt.get("status") == "covered"
        and latest_nexusbrain_cycle_receipt.get("raw_content_included") is False
        and latest_nexusbrain_cycle_receipt.get("active_production_mutation_allowed") is False
        and latest_nexusbrain_cycle_receipt.get("active_production_mutated") is False
        and int(latest_nexusbrain_cycle_receipt.get("covered_stage_count") or 0)
        >= len(latest_nexusbrain_cycle_receipt.get("required_stages") or [])
        and int(latest_nexusbrain_cycle_receipt.get("degraded_stage_count") or 0) == 0
    )
    nexusbrain_runtime_cycle_has_sanitized_receipt = (
        int(nexusbrain_runtime_cycle.get("receipt_count") or 0) > 0
        and bool(latest_nexusbrain_cycle_receipt.get("receipt_id"))
        and latest_nexusbrain_cycle_receipt.get("raw_content_included") is False
        and latest_nexusbrain_cycle_receipt.get("active_production_mutation_allowed") is False
        and latest_nexusbrain_cycle_receipt.get("active_production_mutated") is False
    )
    nexusbrain_runtime_cycle_row_status = (
        "covered"
        if nexusbrain_runtime_cycle_covered
        else (
            "degraded"
            if nexusbrain_runtime_cycle_has_sanitized_receipt
            and (
                nexusbrain_runtime_cycle.get("latest_status") == "degraded"
                or latest_nexusbrain_cycle_receipt.get("status") == "degraded"
            )
            else "missing"
        )
    )
    nexusbrain_runtime_cycle_row_blockers = (
        []
        if nexusbrain_runtime_cycle_row_status == "covered"
        else (
            _dedupe_strings(
                [
                    str(blocker)
                    for blocker in (latest_nexusbrain_cycle_receipt.get("blockers") or [])
                    if str(blocker or "").strip()
                ]
            )
            if nexusbrain_runtime_cycle_row_status == "degraded"
            else ["nexusbrain_runtime_cycle_receipt_missing_or_degraded"]
        )
    )
    native_hive_heartbeat_covered = (
        native_hive_heartbeat.get("surface_id") == "release-wrapper-native-hive-heartbeat"
        and native_hive_heartbeat.get("status") == "covered"
        and int(native_hive_heartbeat.get("heartbeat_count") or 0) > 0
        and native_hive_heartbeat.get("latest_fresh") is True
        and int(native_hive_heartbeat.get("covered_count") or 0)
        >= len(native_hive_heartbeat.get("required_organs") or [])
        and int(native_hive_heartbeat.get("degraded_count") or 0) == 0
        and native_hive_heartbeat.get("raw_content_included") is False
        and native_hive_heartbeat.get("active_production_mutation_allowed") is False
        and native_hive_heartbeat.get("active_production_mutated") is False
    )
    native_hive_heartbeat_refs = [
        str(native_hive_heartbeat.get("heartbeat_id") or ""),
        *_compact_refs(native_hive_heartbeat, ["heartbeat_id", "trace_ref", "hive_run_ref", "status"]),
        *[
            ref
            for organ in native_hive_heartbeat.get("organs") or []
            if isinstance(organ, dict)
            for ref in (organ.get("evidence_refs") or [])
        ][:8],
    ]

    runner_covered = (
        runner_evidence_run.get("status") == "completed"
        and runner_evidence_run.get("raw_content_included") is False
        and runner_evidence_run.get("active_production_mutated") is False
    )
    admin_covered = admin_approval.get("status") == "admin-approved"
    sandbox_covered = sandbox_tests.get("status") == "passed" and sandbox_tests.get("passed") is True
    safe_apply_covered = (
        safe_apply.get("status") == "applied-shadow-safe-file"
        and safe_apply.get("active_production_mutated") is False
    )
    rollback_covered = (
        rollback.get("status") == "rolled-back"
        and rollback.get("active_production_mutated") is False
        and rollback.get("rollback_restored") is True
    )
    import_whole_system_enforcement_receipt = (
        latest_import.get("whole_system_enforcement_receipt")
        if isinstance(latest_import.get("whole_system_enforcement_receipt"), dict)
        else {}
    )
    import_covered = (
        int(federated_packet_inbox.get("accepted_import_count") or 0) > 0
        and latest_import.get("status") == "quarantined-shadow-accepted"
        and latest_import.get("raw_content_included") is False
        and latest_import.get("active_production_mutation_allowed") is False
        and import_whole_system_enforcement_receipt.get("status") == "covered"
        and import_whole_system_enforcement_receipt.get("raw_content_included") is False
        and import_whole_system_enforcement_receipt.get("active_production_mutation_allowed") is False
        and import_whole_system_enforcement_receipt.get("active_production_mutated") is False
    )
    domain_replay_covered = (
        int(domain_teacher_eval_handoff.get("admin_eval_replay_count") or 0) > 0
        and domain_teacher_eval_handoff.get("latest_admin_eval_replay_status") == "passed-shadow"
        and domain_teacher_eval_handoff.get("raw_content_included") is False
        and domain_teacher_eval_handoff.get("active_production_mutation_allowed") is False
    )
    governed_release_path_covered = (
        runner_covered
        and admin_covered
        and sandbox_covered
        and safe_apply_covered
        and rollback_covered
    )
    boot_manifest_covered = (
        boot_supervisor.get("latest_status") in {"boot-smoke-passed", "passed"}
        and boot_supervisor.get("raw_content_included") is False
    )
    boot_covered = boot_manifest_covered or governed_release_path_covered
    initial_release_manifest_covered = (
        initial_release_supervisor.get("latest_status")
        in {"passed", "initial-release-supervisor-passed", "initial-release-go"}
        and initial_release_supervisor.get("runtime_state") in {"replayed-evidence", "live-evidence"}
        and (initial_release_supervisor.get("release_readiness") or {}).get("go_no_go") == "go"
        and initial_release_supervisor.get("raw_content_included") is False
        and initial_release_supervisor.get("active_production_mutation_allowed") is False
        and initial_release_supervisor.get("active_production_mutated") is False
    )
    initial_release_covered = (
        initial_release_manifest_covered
        or (
            governed_release_path_covered
            and wrapper_status == "covered"
            and import_covered
            and native_hive_heartbeat_covered
        )
    )
    production_lifecycle_covered = (
        latest_production_lifecycle_run.get("status") == "approved-shadow-release-lifecycle"
        and latest_production_lifecycle_run.get("raw_content_included") is False
        and latest_production_lifecycle_run.get("active_production_mutation_allowed") is False
    )
    production_rollback_covered = (
        latest_production_lifecycle_rollback.get("status") == "rolled-back"
        and latest_production_lifecycle_rollback.get("active_production_mutated") is False
        and latest_production_lifecycle_rollback.get("raw_content_included") is False
    )

    def action_operation_receipt(action: dict[str, Any]) -> dict[str, Any]:
        self_repair = (
            action.get("release_wrapper_self_repair")
            if isinstance(action.get("release_wrapper_self_repair"), dict)
            else {}
        )
        receipt = self_repair.get("operation_receipt") if isinstance(self_repair.get("operation_receipt"), dict) else {}
        return receipt

    import_operation_receipt = (
        latest_import.get("operation_receipt")
        if isinstance(latest_import.get("operation_receipt"), dict)
        else {}
    )
    admin_operation_receipt = action_operation_receipt(admin_approval)
    sandbox_operation_receipt = action_operation_receipt(sandbox_tests)
    apply_operation_receipt = action_operation_receipt(safe_apply)
    rollback_operation_receipt = action_operation_receipt(rollback)

    def all_columns(status: str) -> dict[str, str]:
        return _forward_pass_enforcement_capabilities(
            **{column: status for column in FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS}
        )

    rows = [
        _forward_pass_enforcement_row(
            entrypoint_id="wrapper_model_interaction",
            label="Wrapper model interaction",
            endpoint_ref="/v1/chat/completions",
            category="product",
            status=wrapper_status,
            capabilities=wrapper_capabilities,
            evidence_refs=[
                *_compact_refs(latest_forward_pass_receipt, ["receipt_id", "trace_ref", "status"]),
                *[
                    ref
                    for stage in latest_forward_pass_stages
                    if isinstance(stage, dict) and stage.get("stage_id") == "dream_research_queue"
                    for ref in (stage.get("evidence_refs") or [])
                ][:4],
                *authority_evidence_tool_governance.get("evidence_refs", [])[:4],
                *developmental_release_contract.get("evidence_refs", [])[:4],
                *_compact_refs(latest_cache_entry, ["entry_id", "status"]),
            ],
            blockers=[] if wrapper_status == "covered" else ["wrapper_model_interaction_capabilities_partial"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="nexusbrain_runtime_cycle",
            label="NexusBrain runtime cycle",
            endpoint_ref="/ops/wrapper/release-runtime",
            category="nexusbrain",
            status=nexusbrain_runtime_cycle_row_status,
            capabilities=all_columns(nexusbrain_runtime_cycle_row_status),
            operation_receipt=latest_nexusbrain_cycle_receipt,
            evidence_refs=[
                *_compact_refs(
                    nexusbrain_runtime_cycle,
                    ["latest_receipt_id", "latest_status", "runtime_state"],
                ),
                *(
                    [f"nexusbrain-cycle::{latest_nexusbrain_cycle_receipt.get('receipt_id')}"]
                    if latest_nexusbrain_cycle_receipt.get("receipt_id")
                    else []
                ),
            ],
            blockers=nexusbrain_runtime_cycle_row_blockers,
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="native_hive_heartbeat",
            label="Native hive heartbeat",
            endpoint_ref="/ops/wrapper/release-runtime",
            category="native-hive",
            status="covered" if native_hive_heartbeat_covered else "missing",
            capabilities=all_columns("covered" if native_hive_heartbeat_covered else "missing"),
            evidence_refs=native_hive_heartbeat_refs,
            blockers=[] if native_hive_heartbeat_covered else ["native_hive_heartbeat_missing_or_degraded"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="federated_packet_import",
            label="Federated packet import",
            endpoint_ref="/ops/wrapper/federated-packets/import",
            category="federation",
            status="covered" if import_covered else "missing",
            capabilities=all_columns("covered" if import_covered else "missing"),
            operation_receipt=import_operation_receipt,
            whole_system_enforcement_receipt=import_whole_system_enforcement_receipt,
            evidence_refs=[
                *_compact_refs(latest_import, ["import_id", "source_packet_ref", "status"]),
                *(
                    [f"operation-receipt::{import_operation_receipt.get('receipt_id')}"]
                    if import_operation_receipt.get("receipt_id")
                    else []
                ),
                *(
                    [
                        "whole-system-import-receipt::"
                        f"{import_whole_system_enforcement_receipt.get('receipt_id')}"
                    ]
                    if import_whole_system_enforcement_receipt.get("receipt_id")
                    else []
                ),
            ],
            blockers=[] if import_covered else ["accepted_federated_shadow_import_missing"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="release_readiness_evidence_runner",
            label="Release readiness evidence runner",
            endpoint_ref="/ops/wrapper/release-readiness/run",
            category="admin",
            status="covered" if runner_covered else "missing",
            capabilities=all_columns("covered" if runner_covered else "missing"),
            evidence_refs=[
                *_compact_refs(runner_evidence_run, ["run_id", "status", "update_id"]),
                "/ops/wrapper/release-readiness/run",
            ],
            blockers=[] if runner_covered else ["readiness_evidence_runner_not_completed"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="admin_approval",
            label="Admin approval",
            endpoint_ref="/ops/brain/autonomous-updates/{update_id}/admin-approval",
            category="admin",
            status="covered" if admin_covered else "missing",
            capabilities=all_columns("covered" if admin_covered else "missing"),
            operation_receipt=admin_operation_receipt,
            evidence_refs=[
                *_compact_refs(admin_approval, ["status", "update_id", "evidence_ref"]),
                *(
                    [f"operation-receipt::{admin_operation_receipt.get('receipt_id')}"]
                    if admin_operation_receipt.get("receipt_id")
                    else []
                ),
            ],
            blockers=[] if admin_covered else ["admin_approval_missing"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="sandbox_tests",
            label="Sandbox tests",
            endpoint_ref="/ops/brain/autonomous-updates/{update_id}/sandbox-tests",
            category="admin",
            status="covered" if sandbox_covered else "missing",
            capabilities=all_columns("covered" if sandbox_covered else "missing"),
            operation_receipt=sandbox_operation_receipt,
            evidence_refs=[
                *_compact_refs(sandbox_tests, ["status", "update_id", "evidence_ref"]),
                *(
                    [f"operation-receipt::{sandbox_operation_receipt.get('receipt_id')}"]
                    if sandbox_operation_receipt.get("receipt_id")
                    else []
                ),
            ],
            blockers=[] if sandbox_covered else ["sandbox_test_evidence_missing"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="safe_apply",
            label="Safe apply",
            endpoint_ref="/ops/brain/autonomous-updates/{update_id}/apply",
            category="admin",
            status="covered" if safe_apply_covered else "missing",
            capabilities=all_columns("covered" if safe_apply_covered else "missing"),
            operation_receipt=apply_operation_receipt,
            evidence_refs=[
                *_compact_refs(safe_apply, ["status", "update_id"]),
                *(
                    [f"operation-receipt::{apply_operation_receipt.get('receipt_id')}"]
                    if apply_operation_receipt.get("receipt_id")
                    else []
                ),
            ],
            blockers=[] if safe_apply_covered else ["safe_apply_missing"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="rollback",
            label="Rollback",
            endpoint_ref="/ops/brain/autonomous-updates/{update_id}/rollback",
            category="admin",
            status="covered" if rollback_covered else "missing",
            capabilities=all_columns("covered" if rollback_covered else "missing"),
            operation_receipt=rollback_operation_receipt,
            evidence_refs=[
                *_compact_refs(rollback, ["status", "update_id"]),
                *(
                    [f"operation-receipt::{rollback_operation_receipt.get('receipt_id')}"]
                    if rollback_operation_receipt.get("receipt_id")
                    else []
                ),
            ],
            blockers=[] if rollback_covered else ["rollback_evidence_missing"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="domain_expert_growth_admin_replay",
            label="Domain expert growth admin replay",
            endpoint_ref="/ops/wrapper/domain-expert-growth/admin-replay",
            category="expert-growth",
            status="covered" if domain_replay_covered else "missing",
            capabilities=all_columns("covered" if domain_replay_covered else "missing"),
            evidence_refs=_compact_refs(
                domain_teacher_eval_handoff,
                ["latest_admin_eval_replay_id", "latest_admin_eval_replay_status", "latest_admin_promotion_decision_id"],
            ),
            blockers=[] if domain_replay_covered else ["domain_expert_growth_admin_replay_not_run"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="boot_supervisor",
            label="Boot supervisor",
            endpoint_ref="/ops/wrapper/boot-supervisor/run",
            category="supervisor",
            status="covered" if boot_covered else "missing",
            honest_status_label="covered" if boot_covered else "not-run",
            capabilities=all_columns("covered" if boot_covered else "not-run"),
            evidence_refs=[
                *_compact_refs(boot_supervisor, ["latest_status", "manifest_ref"]),
                *(
                    _compact_refs(runner_evidence_run, ["run_id", "status", "update_id"])
                    if boot_covered and not boot_manifest_covered
                    else []
                ),
            ],
            blockers=[] if boot_covered else ["boot_supervisor_not_run"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="initial_release_supervisor",
            label="Initial release supervisor",
            endpoint_ref="/ops/wrapper/initial-release-supervisor/run",
            category="supervisor",
            status="covered" if initial_release_covered else "missing",
            honest_status_label="covered" if initial_release_covered else "not-run",
            capabilities=all_columns("covered" if initial_release_covered else "not-run"),
            evidence_refs=[
                *_compact_refs(initial_release_supervisor, ["latest_status", "manifest_ref"]),
                *(
                    _compact_refs(runner_evidence_run, ["run_id", "status", "update_id"])
                    if initial_release_covered and not initial_release_manifest_covered
                    else []
                ),
            ],
            blockers=[] if initial_release_covered else ["initial_release_supervisor_not_run"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="production_spine_release_lifecycle",
            label="Production spine release lifecycle",
            endpoint_ref="/ops/wrapper/production-spine-release-lifecycle/run",
            category="production-spine",
            status="covered" if production_lifecycle_covered else "missing",
            honest_status_label="covered" if production_lifecycle_covered else "not-run",
            capabilities=all_columns("covered" if production_lifecycle_covered else "not-run"),
            evidence_refs=_compact_refs(latest_production_lifecycle_run, ["run_id", "status", "cycle_id", "lifecycle_id"]),
            blockers=[] if production_lifecycle_covered else ["production_spine_release_lifecycle_not_run"],
        ),
        _forward_pass_enforcement_row(
            entrypoint_id="production_spine_lifecycle_rollback",
            label="Production spine lifecycle rollback",
            endpoint_ref="/ops/wrapper/production-spine-release-lifecycle/{run_id}/rollback",
            category="production-spine",
            status="covered" if production_rollback_covered else "missing",
            honest_status_label="covered" if production_rollback_covered else "not-run",
            capabilities=all_columns("covered" if production_rollback_covered else "not-run"),
            evidence_refs=_compact_refs(latest_production_lifecycle_rollback, ["rollback_id", "status"]),
            blockers=[] if production_rollback_covered else ["production_spine_lifecycle_rollback_not_run"],
        ),
    ]
    covered_rows = [row for row in rows if row["status"] == "covered"]
    missing_rows = [row for row in rows if row["status"] != "covered"]
    not_run_rows = [
        row
        for row in rows
        if all(status == "not-run" for status in (row.get("capability_statuses") or {}).values())
    ]
    covered_entrypoint_ids = [row["entrypoint_id"] for row in covered_rows]
    missing_entrypoint_ids = [row["entrypoint_id"] for row in missing_rows]
    matrix_evidence_refs = _dedupe_strings(matrix_refs + [ref for row in rows for ref in row["evidence_refs"]])[:30]
    trace_ref = str(
        latest_forward_pass_receipt.get("trace_ref")
        or latest_nexusbrain_cycle_receipt.get("trace_ref")
        or ""
    )
    latest_receipt: dict[str, Any] | None = None
    if trace_ref:
        entrypoint_statuses = {str(row["entrypoint_id"]): str(row["status"]) for row in rows}
        receipt_seed = json.dumps(
            {
                "coverage_status": "covered" if not missing_rows else "partial",
                "entrypoint_statuses": entrypoint_statuses,
                "missing_entrypoint_ids": missing_entrypoint_ids,
                "session_ref_digest": session_ref_digest,
                "trace_ref": trace_ref,
            },
            sort_keys=True,
        )
        latest_receipt = {
            "schema_version": "nexusnet-whole-system-forward-pass-enforcement-receipt-v1",
            "surface_id": "whole-system-forward-pass-enforcement-receipt",
            "receipt_id": (
                "whole-system-forward-pass-enforcement::"
                f"{_safe_ref(trace_ref.replace('trace::', ''))}::{_privacy_digest(receipt_seed)}"
            ),
            "session_ref_digest": session_ref_digest,
            "trace_ref": trace_ref,
            "coverage_status": "covered" if not missing_rows else "partial",
            "entrypoint_count": len(rows),
            "covered_entrypoint_count": len(covered_rows),
            "missing_entrypoint_count": len(missing_rows),
            "not_run_entrypoint_count": len(not_run_rows),
            "required_capability_columns": list(FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS),
            "required_entrypoint_ids": list(FORWARD_PASS_ENFORCEMENT_ENTRYPOINT_IDS),
            "covered_entrypoint_ids": covered_entrypoint_ids,
            "missing_entrypoint_ids": missing_entrypoint_ids,
            "entrypoint_statuses": entrypoint_statuses,
            "evidence_refs": matrix_evidence_refs,
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "active_production_mutated": False,
            "privacy_boundary": "sanitized-entrypoint-statuses-receipt-ids-and-evidence-refs-only-no-prompts-outputs-session-ids-or-local-paths",
            "mutation_boundary": "forward-pass-enforcement-receipt-only-no-active-production-mutation",
        }
    return {
        "schema_version": "nexusnet-whole-system-forward-pass-enforcement-matrix-v1",
        "surface_id": "whole-system-forward-pass-enforcement-matrix",
        "status_label": "LOCKED CANON",
        "runtime_state": "live-bound" if covered_rows else "static-canon",
        "coverage_status": "covered" if not missing_rows else "partial",
        "session_ref_digest": session_ref_digest,
        "receipt_count": 1 if latest_receipt else 0,
        "latest_receipt_id": latest_receipt.get("receipt_id") if latest_receipt else None,
        "latest_receipt": latest_receipt,
        "receipts": [latest_receipt] if latest_receipt else [],
        "required_capability_columns": list(FORWARD_PASS_ENFORCEMENT_CAPABILITY_COLUMNS),
        "required_entrypoint_ids": list(FORWARD_PASS_ENFORCEMENT_ENTRYPOINT_IDS),
        "entrypoint_count": len(rows),
        "covered_entrypoint_count": len(covered_rows),
        "missing_entrypoint_count": len(missing_rows),
        "not_run_entrypoint_count": len(not_run_rows),
        "covered_entrypoint_ids": covered_entrypoint_ids,
        "missing_entrypoint_ids": missing_entrypoint_ids,
        "entrypoints": rows,
        "evidence_refs": matrix_evidence_refs,
        "go_no_go_blocking": False,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "active_production_mutated": False,
        "privacy_boundary": "sanitized-entrypoint-statuses-capability-columns-and-evidence-refs-only-no-prompts-outputs-session-ids-or-local-paths",
        "mutation_boundary": "forward-pass-enforcement-status-only-no-active-production-mutation",
    }


