def _runtime_decision_route_state(*, result: Any, interaction: dict[str, Any]) -> dict[str, Any]:
    status = str(getattr(result, "status", None) or interaction.get("status") or "ok")
    return {
        "surface_id": "release-wrapper-route-decision",
        "status": "routed-shadow" if status != "error" and not status.startswith("degraded") else "blocked-degraded",
        "provider": {"provider_id": interaction.get("provider_id") or "wrapped-model"},
        "selected_expert": interaction.get("expert_node") or "expert.general",
        "selected_ao": interaction.get("selected_ao"),
        "provider_readiness_status": interaction.get("provider_readiness_status"),
        "runtime_id": str(getattr(result, "runtime_name", None) or "release-wrapper-runtime"),
        "model_id": str(getattr(result, "model_id", None) or interaction.get("source_model") or "wrapped-model"),
        "estimated_cost_usd": 0.0,
        "active_route_mutation_allowed": False,
        "raw_content_included": False,
    }


def _runtime_decision_cache_state(cache_entry: dict[str, Any]) -> dict[str, Any]:
    context_economics = cache_entry.get("context_economics") if isinstance(cache_entry.get("context_economics"), dict) else {}
    kv_cache = cache_entry.get("kv_cache") if isinstance(cache_entry.get("kv_cache"), dict) else {}
    return {
        "surface_id": cache_entry.get("surface_id") or "effective-context-cache-ledger",
        "status": cache_entry.get("status") or "not-measured",
        "promotion_allowed": cache_entry.get("promotion_allowed") is True,
        "latest_cache_entry_id": cache_entry.get("entry_id"),
        "effective_context_tokens": _safe_count(context_economics.get("effective_context_tokens")),
        "raw_context_tokens": _safe_count(context_economics.get("raw_context_tokens")),
        "prefix_cache_hit_rate": _float_metric(kv_cache.get("prefix_cache_hit_rate")),
        "kv_cache_hit_rate": _float_metric(kv_cache.get("kv_cache_hit_rate")),
        "kv_cache_policy": kv_cache.get("policy") or "none",
        "privacy_scope": (cache_entry.get("privacy") or {}).get("privacy_scope") or "session",
        "promotion_blockers": cache_entry.get("promotion_blockers") or [],
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }


def _runtime_decision_eval_state(
    *,
    result: Any,
    cache_state: dict[str, Any],
    scorecard: dict[str, Any],
    evals_ao_artifact_gate: dict[str, Any],
) -> dict[str, Any]:
    eval_refs = [str(ref) for ref in scorecard.get("eval_refs") or [] if str(ref or "")]
    status = str(getattr(result, "status", None) or "")
    promotion_allowed = (
        status != "error"
        and cache_state.get("promotion_allowed") is True
        and scorecard.get("status") in {"measured", "warning"}
        and bool(eval_refs)
        and evals_ao_artifact_gate.get("promotion_allowed") is True
        and evals_ao_artifact_gate.get("artifact_set_complete") is True
    )
    return {
        "surface_id": "release-wrapper-runtime-eval-gate",
        "status": "shadow-eval-covered" if promotion_allowed else "blocked-or-missing-eval",
        "promotion_allowed": promotion_allowed,
        "eval_refs": eval_refs,
        "external_evals_ao_artifact_gate": evals_ao_artifact_gate,
        "runtime_scorecard_status": scorecard.get("status") or "missing",
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }


def _compact_runtime_quantization_state(recommendation: dict[str, Any]) -> dict[str, Any]:
    return {
        "surface_id": recommendation.get("surface_id") or "quantization-catalog",
        "request_id": recommendation.get("request_id"),
        "status": recommendation.get("status") or "unknown",
        "promotion_allowed": recommendation.get("promotion_allowed") is True,
        "promotion_blockers": recommendation.get("promotion_blockers") or [],
        "selected_method": recommendation.get("selected_method"),
        "kv_cache_plan": recommendation.get("kv_cache_plan"),
        "reason_codes": recommendation.get("reason_codes") or [],
        "upstream_runtime_scorecard_gate": recommendation.get("upstream_runtime_scorecard_gate") or {},
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }


def _runtime_decision_evidence_refs(
    *,
    interaction: dict[str, Any],
    cache_entry: dict[str, Any],
    scorecard: dict[str, Any],
    quantization_state: dict[str, Any],
    evals_ao_artifact_gate: dict[str, Any],
) -> list[str]:
    refs = [
        f"trace::{_safe_ref(str(interaction.get('trace_id') or 'trace'))}",
        str(cache_entry.get("entry_id") or ""),
        f"runtime-scorecard::{scorecard.get('scorecard_id')}" if scorecard.get("scorecard_id") else "",
        f"quantization::{quantization_state.get('request_id')}" if quantization_state.get("request_id") else "",
        f"evals-ao-artifact::{evals_ao_artifact_gate.get('gate_id')}" if evals_ao_artifact_gate.get("gate_id") else "",
        f"forward-pass::{interaction.get('forward_pass_receipt_id')}" if interaction.get("forward_pass_receipt_id") else "",
        f"federated-packet::{interaction.get('federated_packet_id')}" if interaction.get("federated_packet_id") else "",
        (
            f"production-spine-packet::{interaction.get('production_spine_packet_signature')}"
            if interaction.get("production_spine_packet_signature")
            else ""
        ),
    ]
    return [ref for ref in refs if ref]


def _compact_runtime_decision_record(record: Any) -> dict[str, Any] | None:
    if not isinstance(record, dict):
        return None
    compact = {
        "surface_id": record.get("surface_id") or "runtime-decision-ledger",
        "authority": record.get("authority") or "NexusBrain",
        "decision_id": record.get("decision_id"),
        "status": record.get("status"),
        "promotion_allowed": record.get("promotion_allowed") is True,
        "findings": record.get("findings") or [],
        "route_decision": record.get("route_decision") if isinstance(record.get("route_decision"), dict) else {},
        "cache_state": record.get("cache_state") if isinstance(record.get("cache_state"), dict) else {},
        "quantization_state": record.get("quantization_state") if isinstance(record.get("quantization_state"), dict) else {},
        "eval_state": record.get("eval_state") if isinstance(record.get("eval_state"), dict) else {},
        "evidence_refs": [str(ref) for ref in record.get("evidence_refs") or [] if str(ref or "")],
        "estimated_cost_usd": _float_metric(record.get("estimated_cost_usd")),
        "metadata": {
            key: value
            for key, value in (record.get("metadata") if isinstance(record.get("metadata"), dict) else {}).items()
            if key
            in {
                "source",
                "session_ref_digest",
                "trace_ref",
                "cache_ledger_entry_id",
                "runtime_scorecard_id",
                "context_capability_status",
                "federated_packet_id",
                "production_spine_packet_signature",
                "forward_pass_receipt_id",
                "evals_ao_artifact_gate_id",
                "raw_content_included",
                "active_production_mutation_allowed",
            }
        },
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }
    artifact_path = str(record.get("artifact_path") or "")
    if artifact_path:
        compact["artifact_path_digest"] = f"sha256:{_privacy_digest(artifact_path)}"
    return compact


def _context_window_posture_summary(
    *,
    effective_context_cache: dict[str, Any],
    session_ref_digest: str | None,
) -> dict[str, Any]:
    latest_entry = (
        effective_context_cache.get("latest_entry")
        if isinstance(effective_context_cache.get("latest_entry"), dict)
        else None
    )
    if latest_entry is None:
        return _empty_context_window_posture(session_ref_digest=session_ref_digest)
    context_economics = (
        latest_entry.get("context_economics")
        if isinstance(latest_entry.get("context_economics"), dict)
        else {}
    )
    observed_raw = _safe_count(context_economics.get("raw_context_tokens"))
    observed_effective = _safe_count(context_economics.get("effective_context_tokens"))
    latest_status = str(latest_entry.get("status") or "unknown")
    measured = latest_status in {"measured", "warning"}
    achieved = measured and observed_effective >= CANON_MIN_CONTEXT_TOKENS
    status = (
        "achieved-canon-minimum"
        if achieved
        else ("measured-below-canon-minimum" if measured else "not-measured")
    )
    artifact_path = str(latest_entry.get("artifact_path") or "")
    return {
        "status_label": "LOCKED CANON",
        "surface_id": "release-wrapper-context-window-posture",
        "authority": "NexusBrain",
        "status": status,
        "target_status": "met" if achieved else "not-met",
        "runtime_state": "live-bound" if achieved else ("shadow-target" if measured else "not-configured"),
        "canon_min_context_tokens": CANON_MIN_CONTEXT_TOKENS,
        "observed_raw_context_tokens": observed_raw,
        "observed_effective_context_tokens": observed_effective,
        "observed_effective_context_ratio": round(observed_effective / CANON_MIN_CONTEXT_TOKENS, 6),
        "achieved_canon_minimum": achieved,
        "latest_cache_entry_id": latest_entry.get("entry_id"),
        "latest_cache_status": latest_status,
        "latest_cache_artifact_path_digest": f"sha256:{_privacy_digest(artifact_path)}" if artifact_path else None,
        "cache_runtime_truth_boundary": effective_context_cache.get("runtime_truth_boundary"),
        "claim_boundary": "wrapper-measures-observed-effective-context-and-does-not-claim-1m-unless-live-receipts-meet-canon-minimum",
        "required_controls": [
            "effective-context-cache-ledger-entry",
            "observed_effective_context_tokens",
            "canon_min_context_tokens",
            "cache_privacy_scope",
            "benchmark_evidence_refs",
            "hardware-runtime-capability-evidence",
        ],
        "session_ref_digest": session_ref_digest,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }


