def _canonical_ao_coverage_summary(
    *,
    interactions: list[dict[str, Any]],
    session_ref_digest: str | None,
) -> dict[str, Any]:
    coverages = [
        interaction.get("canonical_ao_coverage")
        for interaction in interactions
        if isinstance(interaction.get("canonical_ao_coverage"), dict)
    ]
    latest = coverages[0] if coverages else None
    if latest is None:
        return _empty_canonical_ao_coverage(session_ref_digest=session_ref_digest)
    covered_aos = [str(item) for item in latest.get("covered_aos") or [] if str(item)]
    missing_aos = [str(item) for item in latest.get("missing_aos") or [] if str(item)]
    return {
        "surface_id": "release-wrapper-canonical-ao-coverage",
        "status_label": "LOCKED CANON",
        "runtime_state": "live-bound",
        "session_ref_digest": session_ref_digest,
        "coverage_count": len(coverages),
        "passed_count": sum(1 for coverage in coverages if coverage.get("passed") is True),
        "latest_coverage_id": latest.get("coverage_id"),
        "latest_trace_ref": latest.get("trace_ref"),
        "required_aos": list(WRAPPER_CANONICAL_AOS),
        "covered_aos": covered_aos,
        "missing_aos": missing_aos,
        "passed": bool(latest.get("passed")) and not missing_aos,
        "receipt_count": int(latest.get("receipt_count") or 0),
        "receipt_refs": [str(item) for item in latest.get("receipt_refs") or [] if str(item)],
        "latest_coverage": latest,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "runtime_boundary": "canonical-wrapper-aos-record-sanitized-trace-receipts-no-raw-prompts-or-session-ids",
    }


