def _domain_ao_route_from_receipt(
    *,
    receipt: dict[str, Any],
    selected_ao: str,
    session_ref_digest: str | None,
) -> dict[str, Any] | None:
    ao_name = str(receipt.get("ao_name") or selected_ao or "")
    if ao_name not in WRAPPER_DOMAIN_AOS:
        return None
    execution_id = str(receipt.get("execution_id") or "")
    trace_ref = str(receipt.get("trace_ref") or "")
    return {
        "surface_id": "release-wrapper-domain-ao-route",
        "status_label": "STRONG ACCEPTED DIRECTION",
        "route_id": f"domain-ao-route::{_safe_ref(execution_id or trace_ref or ao_name)}",
        "domain_ao": ao_name,
        "trace_ref": trace_ref or None,
        "execution_ref": execution_id or None,
        "session_ref_digest": str(receipt.get("session_ref_digest") or session_ref_digest or ""),
        "wrapper_mode": str(receipt.get("wrapper_mode") or "standard-chat"),
        "selected_expert": receipt.get("selected_expert"),
        "input_contract": receipt.get("input_contract") or "nexusbrain-command-envelope-and-trace-only",
        "consumed_refs": _dedupe_strings(
            [
                trace_ref,
                f"ao-execution::{execution_id}" if execution_id else "",
                f"domain-ao::{ao_name}",
            ]
        ),
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "runtime_boundary": "domain-ao-routing-records-receipt-refs-only-no-raw-prompts-or-session-ids",
    }


