def _domain_teacher_eval_handoff_summary(
    *,
    interactions: list[dict[str, Any]],
    session_ref_digest: str | None,
) -> dict[str, Any]:
    handoffs = [
        interaction.get("domain_teacher_eval_handoff")
        for interaction in interactions
        if isinstance(interaction.get("domain_teacher_eval_handoff"), dict)
    ]
    if not handoffs:
        return _empty_domain_teacher_eval_handoff(session_ref_digest=session_ref_digest)
    selected_domain_aos = _dedupe_strings(
        [str(handoff.get("domain_ao") or "") for handoff in handoffs if str(handoff.get("domain_ao") or "")]
    )
    teacher_subjects = _dedupe_strings(
        [
            str(handoff.get("teacher_subject") or "")
            for handoff in handoffs
            if str(handoff.get("teacher_subject") or "")
        ]
    )
    latest = handoffs[0]
    latest_eval_registry_ref = (
        latest.get("eval_registry_ref") if isinstance(latest.get("eval_registry_ref"), dict) else {}
    )
    growth_candidates = [
        handoff.get("expert_growth_candidate")
        for handoff in handoffs
        if isinstance(handoff.get("expert_growth_candidate"), dict)
    ]
    latest_growth_candidate = (
        latest.get("expert_growth_candidate") if isinstance(latest.get("expert_growth_candidate"), dict) else {}
    )
    latest_growth_cycle_ref = (
        latest_growth_candidate.get("growth_cycle_ref")
        if isinstance(latest_growth_candidate.get("growth_cycle_ref"), dict)
        else {}
    )
    latest_promotion_candidate_ref = (
        latest_growth_candidate.get("promotion_candidate_ref")
        if isinstance(latest_growth_candidate.get("promotion_candidate_ref"), dict)
        else {}
    )
    admin_eval_replay_refs = [
        candidate.get("admin_eval_replay_ref")
        for candidate in growth_candidates
        if isinstance(candidate.get("admin_eval_replay_ref"), dict)
    ]
    admin_promotion_decision_refs = [
        candidate.get("admin_promotion_decision_ref")
        for candidate in growth_candidates
        if isinstance(candidate.get("admin_promotion_decision_ref"), dict)
    ]
    sandbox_takeover_evidence_refs = [
        candidate.get("sandbox_takeover_evidence_ref")
        for candidate in growth_candidates
        if isinstance(candidate.get("sandbox_takeover_evidence_ref"), dict)
    ]
    latest_admin_eval_replay_ref = admin_eval_replay_refs[0] if admin_eval_replay_refs else {}
    latest_admin_promotion_decision_ref = (
        admin_promotion_decision_refs[0] if admin_promotion_decision_refs else {}
    )
    latest_sandbox_takeover_evidence_ref = (
        sandbox_takeover_evidence_refs[0] if sandbox_takeover_evidence_refs else {}
    )
    latest_growth_archive_candidate_ref = (
        latest_sandbox_takeover_evidence_ref.get("growth_archive_candidate_ref")
        if isinstance(latest_sandbox_takeover_evidence_ref.get("growth_archive_candidate_ref"), dict)
        else {}
    )
    passed = (
        bool(handoffs)
        and all(handoff.get("passed") is True for handoff in handoffs)
        and all(handoff.get("raw_content_included") is False for handoff in handoffs)
        and all(handoff.get("active_production_mutation_allowed") is False for handoff in handoffs)
        and len(growth_candidates) == len(handoffs)
        and all(candidate.get("status") == "recorded-shadow" for candidate in growth_candidates)
        and all(candidate.get("raw_content_included") is False for candidate in growth_candidates)
        and all(candidate.get("active_production_mutation_allowed") is False for candidate in growth_candidates)
        and all(
            (handoff.get("teacher_registry") or {}).get("status") == "linked"
            for handoff in handoffs
            if isinstance(handoff.get("teacher_registry"), dict)
        )
        and all(
            (handoff.get("eval_registry_ref") or {}).get("status") == "registered"
            for handoff in handoffs
            if isinstance(handoff.get("eval_registry_ref"), dict)
        )
    )
    return {
        "surface_id": "release-wrapper-domain-teacher-eval-handoff",
        "status_label": "STRONG ACCEPTED DIRECTION",
        "runtime_state": "live-bound",
        "session_ref_digest": session_ref_digest,
        "handoff_count": len(handoffs),
        "selected_domain_aos": selected_domain_aos,
        "teacher_subjects": teacher_subjects,
        "latest_domain_ao": latest.get("domain_ao"),
        "latest_teacher_subject": latest.get("teacher_subject"),
        "latest_handoff_id": latest.get("handoff_id"),
        "latest_trace_ref": latest.get("trace_ref"),
        "latest_eval_suite_id": latest_eval_registry_ref.get("suite_id"),
        "latest_shadow_run_id": latest_eval_registry_ref.get("shadow_run_id"),
        "expert_growth_candidate_count": len(growth_candidates),
        "latest_growth_cycle_id": latest_growth_cycle_ref.get("cycle_id"),
        "latest_promotion_candidate_id": latest_promotion_candidate_ref.get("candidate_id"),
        "admin_eval_replay_count": len(admin_eval_replay_refs),
        "latest_admin_eval_replay_id": latest_admin_eval_replay_ref.get("run_id"),
        "latest_admin_eval_replay_status": latest_admin_eval_replay_ref.get("status"),
        "latest_admin_promotion_decision_id": latest_admin_promotion_decision_ref.get("decision_id"),
        "latest_admin_promotion_decision": latest_admin_promotion_decision_ref.get("decision"),
        "latest_admin_promotion_governance_decision": latest_admin_promotion_decision_ref.get("governance_decision"),
        "sandbox_takeover_evidence_count": len(sandbox_takeover_evidence_refs),
        "latest_sandbox_takeover_evidence_id": latest_sandbox_takeover_evidence_ref.get("evidence_id"),
        "latest_sandbox_takeover_evidence_status": latest_sandbox_takeover_evidence_ref.get("status"),
        "latest_teacher_evidence_bundle_id": latest_sandbox_takeover_evidence_ref.get("teacher_evidence_bundle_id"),
        "latest_takeover_scorecard_id": latest_sandbox_takeover_evidence_ref.get("takeover_scorecard_id"),
        "latest_takeover_trend_report_id": latest_sandbox_takeover_evidence_ref.get("takeover_trend_report_id"),
        "latest_growth_archive_candidate_id": latest_growth_archive_candidate_ref.get("candidate_id"),
        "handoffs": handoffs[:10],
        "passed": passed,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "promotion_use_requires_operator_approval": True,
        "runtime_boundary": "domain-teacher-eval-handoff-records-teacher-and-eval-refs-only-no-raw-prompts-or-session-ids",
    }


