def _production_spine_lifecycle_admin_approval_record(
    approval: dict[str, Any] | None,
) -> dict[str, Any]:
    if not isinstance(approval, dict):
        return {
            "schema_version": "nexusnet-release-wrapper-production-spine-lifecycle-approval-v1",
            "surface_id": "release-wrapper-production-spine-lifecycle-approval",
            "status": "pending-admin-approval",
            "approval_ref": None,
            "approval_subject": "release-wrapper-production-spine-release-lifecycle",
            "decision": "missing",
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
            "privacy_boundary": "approval-status-only-no-approver-rationale-metadata-session-id-or-secrets",
            "mutation_boundary": "admin-approval-required-before-shadow-release-lifecycle-execution",
        }

    approval_ref = str(
        approval.get("approval_ref")
        or approval.get("approval_decision_id")
        or approval.get("decision_id")
        or ""
    ).strip()
    subject = str(
        approval.get("approval_subject")
        or approval.get("subject")
        or "release-wrapper-production-spine-release-lifecycle"
    ).strip()
    decision = str(approval.get("decision") or approval.get("status") or "").strip().lower()
    metadata = approval.get("metadata") if isinstance(approval.get("metadata"), dict) else {}
    return {
        "schema_version": "nexusnet-release-wrapper-production-spine-lifecycle-approval-v1",
        "surface_id": "release-wrapper-production-spine-lifecycle-approval",
        "status": "approved"
        if (
            approval_ref
            and subject == "release-wrapper-production-spine-release-lifecycle"
            and decision == "approved"
        )
        else "blocked-admin-approval",
        "approval_ref": _safe_ref(approval_ref) if approval_ref else None,
        "approval_subject": "release-wrapper-production-spine-release-lifecycle",
        "decision": decision or "missing",
        "approver_digest": f"sha256:{_privacy_digest(str(approval.get('approver') or approval.get('approved_by') or ''))}",
        "rationale_digest": f"sha256:{_privacy_digest(str(approval.get('rationale') or approval.get('approval_rationale') or ''))}",
        "metadata_digest": f"sha256:{_privacy_digest(json.dumps(metadata, sort_keys=True, default=str))}",
        "metadata_key_count": len(metadata),
        "created_at": str(approval.get("created_at") or ""),
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "privacy_boundary": "approval-ids-statuses-and-digests-only-no-approver-rationale-metadata-session-id-or-secrets",
        "mutation_boundary": "admin-approved-shadow-release-lifecycle-only-no-active-production-or-buyer-release-mutation",
    }


def _production_spine_lifecycle_step_summary(
    step_id: str,
    payload: dict[str, Any],
    *,
    ready: bool,
    blockers: list[Any] | None = None,
) -> dict[str, Any]:
    artifacts = payload.get("artifacts") if isinstance(payload.get("artifacts"), dict) else {}
    blocker_values = _dedupe_strings([str(item) for item in (blockers or []) if str(item or "").strip()])
    subject_id = (
        payload.get("lifecycle_id")
        or payload.get("key_id")
        or payload.get("bundle_id")
        or payload.get("readiness_id")
        or payload.get("diagnostics_id")
        or payload.get("monitor_id")
        or payload.get("release_id")
        or payload.get("review_id")
        or payload.get("packet_signature")
        or payload.get("signed_replay_id")
        or payload.get("replay_id")
    )
    return {
        "step_id": step_id,
        "status": "pass" if ready and not blocker_values else "blocked",
        "schema_version": payload.get("schema_version"),
        "subject_id": subject_id,
        "cycle_id": payload.get("cycle_id"),
        "lifecycle_id": payload.get("lifecycle_id"),
        "decision": payload.get("decision"),
        "blockers": blocker_values,
        "blocker_count": len(blocker_values),
        "artifact_path_digests": {
            str(key): f"sha256:{_privacy_digest(str(value))}" if value else None
            for key, value in artifacts.items()
        },
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "release_mutation_allowed": bool(payload.get("release_mutation_allowed")),
        "mutation_boundary": "production-spine-step-summary-only-no-active-production-mutation",
    }


