def _boot_check(check_id: str, status: bool, endpoint: str, detail: str, *, blocker: str = "") -> dict[str, Any]:
    record = {
        "check_id": check_id,
        "status": "pass" if status else "blocked",
        "endpoint": endpoint,
        "detail": detail,
        "raw_content_included": False,
    }
    if blocker and not status:
        record["blocker_digest"] = f"sha256:{_privacy_digest(blocker)}"
    return record


def _boot_supervisor_live_evidence(
    *,
    runtime: dict[str, Any],
    readiness: dict[str, Any],
    status_card: dict[str, Any],
    release_product_path: dict[str, Any],
) -> dict[str, Any]:
    forward_pass_coverage = (
        runtime.get("forward_pass_coverage") if isinstance(runtime.get("forward_pass_coverage"), dict) else {}
    )
    latest_receipt = (
        forward_pass_coverage.get("latest_receipt")
        if isinstance(forward_pass_coverage.get("latest_receipt"), dict)
        else {}
    )
    readiness_evidence = readiness.get("evidence") if isinstance(readiness.get("evidence"), dict) else {}
    runner = (
        readiness_evidence.get("release_readiness_evidence_runner")
        if isinstance(readiness_evidence.get("release_readiness_evidence_runner"), dict)
        else status_card.get("release_readiness_evidence_runner")
        if isinstance(status_card.get("release_readiness_evidence_runner"), dict)
        else {}
    )
    latest_runner = runner.get("latest_run") if isinstance(runner.get("latest_run"), dict) else {}
    inbox = runtime.get("federated_packet_inbox") if isinstance(runtime.get("federated_packet_inbox"), dict) else {}
    accepted_import = _boot_federated_import_by_status(inbox, "quarantined-shadow-accepted")
    rejected_import = _boot_federated_import_by_status(inbox, "quarantined-rejected")
    latest_import = inbox.get("latest_import") if isinstance(inbox.get("latest_import"), dict) else {}
    return {
        "forward_pass_coverage": {
            "latest_status": forward_pass_coverage.get("latest_status") or "not-run",
            "receipt_count": _safe_count(forward_pass_coverage.get("receipt_count")),
            "latest_receipt_id": latest_receipt.get("receipt_id"),
            "raw_content_included": False,
        },
        "release_readiness_evidence_runner": {
            "latest_status": runner.get("latest_status") or "not-run",
            "latest_run_id": latest_runner.get("run_id"),
            "active_production_mutated": bool(runner.get("active_production_mutated")),
        },
        "release_readiness": {
            "go_no_go": readiness.get("go_no_go") or "no-go",
            "blocker_count": len(readiness.get("blockers") or []),
        },
        "peer_federation_reject": _compact_boot_peer_federation_import_evidence(rejected_import),
        "peer_federation_import": _compact_boot_peer_federation_import_evidence(accepted_import or latest_import),
        "status_card": {
            "surface_id": status_card.get("surface_id") or "release-wrapper-status-card",
            "honest_status_label": status_card.get("honest_status_label") or "unknown",
            "raw_content_included": False,
        },
        "release_product_path": release_product_path,
    }


def _boot_supervisor_live_checks(
    *,
    runtime: dict[str, Any],
    readiness: dict[str, Any],
    status_card: dict[str, Any],
    evidence: dict[str, Any],
) -> list[dict[str, Any]]:
    forward_pass_coverage = evidence.get("forward_pass_coverage") if isinstance(evidence.get("forward_pass_coverage"), dict) else {}
    runner = (
        evidence.get("release_readiness_evidence_runner")
        if isinstance(evidence.get("release_readiness_evidence_runner"), dict)
        else {}
    )
    peer_import = evidence.get("peer_federation_import") if isinstance(evidence.get("peer_federation_import"), dict) else {}
    product_path = evidence.get("release_product_path") if isinstance(evidence.get("release_product_path"), dict) else {}
    return [
        _boot_check("api-health", True, "/health", "API process generated boot evidence"),
        _boot_check(
            "release-runtime",
            runtime.get("surface_id") == "release-wrapper-runtime"
            and (runtime.get("entrypoint") or {}).get("boot_target") == "/ui/wrapper/",
            "/ops/wrapper/release-runtime",
            "Release runtime summary is available for the wrapper product entrypoint",
            blocker="release-runtime missing wrapper entrypoint",
        ),
        _boot_check(
            "forward-pass-coverage",
            forward_pass_coverage.get("latest_status") == "covered"
            and _safe_count(forward_pass_coverage.get("receipt_count")) >= 1
            and forward_pass_coverage.get("raw_content_included") is False,
            "/ops/wrapper/release-runtime",
            "Forward-pass coverage is covered and sanitized",
            blocker="forward-pass coverage missing or unsanitized",
        ),
        _boot_check(
            "federated-peer-import",
            peer_import.get("status") == "quarantined-shadow-accepted"
            and peer_import.get("security_envelope_verified") is True
            and peer_import.get("assimilation_shadow_captured") is True
            and peer_import.get("global_growth_shadow_captured") is True
            and peer_import.get("raw_content_included") is False,
            "/ops/wrapper/federated-packets/imports",
            "Federated packet inbox has accepted sanitized shadow-import evidence",
            blocker="accepted federated peer import evidence missing",
        ),
        _boot_check(
            "readiness-runner",
            runner.get("latest_status") == "completed"
            and runner.get("active_production_mutated") is False,
            "/ops/wrapper/release-readiness/run",
            "Readiness runner completed without active production mutation",
            blocker="readiness runner missing or mutated active production",
        ),
        _boot_check(
            "release-readiness",
            readiness.get("go_no_go") == "go"
            and len(readiness.get("blockers") or []) == 0,
            "/ops/wrapper/release-readiness",
            "Release readiness reports go",
            blocker="release readiness is blocked",
        ),
        _boot_check(
            "status-card",
            status_card.get("surface_id") == "release-wrapper-status-card"
            and status_card.get("raw_content_included") is not True,
            "/ops/wrapper/status-card",
            "Status card fetched with sanitized release state",
            blocker="status card missing or unsanitized",
        ),
        _boot_check(
            "release-product-path",
            _boot_release_product_path_is_evidenced(product_path),
            "/ops/wrapper/status-card",
            "Product path covers growth, federation, dream/research, safe apply, rollback, and self-repair",
            blocker="release product path evidence incomplete",
        ),
        _boot_check(
            "boot-manifest-persisted",
            True,
            BOOT_SUPERVISOR_MANIFEST_REF,
            "Boot manifest is written as a sanitized runtime artifact",
        ),
    ]


def _boot_federated_import_by_status(inbox: dict[str, Any], status: str) -> dict[str, Any]:
    imports = inbox.get("imports") if isinstance(inbox.get("imports"), list) else []
    return next(
        (
            record
            for record in imports
            if isinstance(record, dict) and record.get("status") == status
        ),
        {},
    )


def _boot_release_product_path_evidence(
    *,
    runtime: dict[str, Any],
    status_card: dict[str, Any],
) -> dict[str, Any]:
    entrypoint = runtime.get("entrypoint") if isinstance(runtime.get("entrypoint"), dict) else {}
    global_growth = runtime.get("global_growth") if isinstance(runtime.get("global_growth"), dict) else {}
    inbox = runtime.get("federated_packet_inbox") if isinstance(runtime.get("federated_packet_inbox"), dict) else {}
    production_spine = runtime.get("production_spine") if isinstance(runtime.get("production_spine"), dict) else {}
    dream_queue = runtime.get("dream_research_queue") if isinstance(runtime.get("dream_research_queue"), dict) else {}
    autonomous_updates = runtime.get("autonomous_updates") if isinstance(runtime.get("autonomous_updates"), dict) else {}
    telemetry = runtime.get("live_wrapper_telemetry") if isinstance(runtime.get("live_wrapper_telemetry"), dict) else {}
    status_runtime = status_card.get("runtime") if isinstance(status_card.get("runtime"), dict) else {}
    status_telemetry = (
        status_runtime.get("live_wrapper_telemetry")
        if isinstance(status_runtime.get("live_wrapper_telemetry"), dict)
        else {}
    )
    failure_learning = (
        telemetry.get("failure_learning") if isinstance(telemetry.get("failure_learning"), dict) else {}
    ) or (
        status_telemetry.get("failure_learning") if isinstance(status_telemetry.get("failure_learning"), dict) else {}
    )
    self_repair = (
        status_card.get("self_repair_ledger")
        if isinstance(status_card.get("self_repair_ledger"), dict)
        else status_runtime.get("self_repair_ledger")
        if isinstance(status_runtime.get("self_repair_ledger"), dict)
        else runtime.get("self_repair_ledger")
        if isinstance(runtime.get("self_repair_ledger"), dict)
        else {}
    )
    action_lane = (
        status_card.get("operator_action_lane")
        if isinstance(status_card.get("operator_action_lane"), dict)
        else {}
    )
    action_statuses = (
        action_lane.get("latest_action_statuses")
        if isinstance(action_lane.get("latest_action_statuses"), dict)
        else {}
    )
    runner = (
        runtime.get("release_readiness_evidence_runner")
        if isinstance(runtime.get("release_readiness_evidence_runner"), dict)
        else status_card.get("release_readiness_evidence_runner")
        if isinstance(status_card.get("release_readiness_evidence_runner"), dict)
        else {}
    )
    latest_runner = runner.get("latest_run") if isinstance(runner.get("latest_run"), dict) else {}
    runner_actions = latest_runner.get("actions") if isinstance(latest_runner.get("actions"), dict) else {}

    def _admin_status(action: str, fallback: str) -> str:
        current = str(action_statuses.get(action) or fallback)
        if current not in {fallback, "pending-admin-approval", "not-run", "not-applied", "not-rolled-back"}:
            return current
        runner_action = runner_actions.get(action) if isinstance(runner_actions.get(action), dict) else {}
        return str(runner_action.get("status") or current)

    return {
        "entrypoint_runtime_state": str(entrypoint.get("runtime_state") or "unknown"),
        "global_growth_users": _safe_count(global_growth.get("users")),
        "training_ready_node_count": len(global_growth.get("training_ready_nodes") or []),
        "federated_packet_count": _safe_count(runtime.get("federated_packet_count")),
        "federated_import_count": _safe_count(inbox.get("import_count")),
        "federated_import_accepted_count": _safe_count(inbox.get("accepted_import_count")),
        "federated_import_rejected_count": _safe_count(inbox.get("rejected_import_count")),
        "federated_import_degraded_count": _safe_count(inbox.get("degraded_import_count")),
        "peer_shadow_proposal_count": _boot_peer_shadow_proposal_count(
            autonomous_updates=autonomous_updates,
            dream_queue=dream_queue,
        ),
        "production_spine_packet_count": _safe_count(production_spine.get("packet_count")),
        "dream_research_item_count": _safe_count(dream_queue.get("item_count")),
        "dream_research_episode_count": _safe_count(dream_queue.get("episode_count")),
        "autonomous_update_proposal_count": _safe_count(autonomous_updates.get("proposal_count")),
        "self_repair_action_count": _safe_count(self_repair.get("repair_count")),
        "latest_self_repair_action": str(self_repair.get("latest_action") or "none"),
        "admin_action_statuses": {
            "admin_approval": _admin_status("admin_approval", "pending-admin-approval"),
            "sandbox_tests": _admin_status("sandbox_tests", "not-run"),
            "apply": _admin_status("apply", "not-applied"),
            "rollback": _admin_status("rollback", "not-rolled-back"),
        },
        "native_runtime_growth_governance": (
            runtime.get("native_runtime_growth_governance")
            if isinstance(runtime.get("native_runtime_growth_governance"), dict)
            else status_card.get("native_runtime_growth_governance")
            if isinstance(status_card.get("native_runtime_growth_governance"), dict)
            else _empty_boot_native_runtime_growth_governance_evidence()
        ),
        "failure_learning": {
            "captured_count": _safe_count(failure_learning.get("captured_count")),
            "degraded_count": _safe_count(failure_learning.get("degraded_count")),
            "latest_status": str(failure_learning.get("latest_status") or "not-run"),
        },
        "active_production_mutation_allowed": False,
        "raw_content_included": False,
    }


def _boot_peer_shadow_proposal_count(
    *,
    autonomous_updates: dict[str, Any],
    dream_queue: dict[str, Any],
) -> int:
    count = 0
    proposals = autonomous_updates.get("proposals") if isinstance(autonomous_updates.get("proposals"), list) else []
    for proposal in proposals:
        if not isinstance(proposal, dict):
            continue
        metadata = proposal.get("metadata") if isinstance(proposal.get("metadata"), dict) else {}
        safe_payload = metadata.get("safe_payload") if isinstance(metadata.get("safe_payload"), dict) else {}
        if safe_payload.get("peer_shadow_import") is True:
            count += 1
    latest_item = dream_queue.get("latest_item") if isinstance(dream_queue.get("latest_item"), dict) else {}
    latest_metadata = latest_item.get("metadata") if isinstance(latest_item.get("metadata"), dict) else {}
    return max(count, 1 if latest_metadata.get("peer_shadow_import") is True else 0)


def _boot_release_product_path_is_evidenced(product_path: dict[str, Any]) -> bool:
    statuses = (
        product_path.get("admin_action_statuses")
        if isinstance(product_path.get("admin_action_statuses"), dict)
        else {}
    )
    return (
        product_path.get("entrypoint_runtime_state") == "live-bound"
        and _safe_count(product_path.get("global_growth_users")) >= 1
        and _safe_count(product_path.get("federated_packet_count")) >= 1
        and _safe_count(product_path.get("federated_import_count")) >= 1
        and _safe_count(product_path.get("federated_import_accepted_count")) >= 1
        and _safe_count(product_path.get("peer_shadow_proposal_count")) >= 1
        and _safe_count(product_path.get("production_spine_packet_count")) >= 1
        and _safe_count(product_path.get("dream_research_item_count")) >= 1
        and _safe_count(product_path.get("autonomous_update_proposal_count")) >= 1
        and _safe_count(product_path.get("self_repair_action_count")) >= 1
        and statuses.get("admin_approval") == "admin-approved"
        and statuses.get("sandbox_tests") == "passed"
        and statuses.get("apply") == "applied-shadow-safe-file"
        and statuses.get("rollback") == "rolled-back"
        and product_path.get("active_production_mutation_allowed") is False
        and product_path.get("raw_content_included") is False
    )


def _empty_initial_release_supervisor_summary(
    *,
    session_ref_digest: str | None = None,
    latest_status: str = "not-run",
    runtime_state: str = "not-run",
    blocker: str | None = None,
) -> dict[str, Any]:
    action_statuses = {action: "not-run" for action in INITIAL_RELEASE_SUPERVISOR_ACTIONS}
    action_statuses["production_spine_release_lifecycle_rollback"] = "not-rolled-back"
    summary = {
        "schema_version": "nexusnet-release-wrapper-initial-release-supervisor-summary-v1",
        "surface_id": INITIAL_RELEASE_SUPERVISOR_SURFACE_ID,
        "status_label": "LOCKED CANON",
        "runtime_state": runtime_state,
        "latest_status": latest_status,
        "manifest_ref": INITIAL_RELEASE_SUPERVISOR_MANIFEST_REF,
        "manifest_path_digest": None,
        "manifest_id": None,
        "generated_at": None,
        "product_surface": "wrapper",
        "product_scope": "whole-system",
        "session_ref_digest": session_ref_digest,
        "action_statuses": action_statuses,
        "actions": {},
        "release_readiness": {
            "surface_id": "release-wrapper-readiness",
            "go_no_go": "no-go",
            "passed_check_count": 0,
            "blocked_check_count": 0,
            "blockers": [],
        },
        "boot_supervisor": {
            "surface_id": BOOT_SUPERVISOR_SURFACE_ID,
            "status": "not-run",
            "manifest_id": None,
            "pass_count": 0,
            "failed_count": 0,
        },
        "endpoint_refs": {
            "initial_release_supervisor_run": "/ops/wrapper/initial-release-supervisor/run",
            "release_runtime": "/ops/wrapper/release-runtime",
            "release_readiness": "/ops/wrapper/release-readiness",
            "release_health_heartbeat_supervisor_configure": (
                "/ops/wrapper/release-health-heartbeat/supervisor/configure"
            ),
            "release_health_heartbeat_supervisor_repair_run": (
                "/ops/wrapper/release-health-heartbeat/supervisor/repair-run"
            ),
            "boot_supervisor_run": "/ops/wrapper/boot-supervisor/run",
        },
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "active_production_mutated": False,
        "privacy_boundary": "sanitized-status-ids-counts-digests-only-no-raw-prompts-outputs-session-ids",
        "mutation_boundary": "admin-approved-shadow-safe-file-production-spine-and-boot-evidence-only",
    }
    if blocker:
        summary["blocker_digest"] = f"sha256:{_privacy_digest(blocker)}"
    return summary


def _initial_release_supervisor_summary_from_manifest(manifest_paths: list[Path]) -> dict[str, Any]:
    manifest_path = next((path for path in manifest_paths if path.exists()), None)
    if manifest_path is None:
        return _empty_initial_release_supervisor_summary()
    manifest_path_digest = f"sha256:{_privacy_digest(str(manifest_path))}"
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        summary = _empty_initial_release_supervisor_summary(
            latest_status="blocked-invalid-manifest",
            runtime_state="blocked-invalid-manifest",
            blocker=f"{type(exc).__name__}:{manifest_path_digest}",
        )
        summary["manifest_path_digest"] = manifest_path_digest
        return summary
    if not isinstance(manifest, dict):
        summary = _empty_initial_release_supervisor_summary(
            latest_status="blocked-invalid-manifest",
            runtime_state="blocked-invalid-manifest",
            blocker=f"manifest-not-object:{manifest_path_digest}",
        )
        summary["manifest_path_digest"] = manifest_path_digest
        return summary

    actions = manifest.get("actions") if isinstance(manifest.get("actions"), dict) else {}
    action_raw_violation = any(
        isinstance(action, dict) and action.get("raw_content_included") is not False for action in actions.values()
    )
    action_mutation_violation = any(
        isinstance(action, dict) and action.get("active_production_mutation_allowed") is True
        for action in actions.values()
    )
    if (
        manifest.get("schema_version") != INITIAL_RELEASE_SUPERVISOR_SCHEMA
        or manifest.get("surface_id") != INITIAL_RELEASE_SUPERVISOR_SURFACE_ID
        or manifest.get("raw_content_included") is not False
        or manifest.get("active_production_mutation_allowed") is not False
        or action_raw_violation
        or action_mutation_violation
    ):
        summary = _empty_initial_release_supervisor_summary(
            latest_status="blocked-invalid-manifest",
            runtime_state="blocked-invalid-manifest",
            blocker=f"schema-privacy-or-mutation-violation:{manifest_path_digest}",
        )
        summary["manifest_path_digest"] = manifest_path_digest
        return summary

    action_statuses = _compact_initial_release_action_statuses(manifest)
    compact_actions = _compact_initial_release_actions(actions)
    native_hive_heartbeat_history = compact_actions.get("native_hive_heartbeat_history", {})
    native_hive_heartbeat_history_ready = (
        native_hive_heartbeat_history.get("status") == "fresh"
        and native_hive_heartbeat_history.get("latest_fresh") is True
        and native_hive_heartbeat_history.get("raw_content_included") is False
        and native_hive_heartbeat_history.get("active_production_mutation_allowed") is False
    )
    latest_status = str(manifest.get("status") or manifest.get("honest_status_label") or "unknown")
    readiness = _compact_initial_release_readiness(manifest.get("release_readiness"))
    boot_supervisor = _compact_initial_release_boot_supervisor(manifest.get("boot_supervisor") or actions.get("boot_supervisor"))
    runtime_state = (
        "replayed-evidence"
        if latest_status == "initial-release-go"
        and manifest.get("active_production_mutated") is False
        and readiness.get("go_no_go") == "go"
        and native_hive_heartbeat_history_ready
        else "degraded-evidence"
    )
    endpoint_refs = _compact_initial_release_endpoint_refs(manifest.get("endpoint_refs"))
    return {
        "schema_version": "nexusnet-release-wrapper-initial-release-supervisor-summary-v1",
        "surface_id": INITIAL_RELEASE_SUPERVISOR_SURFACE_ID,
        "status_label": str(manifest.get("status_label") or "LOCKED CANON"),
        "runtime_state": runtime_state,
        "latest_status": latest_status,
        "manifest_ref": INITIAL_RELEASE_SUPERVISOR_MANIFEST_REF,
        "manifest_path_digest": manifest_path_digest,
        "manifest_id": manifest.get("manifest_id") if isinstance(manifest.get("manifest_id"), str) else None,
        "generated_at": manifest.get("generated_at") if isinstance(manifest.get("generated_at"), str) else None,
        "product_surface": str(manifest.get("product_surface") or "wrapper"),
        "product_scope": str(manifest.get("product_scope") or "whole-system"),
        "session_ref_digest": manifest.get("session_ref_digest")
        if isinstance(manifest.get("session_ref_digest"), str)
        else None,
        "action_statuses": action_statuses,
        "actions": compact_actions,
        "release_readiness": readiness,
        "boot_supervisor": boot_supervisor,
        "endpoint_refs": endpoint_refs,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "active_production_mutated": bool(manifest.get("active_production_mutated")),
        "privacy_boundary": str(
            manifest.get("privacy_boundary")
            or "sanitized-status-ids-counts-digests-only-no-raw-prompts-outputs-session-ids"
        ),
        "mutation_boundary": str(
            manifest.get("mutation_boundary")
            or "admin-approved-shadow-safe-file-production-spine-and-boot-evidence-only"
        ),
    }


def _compact_initial_release_action_statuses(manifest: dict[str, Any]) -> dict[str, str]:
    compact = {action: "not-run" for action in INITIAL_RELEASE_SUPERVISOR_ACTIONS}
    compact["production_spine_release_lifecycle_rollback"] = "not-rolled-back"
    statuses = manifest.get("action_statuses") if isinstance(manifest.get("action_statuses"), dict) else {}
    actions = manifest.get("actions") if isinstance(manifest.get("actions"), dict) else {}
    for action in INITIAL_RELEASE_SUPERVISOR_ACTIONS:
        status = statuses.get(action)
        action_record = actions.get(action) if isinstance(actions.get(action), dict) else {}
        compact[action] = str(status or action_record.get("status") or compact[action])
    return compact


def _compact_initial_release_actions(actions: dict[str, Any]) -> dict[str, dict[str, Any]]:
    compact: dict[str, dict[str, Any]] = {}
    for action in INITIAL_RELEASE_SUPERVISOR_ACTIONS:
        record = actions.get(action) if isinstance(actions.get(action), dict) else {}
        compact[action] = _compact_initial_release_action(record)
    return compact


def _compact_initial_release_action(record: dict[str, Any]) -> dict[str, Any]:
    compact = {
        "status": str(record.get("status") or "not-run"),
        "run_id": record.get("run_id") if isinstance(record.get("run_id"), str) else None,
        "import_id": record.get("import_id") if isinstance(record.get("import_id"), str) else None,
        "rollback_id": record.get("rollback_id") if isinstance(record.get("rollback_id"), str) else None,
        "interaction_count": int(record.get("interaction_count") or 0),
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }
    step_counts = record.get("step_counts") if isinstance(record.get("step_counts"), dict) else None
    if step_counts is not None:
        compact["step_counts"] = {
            "total": int(step_counts.get("total") or 0),
            "passed": int(step_counts.get("passed") or 0),
            "blocked": int(step_counts.get("blocked") or 0),
        }
    if "rollback_restored" in record:
        compact["rollback_restored"] = bool(record.get("rollback_restored"))
    if "pass_count" in record or "failed_count" in record:
        compact["pass_count"] = int(record.get("pass_count") or 0)
        compact["failed_count"] = int(record.get("failed_count") or 0)
    if "latest_fresh" in record:
        compact["latest_fresh"] = record.get("latest_fresh") is True
    if "freshness_status" in record:
        compact["freshness_status"] = str(record.get("freshness_status") or "not-run")
    if "artifact_ref" in record:
        compact["artifact_ref"] = str(record.get("artifact_ref") or "")
    if "latest_heartbeat_id" in record:
        compact["latest_heartbeat_id"] = (
            str(record.get("latest_heartbeat_id")) if record.get("latest_heartbeat_id") else None
        )
    if "latest_pulse_id" in record:
        compact["latest_pulse_id"] = str(record.get("latest_pulse_id")) if record.get("latest_pulse_id") else None
    if "latest_loop_id" in record:
        compact["latest_loop_id"] = str(record.get("latest_loop_id")) if record.get("latest_loop_id") else None
    if "pulse_count" in record:
        compact["pulse_count"] = int(record.get("pulse_count") or 0)
    if "next_due_status" in record:
        compact["next_due_status"] = str(record.get("next_due_status") or "unknown")
    for key in (
        "update_id",
        "source_pulse_id",
        "source_loop_id",
        "source_heartbeat_id",
        "readiness_run_id",
        "readiness_evidence_status",
    ):
        if record.get(key):
            compact[key] = str(record.get(key))
    action_statuses = record.get("action_statuses") if isinstance(record.get("action_statuses"), dict) else {}
    if action_statuses:
        compact["action_statuses"] = {
            "admin_approval": str(action_statuses.get("admin_approval") or "not-approved"),
            "shadow_eval_replay": str(action_statuses.get("shadow_eval_replay") or "not-run"),
            "sandbox_tests": str(action_statuses.get("sandbox_tests") or "not-run"),
            "apply": str(action_statuses.get("apply") or "not-applied"),
            "rollback": str(action_statuses.get("rollback") or "not-rolled-back"),
        }
    return compact


def _compact_initial_release_readiness(readiness: Any) -> dict[str, Any]:
    record = readiness if isinstance(readiness, dict) else {}
    blockers = record.get("blockers") if isinstance(record.get("blockers"), list) else []
    return {
        "surface_id": str(record.get("surface_id") or "release-wrapper-readiness"),
        "go_no_go": str(record.get("go_no_go") or "no-go"),
        "passed_check_count": int(record.get("passed_check_count") or 0),
        "blocked_check_count": int(record.get("blocked_check_count") or 0),
        "blockers": [str(blocker) for blocker in blockers if str(blocker or "")],
    }


def _compact_initial_release_boot_supervisor(boot: Any) -> dict[str, Any]:
    record = boot if isinstance(boot, dict) else {}
    return {
        "surface_id": str(record.get("surface_id") or BOOT_SUPERVISOR_SURFACE_ID),
        "status": str(record.get("status") or record.get("latest_status") or "not-run"),
        "manifest_id": record.get("manifest_id") if isinstance(record.get("manifest_id"), str) else None,
        "pass_count": int(record.get("pass_count") or 0),
        "failed_count": int(record.get("failed_count") or 0),
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }


def _compact_initial_release_endpoint_refs(endpoint_refs: Any) -> dict[str, str]:
    refs = endpoint_refs if isinstance(endpoint_refs, dict) else {}
    return {
        "initial_release_supervisor_run": str(
            refs.get("initial_release_supervisor_run") or "/ops/wrapper/initial-release-supervisor/run"
        ),
        "release_runtime": str(refs.get("release_runtime") or "/ops/wrapper/release-runtime"),
        "release_readiness": str(refs.get("release_readiness") or "/ops/wrapper/release-readiness"),
        "release_health_heartbeat_supervisor_configure": str(
            refs.get("release_health_heartbeat_supervisor_configure")
            or "/ops/wrapper/release-health-heartbeat/supervisor/configure"
        ),
        "release_health_heartbeat_supervisor_repair_run": str(
            refs.get("release_health_heartbeat_supervisor_repair_run")
            or "/ops/wrapper/release-health-heartbeat/supervisor/repair-run"
        ),
        "boot_supervisor_run": str(refs.get("boot_supervisor_run") or "/ops/wrapper/boot-supervisor/run"),
    }


