def _compact_boot_native_runtime_growth_governance_evidence(native: dict[str, Any]) -> dict[str, Any]:
    compact = _empty_boot_native_runtime_growth_governance_evidence()
    if not isinstance(native, dict):
        return compact
    statuses = native.get("latest_action_statuses") if isinstance(native.get("latest_action_statuses"), dict) else {}
    compact["status"] = _safe_ref(str(native.get("status") or compact["status"]))
    compact["native_hive_runtime_growth"] = native.get("native_hive_runtime_growth") is True
    compact["proposal_update_id"] = str(native.get("proposal_update_id")) if native.get("proposal_update_id") else None
    compact["runtime_growth_receipt_id"] = (
        str(native.get("runtime_growth_receipt_id")) if native.get("runtime_growth_receipt_id") else None
    )
    compact["latest_action_statuses"] = {
        "proposal": _safe_ref(str(statuses.get("proposal") or "not-generated")),
        "admin_approval": _safe_ref(str(statuses.get("admin_approval") or "pending-admin-approval")),
        "shadow_eval_replay": _safe_ref(str(statuses.get("shadow_eval_replay") or "not-run")),
        "sandbox_tests": _safe_ref(str(statuses.get("sandbox_tests") or "not-run")),
        "apply": _safe_ref(str(statuses.get("apply") or "not-applied")),
        "rollback": _safe_ref(str(statuses.get("rollback") or "not-rolled-back")),
        "readiness_runner": _safe_ref(
            str(statuses.get("readiness_runner") or native.get("latest_runner_status") or "not-run")
        ),
    }
    compact["latest_runner_status"] = _safe_ref(str(native.get("latest_runner_status") or "not-run"))
    compact["latest_runner_run_id"] = (
        str(native.get("latest_runner_run_id") or native.get("latest_run_id"))
        if native.get("latest_runner_run_id") or native.get("latest_run_id")
        else None
    )
    compact["active_production_mutated"] = bool(native.get("active_production_mutated"))
    compact["active_production_mutation_allowed"] = False
    compact["raw_content_included"] = False
    return compact


