def _compact_boot_release_product_path_evidence(product_path: dict[str, Any]) -> dict[str, Any]:
    compact = _empty_boot_release_product_path_evidence()
    action_statuses = product_path.get("admin_action_statuses")
    if not isinstance(action_statuses, dict):
        action_statuses = {}
    failure_learning = product_path.get("failure_learning")
    if not isinstance(failure_learning, dict):
        failure_learning = {}
    for key in (
        "global_growth_users",
        "training_ready_node_count",
        "federated_packet_count",
        "federated_import_count",
        "federated_import_accepted_count",
        "federated_import_rejected_count",
        "federated_import_degraded_count",
        "peer_shadow_proposal_count",
        "production_spine_packet_count",
        "dream_research_item_count",
        "dream_research_episode_count",
        "autonomous_update_proposal_count",
        "self_repair_action_count",
    ):
        compact[key] = _safe_count(product_path.get(key))
    compact["entrypoint_runtime_state"] = _safe_ref(product_path.get("entrypoint_runtime_state") or "not-run")
    compact["latest_self_repair_action"] = _safe_ref(product_path.get("latest_self_repair_action") or "none")
    compact["admin_action_statuses"] = {
        "admin_approval": _safe_ref(action_statuses.get("admin_approval") or "pending-admin-approval"),
        "sandbox_tests": _safe_ref(action_statuses.get("sandbox_tests") or "not-run"),
        "apply": _safe_ref(action_statuses.get("apply") or "not-applied"),
        "rollback": _safe_ref(action_statuses.get("rollback") or "not-rolled-back"),
    }
    compact["native_runtime_growth_governance"] = _compact_boot_native_runtime_growth_governance_evidence(
        product_path.get("native_runtime_growth_governance")
        if isinstance(product_path.get("native_runtime_growth_governance"), dict)
        else {}
    )
    compact["failure_learning"] = {
        "captured_count": _safe_count(failure_learning.get("captured_count")),
        "degraded_count": _safe_count(failure_learning.get("degraded_count")),
        "latest_status": _safe_ref(failure_learning.get("latest_status") or "not-run"),
    }
    compact["active_production_mutation_allowed"] = False
    compact["raw_content_included"] = False
    return compact


