def _release_run_history_summary_from_records(
    records: list[dict[str, Any]],
    *,
    session_ref_digest: str | None,
    limit: int,
) -> dict[str, Any]:
    scoped_session_ref = f"sha256:{session_ref_digest}" if session_ref_digest else None
    scoped_records = [
        record
        for record in records
        if scoped_session_ref is None or record.get("session_ref_digest") == scoped_session_ref
    ]
    if not scoped_records:
        return _empty_release_run_history(session_ref_digest=scoped_session_ref, global_run_count=len(records))
    recent_runs = [_compact_release_run_record(record) for record in scoped_records[-limit:]]
    latest_run = recent_runs[-1]
    return {
        "schema_version": RELEASE_RUN_HISTORY_SCHEMA,
        "surface_id": RELEASE_RUN_HISTORY_SURFACE_ID,
        "status_label": "LOCKED CANON",
        "runtime_state": "live-evidence",
        "latest_status": latest_run.get("status") or "unknown",
        "product_surface": "wrapper",
        "product_scope": "whole-system",
        "session_ref_digest": scoped_session_ref,
        "run_count": len(scoped_records),
        "global_run_count": len(records),
        "latest_run": latest_run,
        "runs": recent_runs,
        "manifest_ref": RELEASE_RUN_HISTORY_MANIFEST_REF,
        "endpoint_refs": {
            "release_run_history": "/ops/wrapper/release-runtime",
            "release_product_smoke_run": "/ops/wrapper/release-product-smoke/run",
            "status_card": "/ops/wrapper/status-card",
            "session_lifecycle": "/ops/wrapper/session-lifecycle",
            "control_panel": "/ui/control-panel/",
            "visualizer": "/ui/visualizer/",
        },
        "evidence_refs": [f"release-run::{run.get('run_id')}" for run in recent_runs if run.get("run_id")],
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "active_production_mutated": False,
        "privacy_boundary": "sanitized-release-run-history-status-counts-digests-and-endpoint-refs-only-no-prompts-outputs-admin-identities-session-ids-or-local-paths",
        "mutation_boundary": "release-run-history-evidence-only-no-active-production-mutation",
    }


def _compact_release_run_record(record: dict[str, Any]) -> dict[str, Any]:
    return {
        "schema_version": str(record.get("schema_version") or RELEASE_RUN_HISTORY_SCHEMA),
        "surface_id": str(record.get("surface_id") or RELEASE_RUN_SURFACE_ID),
        "run_id": record.get("run_id"),
        "run_kind": str(record.get("run_kind") or "release-run"),
        "run_sequence": _safe_count(record.get("run_sequence")),
        "created_at": record.get("created_at"),
        "status": str(record.get("status") or "unknown"),
        "honest_status_label": str(record.get("honest_status_label") or record.get("status") or "unknown"),
        "product_surface": str(record.get("product_surface") or "wrapper"),
        "product_scope": str(record.get("product_scope") or "whole-system"),
        "session_ref_digest": record.get("session_ref_digest") if isinstance(record.get("session_ref_digest"), str) else None,
        "manifest_id": record.get("manifest_id") if isinstance(record.get("manifest_id"), str) else None,
        "manifest_ref": str(record.get("manifest_ref") or RELEASE_PRODUCT_SMOKE_MANIFEST_REF),
        "history_ref": str(record.get("history_ref") or RELEASE_RUN_HISTORY_MANIFEST_REF),
        "check_count": _safe_count(record.get("check_count")),
        "pass_count": _safe_count(record.get("pass_count")),
        "failed_count": _safe_count(record.get("failed_count")),
        "whole_system_evidence": record.get("whole_system_evidence")
        if isinstance(record.get("whole_system_evidence"), dict)
        else {},
        "canon_contract_ledger": compact_canon_contract_ledger(
            record.get("canon_contract_ledger") if isinstance(record.get("canon_contract_ledger"), dict) else {}
        ),
        "canon_contract_receipts": record.get("canon_contract_receipts")
        if isinstance(record.get("canon_contract_receipts"), dict)
        else {
            "surface_id": "whole-project-canon-contract-receipts",
            "receipt_count": 0,
            "latest_status": "not-run",
            "raw_content_included": False,
            "active_production_mutation_allowed": False,
        },
        "endpoint_refs": record.get("endpoint_refs") if isinstance(record.get("endpoint_refs"), dict) else {},
        "evidence_refs": [str(ref) for ref in (record.get("evidence_refs") or []) if str(ref or "")],
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "active_production_mutated": False,
        "privacy_boundary": str(
            record.get("privacy_boundary")
            or "sanitized-release-run-status-counts-digests-and-endpoint-refs-only-no-prompts-outputs-admin-identities-session-ids-or-local-paths"
        ),
        "mutation_boundary": str(
            record.get("mutation_boundary")
            or "release-run-history-evidence-only-no-active-production-mutation"
        ),
    }


