def _safe_count(value: Any) -> int:
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _hardware_profile_payload(scanner: Any) -> dict[str, Any]:
    try:
        profile = scanner.scan()
    except Exception as exc:  # pragma: no cover - defensive fallback for host scanner failures
        return {
            "profile_id": f"hardware::scan-error::{_privacy_digest(str(exc))}",
            "platform": "unknown",
            "python_version": "unknown",
            "cpu_count": 0,
            "ram_gb": None,
            "vram_gb": None,
            "gpu_summary": "unreported",
            "thermal_mode": "unknown",
            "ram_pressure": "unknown",
            "vram_pressure": "unreported",
            "safe_mode": True,
            "max_context_tokens": 0,
            "long_context_profile": {"ambition_tokens": CANON_MIN_CONTEXT_TOKENS, "host_cap_tokens": 0},
            "local_first": True,
            "status_label": "LOCKED CANON",
            "scan_error_digest": f"sha256:{_privacy_digest(str(exc))}",
        }
    if hasattr(profile, "model_dump"):
        payload = profile.model_dump(mode="json")
    elif isinstance(profile, dict):
        payload = dict(profile)
    else:
        payload = {
            key: getattr(profile, key)
            for key in [
                "profile_id",
                "platform",
                "python_version",
                "cpu_count",
                "ram_gb",
                "vram_gb",
                "gpu_summary",
                "thermal_mode",
                "ram_pressure",
                "vram_pressure",
                "safe_mode",
                "max_context_tokens",
                "long_context_profile",
                "local_first",
                "status_label",
            ]
            if hasattr(profile, key)
        }
    payload.setdefault("long_context_profile", {})
    payload.setdefault("max_context_tokens", _safe_count((payload.get("long_context_profile") or {}).get("host_cap_tokens")))
    payload.setdefault("status_label", "LOCKED CANON")
    return payload


def _hardware_lane(hardware_profile: dict[str, Any]) -> str:
    if _float_metric(hardware_profile.get("vram_gb")) >= 12.0:
        return "local-gpu"
    if _float_metric(hardware_profile.get("ram_gb")) >= 24.0:
        return "local-cpu"
    return "local-safe-mode"


def _observed_wrapper_latency_ms(result: Any, *, observed_effective_tokens: int) -> int:
    trace = getattr(result, "trace", None)
    trace_metrics = getattr(trace, "metrics", None)
    if isinstance(trace_metrics, dict):
        latency = _safe_count(
            trace_metrics.get("brain_latency_ms")
            or trace_metrics.get("latency_ms")
            or trace_metrics.get("ttft_ms")
        )
        if latency > 0:
            return latency
    latency = _safe_count(getattr(result, "latency_ms", None))
    if latency > 0:
        return latency
    return max(1, min(3000, observed_effective_tokens * 12))


def _observed_decode_tokens_per_sec(*, observed_effective_tokens: int, latency_ms: int) -> float:
    return round(max(1, observed_effective_tokens) / max(latency_ms, 1) * 1000.0, 4)


def _latency_metric_source(result: Any) -> str:
    trace = getattr(result, "trace", None)
    trace_metrics = getattr(trace, "metrics", None)
    if isinstance(trace_metrics, dict) and (
        trace_metrics.get("brain_latency_ms")
        or trace_metrics.get("latency_ms")
        or trace_metrics.get("ttft_ms")
    ):
        return "result.trace.metrics"
    if getattr(result, "latency_ms", None):
        return "result.latency_ms"
    return "token-count-estimate"


def _compact_endpoint_ref(value: Any) -> str | None:
    if not isinstance(value, str):
        return None
    if value.startswith("/"):
        return value
    if _is_loopback_url(value):
        return value
    return f"sha256:{_privacy_digest(value)}"


def _is_loopback_url(value: Any) -> bool:
    return isinstance(value, str) and (
        value.startswith("http://127.0.0.1:")
        or value.startswith("http://localhost:")
        or value.startswith("http://[::1]:")
    )


