def _build_live_wrapper_telemetry(
    *,
    interactions: list[dict[str, Any]],
    continuous_status: dict[str, Any],
    global_growth: dict[str, Any],
    federated_packet_count: int,
    latest_packet: dict[str, Any] | None,
    production_spine: dict[str, Any],
) -> dict[str, Any]:
    nodes = continuous_status.get("nodes") if isinstance(continuous_status.get("nodes"), dict) else {}
    captures_by_node = {
        str(node_id): int((node_status or {}).get("captures") or 0)
        for node_id, node_status in nodes.items()
        if isinstance(node_status, dict)
    }
    latest_production_packet = (
        production_spine.get("latest_packet")
        if isinstance(production_spine.get("latest_packet"), dict)
        else {}
    )
    recent_events = [
        {
            "trace_id": event.get("trace_id"),
            "session_ref_digest": event.get("session_ref_digest"),
            "source_model": event.get("source_model"),
            "expert_node": event.get("expert_node"),
            "selected_ao": event.get("selected_ao"),
            "knowledge_ref": event.get("knowledge_ref"),
            "hive_run_id": event.get("hive_run_id"),
            "federated_packet_id": event.get("federated_packet_id"),
            "federated_prior_update_id": event.get("federated_prior_update_id"),
            "production_spine_packet_signature": event.get("production_spine_packet_signature"),
            "cache_ledger_entry_id": event.get("cache_ledger_entry_id"),
            "runtime_scorecard_id": event.get("runtime_scorecard_id"),
            "improvement_queue_id": event.get("improvement_queue_id"),
            "dream_research_episode_id": event.get("dream_research_episode_id"),
            "ao_execution_receipt_id": event.get("ao_execution_receipt_id"),
            "ao_execution_trace_ref": event.get("ao_execution_trace_ref"),
            "domain_ao": (
                (event.get("domain_ao_routing") or {}).get("domain_ao")
                if isinstance(event.get("domain_ao_routing"), dict)
                else None
            ),
            "domain_ao_route_id": (
                (event.get("domain_ao_routing") or {}).get("route_id")
                if isinstance(event.get("domain_ao_routing"), dict)
                else None
            ),
            "failure_learning_signal_id": (
                (event.get("failure_learning_signal") or {}).get("signal_id")
                if isinstance(event.get("failure_learning_signal"), dict)
                else None
            ),
            "failure_learning_signal_status": (
                (event.get("failure_learning_signal") or {}).get("status")
                if isinstance(event.get("failure_learning_signal"), dict)
                else None
            ),
            "created_at": event.get("created_at"),
            "raw_content_included": False,
        }
        for event in interactions[:8]
    ]
    failure_learning_signals = [
        event.get("failure_learning_signal")
        for event in interactions
        if isinstance(event.get("failure_learning_signal"), dict)
    ]
    latest_failure_learning_signal = failure_learning_signals[0] if failure_learning_signals else {}
    failure_learning = {
        "surface_id": "release-wrapper-failure-learning-summary",
        "captured_count": sum(1 for signal in failure_learning_signals if signal.get("status") == "captured"),
        "degraded_count": sum(1 for signal in failure_learning_signals if signal.get("status") != "captured"),
        "latest_status": latest_failure_learning_signal.get("status") or "not-run",
        "latest_signal_id": latest_failure_learning_signal.get("signal_id"),
        "latest_failure_ref": latest_failure_learning_signal.get("failure_ref"),
        "continuous_assimilation_captured": bool(
            latest_failure_learning_signal.get("continuous_assimilation_captured")
        ),
        "global_growth_captured": bool(latest_failure_learning_signal.get("global_growth_captured")),
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
    }
    evidence_refs = [
        "/ops/wrapper/release-runtime",
        "/ops/wrapper/status-card",
        "/ops/brain/visualizer/state",
    ]
    if latest_packet and latest_packet.get("packet_id"):
        evidence_refs.append(f"federated-packet::{latest_packet.get('packet_id')}")
    if latest_production_packet.get("packet_signature"):
        evidence_refs.append(f"production-spine-packet::{latest_production_packet.get('packet_signature')}")
    forward_pass_coverage = _forward_pass_coverage_summary(interactions)
    latest_receipt = forward_pass_coverage.get("latest_receipt")
    if isinstance(latest_receipt, dict) and latest_receipt.get("receipt_id"):
        evidence_refs.append(f"forward-pass-receipt::{latest_receipt.get('receipt_id')}")
    if latest_failure_learning_signal.get("signal_id"):
        evidence_refs.append(f"failure-learning::{latest_failure_learning_signal.get('signal_id')}")
    for event in recent_events[:4]:
        if event.get("trace_id"):
            evidence_refs.append(f"trace::{event.get('trace_id')}")
        if event.get("dream_research_episode_id"):
            evidence_refs.append(f"dream-research-episode::{event.get('dream_research_episode_id')}")
    nexusbrain_runtime_cycle = _nexusbrain_runtime_cycle_summary(
        interactions,
        session_ref_digest=None,
    )
    if nexusbrain_runtime_cycle.get("latest_receipt_id"):
        evidence_refs.append(f"nexusbrain-cycle::{nexusbrain_runtime_cycle.get('latest_receipt_id')}")
    return {
        "surface_id": "release-wrapper-live-telemetry",
        "status_label": "LOCKED CANON",
        "runtime_state": "live-bound" if interactions else "static-canon",
        "source": "release-wrapper-runtime-events",
        "event_count": len(interactions),
        "recent_events": recent_events,
        "continuous_assimilation": {
            "node_count": len(nodes),
            "capture_count": sum(captures_by_node.values()),
            "training_ready_node_count": len(continuous_status.get("training_ready_nodes") or []),
            "captures_by_node": captures_by_node,
            "continuous": bool(continuous_status.get("continuous")),
            "mutates_production": bool(continuous_status.get("mutates_production")),
        },
        "global_growth": {
            "users": int(global_growth.get("users") or 0),
            "global_captures": int(global_growth.get("global_captures") or 0),
            "expert_nodes": int(global_growth.get("expert_nodes") or 0),
            "federation_ready": bool(global_growth.get("federation_ready")),
            "mutates_production": bool(global_growth.get("mutates_production")),
        },
        "federation": {
            "packet_count": int(federated_packet_count or 0),
            "latest_packet_id": (latest_packet or {}).get("packet_id"),
            "latest_prior_update_id": (
                ((latest_packet or {}).get("learning_metadata") or {}).get("prior_update_id")
                or ((latest_packet or {}).get("route_metadata") or {}).get("prior_update_id")
            ),
            "active_route_mutation_allowed": bool((latest_packet or {}).get("active_route_mutation_allowed")),
        },
        "production_spine": {
            "packet_count": int(production_spine.get("packet_count") or 0),
            "latest_packet_signature": latest_production_packet.get("packet_signature"),
            "active_route_mutation_allowed": bool(latest_production_packet.get("active_route_mutation_allowed")),
        },
        "forward_pass_coverage": forward_pass_coverage,
        "nexusbrain_runtime_cycle": nexusbrain_runtime_cycle,
        "failure_learning": failure_learning,
        "evidence_refs": evidence_refs,
        "privacy_boundary": "sanitized-digests-refs-counts-and-status-only-no-raw-prompts-outputs-session-ids",
    }


