def _compact_self_repair_ao_guard(guard: dict[str, Any] | None) -> dict[str, Any] | None:
    if not isinstance(guard, dict):
        return None
    receipts = [
        _compact_ao_execution_receipt(receipt)
        for receipt in guard.get("receipts") or []
        if isinstance(receipt, dict)
    ]
    return {
        "surface_id": "release-wrapper-ao-guard",
        "status_label": str(guard.get("status_label") or "LOCKED CANON"),
        "update_id": str(guard.get("update_id") or ""),
        "action": str(guard.get("action") or ""),
        "endpoint_ref": guard.get("endpoint_ref"),
        "created_at": guard.get("created_at"),
        "session_ref_digest": guard.get("session_ref_digest"),
        "required_aos": [str(item) for item in guard.get("required_aos") or []],
        "received_aos": [str(item) for item in guard.get("received_aos") or []],
        "missing_aos": [str(item) for item in guard.get("missing_aos") or []],
        "passed": bool(guard.get("passed")),
        "receipt_refs": [str(item) for item in guard.get("receipt_refs") or []],
        "receipts": receipts,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "mutation_boundary": "admin-approved-shadow-safe-file-only-no-active-production-mutation",
        "privacy_boundary": "sanitized-ao-receipts-only-no-raw-prompts-outputs-session-ids-or-artifact-paths",
    }


def _compact_release_readiness_runner_action(result: dict[str, Any]) -> dict[str, Any]:
    linked_eval_replay = (
        result.get("linked_eval_replay") if isinstance(result.get("linked_eval_replay"), dict) else None
    )
    linked_queue = (
        result.get("linked_improvement_queue")
        if isinstance(result.get("linked_improvement_queue"), dict)
        else None
    )
    self_repair = (
        result.get("release_wrapper_self_repair")
        if isinstance(result.get("release_wrapper_self_repair"), dict)
        else None
    )
    ao_guard = _compact_self_repair_ao_guard(
        result.get("release_wrapper_ao_guard")
        if isinstance(result.get("release_wrapper_ao_guard"), dict)
        else None
    )
    compact = {
        "surface_id": str(result.get("surface_id") or "autonomous-updates"),
        "status": str(result.get("status") or ("passed" if result.get("passed") is True else "recorded")),
        "update_id": _safe_ref(str(result.get("update_id") or "")),
        "operator_approved": bool(result.get("operator_approved")),
        "active_production_mutated": bool(result.get("active_production_mutated")),
        "raw_content_included": False,
        "release_wrapper_ao_guard": ao_guard,
    }
    if linked_eval_replay is not None:
        compact["linked_eval_replay"] = {
            "run_id": linked_eval_replay.get("run_id"),
            "suite_id": linked_eval_replay.get("suite_id"),
            "status": linked_eval_replay.get("status"),
            "promotion_allowed": bool(linked_eval_replay.get("promotion_allowed")),
            "operator_approved": bool(linked_eval_replay.get("operator_approved")),
            "evidence_refs": [str(item) for item in linked_eval_replay.get("evidence_refs") or []],
        }
    if linked_queue is not None:
        compact["linked_improvement_queue"] = {
            "status": linked_queue.get("status"),
            "queue_status": linked_queue.get("queue_status"),
            "target_status": linked_queue.get("target_status"),
        }
    if self_repair is not None:
        compact["release_wrapper_self_repair"] = {
            "repair_run_id": self_repair.get("repair_run_id"),
            "action": self_repair.get("action"),
            "status": self_repair.get("status"),
            "evidence_refs": [str(item) for item in self_repair.get("evidence_refs") or []],
            "operation_receipt": self_repair.get("operation_receipt")
            if isinstance(self_repair.get("operation_receipt"), dict)
            else None,
            "active_production_mutated": bool(self_repair.get("active_production_mutated")),
            "raw_content_included": False,
        }
    for key in (
        "evidence_ref",
        "artifact_path",
        "safe_file_path",
        "approval_ref",
        "rollback_plan",
        "reason",
    ):
        if result.get(key):
            compact[key] = str(result.get(key))
    if result.get("passed") is not None:
        compact["passed"] = bool(result.get("passed"))
    if result.get("rollback_restored") is not None:
        compact["rollback_restored"] = bool(result.get("rollback_restored"))
    if isinstance(result.get("test_evidence_refs"), list):
        compact["test_evidence_refs"] = [str(item) for item in result.get("test_evidence_refs") or []]
    if isinstance(result.get("diff_summary"), dict):
        compact["diff_summary"] = {
            "unsafe_change_count": int((result.get("diff_summary") or {}).get("unsafe_change_count") or 0),
            "changed_file_count": int((result.get("diff_summary") or {}).get("changed_file_count") or 0),
        }
    if isinstance(result.get("sandbox"), dict):
        compact["sandbox"] = {
            "mode": (result.get("sandbox") or {}).get("mode"),
            "active_project_root_mutated": bool((result.get("sandbox") or {}).get("active_project_root_mutated")),
        }
    return compact


def _compact_ao_execution_receipt(receipt: dict[str, Any]) -> dict[str, Any]:
    return {
        "surface_id": str(receipt.get("surface_id") or "ao-execution-receipt"),
        "execution_id": str(receipt.get("execution_id") or ""),
        "ao_name": str(receipt.get("ao_name") or ""),
        "trace_ref": str(receipt.get("trace_ref") or ""),
        "session_ref_digest": receipt.get("session_ref_digest"),
        "selected_expert": receipt.get("selected_expert"),
        "selected_teacher_ref": receipt.get("selected_teacher_ref"),
        "wrapper_mode": receipt.get("wrapper_mode"),
        "input_contract": receipt.get("input_contract"),
        "consumed_refs": [str(item) for item in receipt.get("consumed_refs") or []],
        "direct_local_state_reads": list(receipt.get("direct_local_state_reads") or []),
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "plan": receipt.get("plan") if isinstance(receipt.get("plan"), dict) else {},
        "created_at": receipt.get("created_at"),
    }


def _self_repair_status(action: str, result: dict[str, Any]) -> str:
    status = str(result.get("status") or "")
    if status:
        return status
    if action == "sandbox_tests" and result.get("passed") is True:
        return "passed"
    return "recorded"


def _self_repair_sandbox_boundary_ok(action: str, result: dict[str, Any]) -> bool:
    if action == "sandbox_tests":
        sandbox = result.get("sandbox") if isinstance(result.get("sandbox"), dict) else {}
        diff_summary = result.get("diff_summary") if isinstance(result.get("diff_summary"), dict) else {}
        return (
            result.get("passed") is True
            and sandbox.get("active_project_root_mutated") is False
            and int(diff_summary.get("unsafe_change_count") or 0) == 0
        )
    if action == "apply":
        return result.get("status") == "applied-shadow-safe-file" and result.get("active_production_mutated") is False
    if action == "rollback":
        return result.get("status") == "rolled-back" and result.get("rollback_restored") is True
    if action == "admin_approval":
        return result.get("status") == "admin-approved"
    return _self_repair_active_production_mutated(result) is False


def _self_repair_sandbox_evidence_refs(result: dict[str, Any]) -> list[str]:
    refs = _compact_refs(result, ["evidence_ref", "status"])
    if result.get("safe_file_path"):
        refs.append(f"safe_file_path_digest::sha256:{_privacy_digest(str(result.get('safe_file_path')))}")
    if result.get("rollback_plan"):
        refs.append(f"rollback_plan_digest::sha256:{_privacy_digest(str(result.get('rollback_plan')))}")
    refs.extend(str(item) for item in result.get("test_evidence_refs") or [] if str(item or ""))
    return _dedupe_strings(refs)


def _self_repair_authority_sandbox_state(action: str, result: dict[str, Any]) -> str:
    sandbox = result.get("sandbox") if isinstance(result.get("sandbox"), dict) else {}
    if sandbox.get("mode"):
        return str(sandbox.get("mode"))
    for test_result in result.get("test_results") or []:
        if isinstance(test_result, dict) and test_result.get("sandbox_mode"):
            return str(test_result.get("sandbox_mode"))
    if action == "admin_approval":
        return "ao-guarded-admin-control-plane"
    if action == "rollback":
        return "safe-file-rollback"
    return "ao-guarded-release-wrapper-control-plane"


def _self_repair_operator_approved(
    action: str,
    proposal: dict[str, Any] | None,
    result: dict[str, Any],
) -> bool:
    return bool(
        result.get("operator_approved")
        or (proposal or {}).get("operator_approved")
        or action in {"admin_approval", "sandbox_tests", "apply", "rollback"}
    )


def _self_repair_rollback_available(proposal: dict[str, Any] | None, result: dict[str, Any]) -> bool:
    return bool(
        str(result.get("rollback_plan") or "").strip()
        or result.get("rollback_restored") is True
        or str((proposal or {}).get("rollback_plan") or "").strip()
    )


def _self_repair_authority_rollback_ref(proposal: dict[str, Any] | None, result: dict[str, Any]) -> str:
    safe_file_path = str(result.get("safe_file_path") or "").strip()
    if safe_file_path:
        return f"safe_file_path_digest::sha256:{_privacy_digest(safe_file_path)}"
    rollback_plan = str(result.get("rollback_plan") or (proposal or {}).get("rollback_plan") or "").strip()
    if rollback_plan:
        return f"rollback_plan_digest::sha256:{_privacy_digest(rollback_plan)}"
    return ""


def _self_repair_active_production_mutated(result: dict[str, Any]) -> bool:
    if "active_production_mutated" in result:
        return bool(result.get("active_production_mutated"))
    sandbox = result.get("sandbox") if isinstance(result.get("sandbox"), dict) else {}
    return bool(sandbox.get("active_production_mutated"))


def _self_repair_evidence_refs(result: dict[str, Any], *, endpoint_ref: str | None = None) -> list[str]:
    refs: list[str] = []
    if endpoint_ref:
        refs.append(str(endpoint_ref))
    for key in ("approval_ref", "evidence_ref", "update_id"):
        value = str(result.get(key) or "").strip()
        if value:
            refs.append(f"{key}::{value}")
    for key in ("artifact_path", "safe_file_path"):
        value = str(result.get(key) or "").strip()
        if value:
            refs.append(f"{key}_digest::sha256:{_privacy_digest(value)}")
    for ref in result.get("test_evidence_refs") or []:
        value = str(ref or "").strip()
        if value:
            refs.append(value)
    replay = result.get("linked_eval_replay") if isinstance(result.get("linked_eval_replay"), dict) else {}
    for key in ("run_id", "suite_id"):
        value = str(replay.get(key) or "").strip()
        if value:
            refs.append(f"linked_eval_replay.{key}::{value}")
    linked_queue = result.get("linked_improvement_queue") if isinstance(result.get("linked_improvement_queue"), dict) else {}
    queue_id = str(linked_queue.get("queue_id") or "").strip()
    if queue_id:
        refs.append(f"self_improvement_queue::{queue_id}")
    guard = result.get("release_wrapper_ao_guard") if isinstance(result.get("release_wrapper_ao_guard"), dict) else {}
    for ref in guard.get("receipt_refs") or []:
        value = str(ref or "").strip()
        if value:
            refs.append(f"ao_guard::{value}")
    compact: list[str] = []
    seen: set[str] = set()
    for ref in refs:
        if ref and ref not in seen:
            compact.append(ref)
            seen.add(ref)
    return compact


def _strip_developmental_artifact_path(value: Any) -> Any:
    if isinstance(value, dict):
        return {
            str(key): _strip_developmental_artifact_path(item)
            for key, item in value.items()
            if key != "artifact_path"
        }
    if isinstance(value, list):
        return [_strip_developmental_artifact_path(item) for item in value]
    return value


def _compact_developmental_release_contract_assessment(assessment: Any) -> dict[str, Any] | None:
    if not isinstance(assessment, dict):
        return None
    body = _strip_developmental_artifact_path(
        assessment.get("body_schema_snapshot") if isinstance(assessment.get("body_schema_snapshot"), dict) else {}
    )
    frame = _strip_developmental_artifact_path(
        assessment.get("reference_frame") if isinstance(assessment.get("reference_frame"), dict) else {}
    )
    simulation = _strip_developmental_artifact_path(
        assessment.get("simulation") if isinstance(assessment.get("simulation"), dict) else {}
    )
    causal = _strip_developmental_artifact_path(
        assessment.get("causal_intervention") if isinstance(assessment.get("causal_intervention"), dict) else {}
    )
    candidate = _strip_developmental_artifact_path(
        assessment.get("growth_candidate") if isinstance(assessment.get("growth_candidate"), dict) else {}
    )
    promotion = _strip_developmental_artifact_path(
        assessment.get("promotion_case") if isinstance(assessment.get("promotion_case"), dict) else {}
    )
    dream_request = {
        "surface_id": "developmental-dream-request",
        "simulation_id": simulation.get("simulation_id"),
        "status": simulation.get("status") or "blocked",
        "seed_trace_ref": simulation.get("seed_trace_ref"),
        "expected_outcomes": list(simulation.get("expected_outcomes") or []),
        "evidence_ref_count": len(simulation.get("evidence_refs") or []),
        "learned_world_model_claim": bool(simulation.get("learned_world_model_claim")),
        "production_action_allowed": bool(simulation.get("production_action_allowed")),
        "raw_content_included": False,
    }
    causal_test_request = {
        "surface_id": "developmental-causal-test-request",
        "intervention_id": causal.get("intervention_id"),
        "status": causal.get("status") or "blocked",
        "variable": causal.get("variable"),
        "causal_confidence": causal.get("causal_confidence") or "unknown",
        "evidence_ref_count": len(causal.get("evidence_refs") or []),
        "production_action_allowed": bool(causal.get("production_action_allowed")),
        "raw_content_included": False,
    }
    return {
        "request_id": assessment.get("request_id"),
        "task_ref": assessment.get("task_ref"),
        "status": assessment.get("status") or "blocked",
        "body_schema_snapshot": body,
        "reference_frame_updates": [frame] if frame else [],
        "dream_request": dream_request,
        "causal_test_request": causal_test_request,
        "growth_archive_candidate": candidate,
        "promotion_tribunal_case": promotion,
        "production_mutation_allowed": bool(assessment.get("production_mutation_allowed")),
        "raw_content_included": False,
    }


def _developmental_release_contract_assessment_from_interactions(
    interactions: list[dict[str, Any]],
) -> dict[str, Any] | None:
    for interaction in interactions:
        compact = interaction.get("developmental_release_contract_assessment")
        if isinstance(compact, dict):
            return compact
    return None


