def _developmental_release_contract_summary(
    compact_assessment: dict[str, Any] | None,
    *,
    session_ref_digest: str | None = None,
) -> dict[str, Any]:
    if not isinstance(compact_assessment, dict):
        return _empty_developmental_release_contract(session_ref_digest=session_ref_digest)
    latest_status = str(compact_assessment.get("status") or "blocked")
    request_id = compact_assessment.get("request_id")
    growth_candidate = (
        compact_assessment.get("growth_archive_candidate")
        if isinstance(compact_assessment.get("growth_archive_candidate"), dict)
        else {}
    )
    promotion_case = (
        compact_assessment.get("promotion_tribunal_case")
        if isinstance(compact_assessment.get("promotion_tribunal_case"), dict)
        else {}
    )
    evidence_refs = _dedupe_strings(
        [
            "/ops/brain/canon/developmental-cortex",
            "/ops/brain/developmental-cortex/assess",
            "/ops/wrapper/release-runtime",
            f"developmental-cortex::{_safe_ref(str(request_id))}" if request_id else "",
            (
                f"growth-candidate::{_safe_ref(str(growth_candidate.get('candidate_id')))}"
                if growth_candidate.get("candidate_id")
                else ""
            ),
            (
                f"promotion-case::{_safe_ref(str(promotion_case.get('case_id')))}"
                if promotion_case.get("case_id")
                else ""
            ),
        ]
    )
    blockers: list[str] = []
    if latest_status != "shadow-ready":
        blockers.append("developmental_release_contract_latest_status_not_shadow_ready")
    if not compact_assessment.get("reference_frame_updates"):
        blockers.append("developmental_release_contract_reference_frame_missing")
    if not growth_candidate.get("candidate_id"):
        blockers.append("developmental_release_contract_growth_candidate_missing")
    if not promotion_case.get("case_id"):
        blockers.append("developmental_release_contract_promotion_case_missing")
    return {
        "schema_version": "nexusnet-developmental-release-contract-v1",
        "surface_id": "developmental-release-contract",
        "authority": "NexusBrain",
        "status_label": "LOCKED CANON",
        "runtime_state": "live-bound" if not blockers else "degraded",
        "latest_status": latest_status,
        "session_ref_digest": session_ref_digest,
        "latest_assessment_ref": request_id,
        "task_ref": compact_assessment.get("task_ref"),
        "canonical_output_names": list(DEVELOPMENTAL_RELEASE_CONTRACT_OUTPUT_NAMES),
        "canonical_output_count": len(DEVELOPMENTAL_RELEASE_CONTRACT_OUTPUT_NAMES),
        "body_schema_snapshot": compact_assessment.get("body_schema_snapshot") or {},
        "reference_frame_updates": compact_assessment.get("reference_frame_updates") or [],
        "dream_request": compact_assessment.get("dream_request") or {},
        "causal_test_request": compact_assessment.get("causal_test_request") or {},
        "growth_archive_candidate": growth_candidate,
        "promotion_tribunal_case": promotion_case,
        "blockers": blockers,
        "evidence_refs": evidence_refs,
        "raw_content_included": False,
        "active_production_mutation_allowed": False,
        "privacy_boundary": (
            "canonical-developmental-ids-statuses-counts-and-digested-refs-only-no-prompts-outputs-session-ids-or-local-paths"
        ),
        "mutation_boundary": "release-contract-projection-only-shadow-developmental-requests-no-production-mutation",
        "source_documents": list(CANON_CONTRACT_SOURCE_REFS),
    }


def _restore_developmental_release_contract(
    contract: Any,
    *,
    session_ref_digest: str | None = None,
) -> dict[str, Any]:
    if not isinstance(contract, dict):
        return _empty_developmental_release_contract(session_ref_digest=session_ref_digest)
    restored = _strip_developmental_artifact_path(json.loads(json.dumps(contract)))
    restored["session_ref_digest"] = session_ref_digest
    restored["raw_content_included"] = False
    restored["active_production_mutation_allowed"] = False
    restored.setdefault("canonical_output_names", list(DEVELOPMENTAL_RELEASE_CONTRACT_OUTPUT_NAMES))
    restored.setdefault("canonical_output_count", len(DEVELOPMENTAL_RELEASE_CONTRACT_OUTPUT_NAMES))
    restored.setdefault(
        "privacy_boundary",
        "canonical-developmental-ids-statuses-counts-and-digested-refs-only-no-prompts-outputs-session-ids-or-local-paths",
    )
    return restored


def _compact_session_lifecycle_interaction(interaction: Any) -> dict[str, Any] | None:
    if not isinstance(interaction, dict):
        return None
    allowed_keys = [
        "trace_id",
        "session_ref_digest",
        "source_model",
        "expert_node",
        "selected_ao",
        "knowledge_ref",
        "hive_run_id",
        "federated_packet_id",
        "federated_prior_update_id",
        "production_spine_packet_signature",
        "cache_ledger_entry_id",
        "runtime_scorecard_id",
        "improvement_queue_id",
        "dream_research_episode_id",
        "nexusbrain_runtime_cycle_receipt_id",
        "nexusbrain_runtime_cycle_status",
        "autonomous_update_lifecycle_run_id",
        "autonomous_update_lifecycle_status",
        "autonomous_update_lifecycle_update_id",
        "developmental_cortex_assessment_ref",
        "developmental_cortex_status",
        "developmental_cortex_growth_candidate_ref",
        "developmental_cortex_promotion_case_ref",
        "ao_execution_receipt_id",
        "ao_execution_trace_ref",
        "domain_ao_routing",
        "created_at",
    ]
    compact = {key: interaction.get(key) for key in allowed_keys if interaction.get(key) is not None}
    compact["raw_content_included"] = False
    return compact


def _session_lifecycle_steps_from_readiness(readiness: dict[str, Any]) -> list[dict[str, Any]]:
    readiness_checks = readiness.get("readiness_checks") if isinstance(readiness.get("readiness_checks"), list) else []
    steps: list[dict[str, Any]] = []
    for index, check in enumerate(readiness_checks, start=1):
        if not isinstance(check, dict):
            continue
        step = {
            "step_id": str(check.get("check_id") or f"release-wrapper-step-{index}"),
            "order": index,
            "label": str(check.get("label") or "Release wrapper lifecycle step"),
            "status": "pass" if check.get("status") == "pass" else "blocked",
            "evidence_refs": [
                str(ref)
                for ref in (check.get("evidence_refs") if isinstance(check.get("evidence_refs"), list) else [])
                if str(ref or "").strip()
            ],
            "blocker": "" if check.get("status") == "pass" else str(check.get("blocker") or "evidence missing"),
        }
        if "release_mutation_allowed" in check:
            step["release_mutation_allowed"] = bool(check.get("release_mutation_allowed"))
        if "buyer_release_allowed" in check:
            step["buyer_release_allowed"] = bool(check.get("buyer_release_allowed"))
        steps.append(step)
    return steps


