def _native_runtime_growth_governance_summary(
    *,
    autonomous_updates: dict[str, Any],
    dream_queue: dict[str, Any] | None = None,
    release_readiness_evidence_runner: dict[str, Any] | None = None,
    operator_action_lane: dict[str, Any] | None = None,
) -> dict[str, Any]:
    proposals = autonomous_updates.get("proposals") if isinstance(autonomous_updates.get("proposals"), list) else []
    native_proposal = next(
        (
            proposal
            for proposal in proposals
            if isinstance(proposal, dict)
            and (
                ((proposal.get("metadata") or {}).get("native_hive_runtime_growth") is True)
                or (((proposal.get("metadata") or {}).get("safe_payload") or {}).get("native_hive_runtime_growth") is True)
            )
        ),
        None,
    )
    native_proposal = native_proposal if isinstance(native_proposal, dict) else {}
    metadata = native_proposal.get("metadata") if isinstance(native_proposal.get("metadata"), dict) else {}
    safe_payload = metadata.get("safe_payload") if isinstance(metadata.get("safe_payload"), dict) else {}
    dream_queue = dream_queue if isinstance(dream_queue, dict) else {}
    latest_item = dream_queue.get("latest_item") if isinstance(dream_queue.get("latest_item"), dict) else {}
    latest_item_metadata = latest_item.get("metadata") if isinstance(latest_item.get("metadata"), dict) else {}
    operator_action_lane = operator_action_lane if isinstance(operator_action_lane, dict) else {}
    lane_statuses = (
        operator_action_lane.get("latest_action_statuses")
        if isinstance(operator_action_lane.get("latest_action_statuses"), dict)
        else {}
    )
    latest_eval_replay = (
        native_proposal.get("latest_eval_replay")
        if isinstance(native_proposal.get("latest_eval_replay"), dict)
        else _latest_proposal_field(autonomous_updates, "latest_eval_replay")
    )
    latest_sandbox = (
        native_proposal.get("latest_sandbox_test_evidence")
        if isinstance(native_proposal.get("latest_sandbox_test_evidence"), dict)
        else autonomous_updates.get("latest_sandbox_test_evidence")
        if isinstance(autonomous_updates.get("latest_sandbox_test_evidence"), dict)
        else None
    )
    latest_applied = (
        autonomous_updates.get("latest_applied") if isinstance(autonomous_updates.get("latest_applied"), dict) else None
    )
    latest_rollback = (
        autonomous_updates.get("latest_rollback") if isinstance(autonomous_updates.get("latest_rollback"), dict) else None
    )
    release_readiness_evidence_runner = (
        release_readiness_evidence_runner if isinstance(release_readiness_evidence_runner, dict) else {}
    )
    latest_runner = (
        release_readiness_evidence_runner.get("latest_run")
        if isinstance(release_readiness_evidence_runner.get("latest_run"), dict)
        else {}
    )
    action_statuses = {
        "proposal": lane_statuses.get("proposal") or native_proposal.get("status") or "not-generated",
        "admin_approval": lane_statuses.get("admin_approval")
        or ("admin-approved" if native_proposal.get("operator_approved") is True else "pending-admin-approval"),
        "shadow_eval_replay": lane_statuses.get("shadow_eval_replay")
        or ((latest_eval_replay or {}).get("status") if isinstance(latest_eval_replay, dict) else None)
        or "not-run",
        "sandbox_tests": lane_statuses.get("sandbox_tests")
        or ((latest_sandbox or {}).get("status") if isinstance(latest_sandbox, dict) else None)
        or "not-run",
        "apply": lane_statuses.get("apply")
        or ((latest_applied or {}).get("status") if isinstance(latest_applied, dict) else None)
        or "not-applied",
        "rollback": lane_statuses.get("rollback")
        or ((latest_rollback or {}).get("status") if isinstance(latest_rollback, dict) else None)
        or "not-rolled-back",
        "readiness_runner": lane_statuses.get("readiness_runner")
        or release_readiness_evidence_runner.get("latest_status")
        or "not-run",
    }
    if action_statuses["rollback"] == "rolled-back":
        status = "rolled-back"
    elif action_statuses["apply"] == "applied-shadow-safe-file":
        status = "applied-shadow-safe-file"
    elif action_statuses["sandbox_tests"] == "passed":
        status = "sandbox-passed"
    elif action_statuses["admin_approval"] == "admin-approved":
        status = "admin-approved"
    elif action_statuses["proposal"] in {"proposed", "blocked", "shadow-approved"}:
        status = str(action_statuses["proposal"])
    elif latest_item_metadata.get("native_hive_runtime_growth") is True:
        status = "queued"
    else:
        status = "not-triggered"
    active_production_mutated = any(
        bool(record.get("active_production_mutated"))
        for record in (latest_sandbox, latest_applied, latest_rollback, latest_runner)
        if isinstance(record, dict)
    )
    runtime_growth_receipt_id = (
        metadata.get("runtime_growth_receipt_id")
        or safe_payload.get("runtime_growth_receipt_id")
        or latest_item_metadata.get("runtime_growth_receipt_id")
    )
    return {
        "surface_id": "native-runtime-growth-governance",
        "status_label": "LOCKED CANON",
        "status": status,
        "native_hive_runtime_growth": bool(
            metadata.get("native_hive_runtime_growth")
            or safe_payload.get("native_hive_runtime_growth")
            or latest_item_metadata.get("native_hive_runtime_growth")
        ),
        "direct_nexusbrain_generate": bool(
            metadata.get("direct_nexusbrain_generate")
            or safe_payload.get("direct_nexusbrain_generate")
            or latest_item_metadata.get("direct_nexusbrain_generate")
        ),
        "proposal_update_id": native_proposal.get("update_id"),
        "runtime_growth_receipt_id": runtime_growth_receipt_id,
        "runtime_growth_federated_packet_id": (
            metadata.get("runtime_growth_federated_packet_id")
            or safe_payload.get("runtime_growth_federated_packet_id")
            or latest_item_metadata.get("runtime_growth_federated_packet_id")
        ),
        "hive_run_id": safe_payload.get("hive_run_id") or metadata.get("hive_run_id") or latest_item_metadata.get("hive_run_id"),
        "failure_class": metadata.get("failure_class") or safe_payload.get("failure_class"),
        "policy_block_class": metadata.get("policy_block_class") or safe_payload.get("policy_block_class"),
        "confidence_bucket": metadata.get("confidence_bucket") or safe_payload.get("confidence_bucket"),
        "latest_action_statuses": action_statuses,
        "latest_eval_replay_status": action_statuses["shadow_eval_replay"],
        "latest_sandbox_status": action_statuses["sandbox_tests"],
        "latest_apply_status": action_statuses["apply"],
        "latest_rollback_status": action_statuses["rollback"],
        "latest_runner_status": action_statuses["readiness_runner"],
        "latest_runner_run_id": latest_runner.get("run_id"),
        "active_production_mutated": active_production_mutated,
        "active_production_mutation_allowed": False,
        "raw_content_included": False,
        "privacy_boundary": "native-growth-governance-uses-statuses-digests-and-receipt-refs-only-no-raw-prompts-outputs-session-ids",
    }


def _native_runtime_growth_governance_ready(summary: dict[str, Any]) -> bool:
    if not isinstance(summary, dict):
        return True
    if summary.get("native_hive_runtime_growth") is not True:
        return True
    statuses = summary.get("latest_action_statuses") if isinstance(summary.get("latest_action_statuses"), dict) else {}
    return (
        summary.get("status") == "rolled-back"
        and statuses.get("admin_approval") == "admin-approved"
        and statuses.get("shadow_eval_replay") == "passed-shadow"
        and statuses.get("sandbox_tests") == "passed"
        and statuses.get("apply") == "applied-shadow-safe-file"
        and statuses.get("rollback") == "rolled-back"
        and statuses.get("readiness_runner") == "completed"
        and summary.get("active_production_mutated") is False
        and summary.get("raw_content_included") is False
    )


def _native_runtime_growth_governance_evidence_refs(summary: dict[str, Any]) -> list[str]:
    if not isinstance(summary, dict):
        return ["native-runtime-growth::not-triggered"]
    refs = [f"native-growth-status::{summary.get('status') or 'not-triggered'}"]
    for key, prefix in (
        ("proposal_update_id", "proposal"),
        ("runtime_growth_receipt_id", "runtime-growth-receipt"),
        ("runtime_growth_federated_packet_id", "federated-packet"),
        ("hive_run_id", "hive-forward"),
        ("latest_runner_run_id", "readiness-runner"),
    ):
        value = summary.get(key)
        if value:
            refs.append(f"{prefix}::{_safe_ref(str(value))}")
    return list(dict.fromkeys(refs))


